/**
 * 安全获取 totalFloorCount（带回退）
 * 优先从引擎状态读取，回退到直接读取聊天变量
 */
function getSafeTotalFloorCount() {
  // 方案1：从引擎状态读取
  const engineState = getEngineState();
  if (engineState?.totalFloorCount !== undefined) {
    return engineState.totalFloorCount;
  }

  // 方案2：直接读取聊天变量
  try {
    const ctx = SillyTavern.getContext();
    const value = ctx?.chatMetadata?.variables?.AutoTask?.totalFloorCount;
    if (value !== undefined && value !== null) {
      return parseInt(value, 10) || 0;
    }
  } catch (e) {
    console.warn('[AutoTask] 读取 totalFloorCount 失败:', e);
  }

  return 0;
}

/**
 * 安全获取 lastSummarizedId（带回退）
 */
function getSafeLastSummarizedId() {
  // 方案1：从引擎状态读取
  const engineState = getEngineState();
  if (engineState?.lastSummarizedId !== undefined) {
    return engineState.lastSummarizedId;
  }

  // 方案2：直接读取聊天变量
  try {
    const ctx = SillyTavern.getContext();
    const value = ctx?.chatMetadata?.variables?.AutoTask?.lastSummarizedId;
    if (value !== undefined && value !== null) {
      return parseInt(value, 10);
    }
  } catch (e) {
    console.warn('[AutoTask] 读取 lastSummarizedId 失败:', e);
  }

  // 方案3：尝试读取小白X的摘要数据（兼容）
  try {
    const ctx = SillyTavern.getContext();
    const xbLastId = ctx?.chatMetadata?.extensions?.LittleWhiteBox?.storySummary?.lastSummarizedMesId;
    if (xbLastId !== undefined && xbLastId >= 0) {
      return xbLastId;
    }
  } catch (e) {}

  return -1;
}

