/**
 * 缓存 AutoTask 引擎所在的 window
 */
let _autoTaskWindowCache = null;

/**
 * 查找 AutoTask 引擎所在的 window
 */
function findAutoTaskWindow() {
  // 如果缓存有效，直接返回
  if (_autoTaskWindowCache && _autoTaskWindowCache.AutoTask) {
    return _autoTaskWindowCache;
  }

  // 重新查找
  _autoTaskWindowCache = null;

  try {
    // 1. 当前窗口
    if (window.AutoTask) {
      _autoTaskWindowCache = window;
      return window;
    }

    // 2. 父窗口
    if (window.parent?.AutoTask) {
      _autoTaskWindowCache = window.parent;
      return window.parent;
    }

    // 3. 顶层窗口
    if (window.top?.AutoTask) {
      _autoTaskWindowCache = window.top;
      return window.top;
    }

    // 4. 父窗口的所有 frames（平级 iframe）
    if (window.parent?.frames) {
      for (let i = 0; i < window.parent.frames.length; i++) {
        try {
          if (window.parent.frames[i]?.AutoTask) {
            _autoTaskWindowCache = window.parent.frames[i];
            return window.parent.frames[i];
          }
        } catch (e) {
          // 跨域访问会报错，忽略
        }
      }
    }

    return null;
  } catch {
    return null;
  }
}

/**
 * 检测MVU是否可用
 */
function isMvuAvailable() {
  try {
    // 先在 AutoTask 所在的 window 找
    const autoTaskWin = findAutoTaskWindow();
    if (autoTaskWin?.Mvu) return true;

    // 再检查其他常见位置
    if (window.Mvu) return true;
    if (window.parent?.Mvu) return true;
    if (window.top?.Mvu) return true;

    // 检查平级 frames
    if (window.parent?.frames) {
      for (let i = 0; i < window.parent.frames.length; i++) {
        try {
          if (window.parent.frames[i]?.Mvu) return true;
        } catch (e) {}
      }
    }

    return false;
  } catch {
    return false;
  }
}

/**
 * 检测 MVU 是否启用了额外模型解析（与 AutoTask 冲突）
 * @returns {'ok'|'conflict'|'unavailable'} 状态
 */
function getMvuConflictStatus() {
  try {
    if (!isMvuAvailable()) {
      return 'unavailable';
    }

    // 尝试从多个位置获取 MVU 设置
    const autoTaskWin = findAutoTaskWindow();
    const mvuSettings =
      autoTaskWin?.SillyTavern?.extensionSettings?.mvu_settings ||
      window.SillyTavern?.extensionSettings?.mvu_settings ||
      window.parent?.SillyTavern?.extensionSettings?.mvu_settings;

    if (mvuSettings?.更新方式 === '额外模型解析') {
      return 'conflict';
    }

    return 'ok';
  } catch (e) {
    console.warn('[AutoTask] 检测MVU设置时出错:', e);
    return 'unavailable';
  }
}

