/**
 * 扁平化变量对象为路径列表
 * @param obj - 要扁平化的对象
 * @param prefix - 路径前缀
 * @returns Array<{path: string, value: any}>
 */
function flattenVariables(obj, prefix = '') {
  const result = [];

  if (obj === null || obj === undefined) {
    return result;
  }

  for (const key of Object.keys(obj)) {
    const path = prefix ? `${prefix}.${key}` : key;
    const value = obj[key];

    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      // 递归处理嵌套对象
      result.push(...flattenVariables(value, path));
    } else {
      // 基本类型或数组，直接添加
      result.push({ path, value });
    }
  }

  return result;
}

