/**
 * 将条件配置翻译为中文可读格式
 * @param condition - ConditionConfig对象
 */
function translateCondition(condition) {
  if (!condition || !condition.groups || condition.groups.length === 0) {
    return '（无条件）';
  }

  const groupTexts = condition.groups.map(group => {
    const condTexts = group.conditions.map(cond => {
      const op = cond.operator;
      let opText = op;
      if (op === 'contains') opText = '包含';
      else if (op === 'not_contains') opText = '不包含';

      return `${cond.variable} ${opText} ${cond.value}`;
    });

    let groupText = condTexts.join(group.relation === 'AND' ? ' 且 ' : ' 或 ');
    if (condTexts.length > 1) {
      groupText = `(${groupText})`;
    }
    if (group.not) {
      groupText = `非${groupText}`;
    }
    return groupText;
  });

  return groupTexts.join(condition.groupRelation === 'AND' ? ' 且 ' : ' 或 ');
}

/**
 * 格式化数字显示（添加千位分隔符）
 */
function formatNumber(num) {
  if (num === null || num === undefined) return '-';
  return num.toLocaleString();
}

/**
 * 安全地获取嵌套属性
 */
function getNestedValue(obj, path, defaultValue = undefined) {
  if (!obj || !path) return defaultValue;
  const keys = path.split('.');
  let current = obj;
  for (const key of keys) {
    if (current === null || current === undefined) return defaultValue;
    current = current[key];
  }
  return current !== undefined ? current : defaultValue;
}

/**
 * 安全地设置嵌套属性
 */
function setNestedValue(obj, path, value) {
  if (!obj || !path) return;
  const keys = path.split('.');
  let current = obj;
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    if (!(key in current) || current[key] === null) {
      current[key] = {};
    }
    current = current[key];
  }
  current[keys[keys.length - 1]] = value;
}

/**
