/**
 * 更新未保存指示器
 */
function updateDirtyIndicator() {
  const overlay = mainDoc.getElementById('at-overlay');
  if (!overlay) return;

  // 1. 在标题旁显示/隐藏红点
  const title = overlay.querySelector('.at-title');
  if (title) {
    let indicator = title.querySelector('.at-dirty-indicator');
    if (isDirty && !indicator) {
      indicator = mainDoc.createElement('span');
      indicator.className = 'at-dirty-indicator';
      title.appendChild(indicator);
    } else if (!isDirty && indicator) {
      indicator.remove();
    }
  }

  // 2. 更新底部保存按钮区域的提示（仅在创作者页）
  const saveArea = overlay.querySelector('.at-save-buttons');
  if (saveArea) {
    let dirtyHint = saveArea.querySelector('.at-dirty-hint');
    if (isDirty && !dirtyHint) {
      // 添加提示
      dirtyHint = mainDoc.createElement('span');
      dirtyHint.className = 'at-dirty-hint';
      dirtyHint.style.cssText = `
        color: var(--warning);
        font-size: 12px;
        display: flex;
        align-items: center;
        margin-right: auto;
      `;
      dirtyHint.textContent = '● 有未保存的更改';
      saveArea.insertBefore(dirtyHint, saveArea.firstChild);
    } else if (!isDirty && dirtyHint) {
      dirtyHint.remove();
    }
  }
}

