/**
 * 从角色世界书加载配置
 */
async function loadConfig() {
  // 获取角色世界书
  const charWB = getCharWorldbookNames('current');
  if (!charWB.primary) {
    throw new Error('当前角色卡未绑定主世界书');
  }

  const entries = await getWorldbook(charWB.primary);
  const configEntry = entries.find(e => e.strategy.keys.includes(CONFIG_ENTRY_KEY));

  if (!configEntry) {
    return null; // 配置不存在
  }

  try {
    return JSON.parse(configEntry.content);
  } catch (err) {
    throw new Error('配置JSON解析失败: ' + err.message);
  }
}

/**
 * 保存配置到角色世界书
 */
async function saveConfig(config) {
  const charWB = getCharWorldbookNames('current');
  if (!charWB.primary) {
    throw new Error('当前角色卡未绑定主世界书');
  }

  const entries = await getWorldbook(charWB.primary);
  const existingEntry = entries.find(e => e.strategy.keys.includes(CONFIG_ENTRY_KEY));

  if (existingEntry) {
    // 更新现有条目
    await updateWorldbookWith(charWB.primary, (entries) => {
      return entries.map(e => {
        if (e.uid === existingEntry.uid) {
          return { ...e, content: JSON.stringify(config, null, 2) };
        }
        return e;
      });
    });
  } else {
    // 创建新条目
    await createWorldbookEntries(charWB.primary, [{
      name: CONFIG_ENTRY_COMMENT,
      enabled: false,
      content: JSON.stringify(config, null, 2),
      strategy: {
        type: 'selective',
        keys: [CONFIG_ENTRY_KEY],
        keys_secondary: { logic: 'and_any', keys: [] },
        scan_depth: 'same_as_global',
      },
      position: {
        type: 'after_character_definition',
        role: 'system',
        depth: 4,
        order: 100,
      },
      probability: 100,
      recursion: { prevent_incoming: false, prevent_outgoing: false, delay_until: null },
      effect: { sticky: null, cooldown: null, delay: null },
    }]);
  }
}

async function createDefaultConfig() {
  const config = deepClone(DEFAULT_CONFIG);
  await saveConfig(config);
  return config;
}

/**
 * 从localStorage加载API预设
 */
function loadApiPresets() {
  try {
    const stored = localStorage.getItem(API_PRESETS_STORAGE_KEY);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (err) {
    console.warn('加载API预设失败:', err);
  }
  return deepClone(DEFAULT_API_PRESETS);
}

/**
 * 保存API预设到localStorage
 */
function saveApiPresets(presets) {
  localStorage.setItem(API_PRESETS_STORAGE_KEY, JSON.stringify(presets));
}

