/**
 * 创建折叠区块
 * @param options.id - 区块ID（用于记忆展开状态）
 * @param options.title - 区块标题
 * @param options.badge - 可选徽章文本
 * @param options.content - 区块内容HTML或DOM元素
 * @param options.defaultCollapsed - 默认是否折叠
 */
function buildSection(options) {
  const { id, title, badge, content, defaultCollapsed } = options;

  // 检查记忆的展开状态
  const isCollapsed = expandedSections[id] !== undefined
    ? !expandedSections[id]
    : (defaultCollapsed ?? false);

  const section = mainDoc.createElement('div');
  section.className = `at-section${isCollapsed ? ' collapsed' : ''}`;
  section.dataset.sectionId = id;

  // 构建头部
  let badgeHtml = badge ? `<span class="at-section-badge">${badge}</span>` : '';
  section.innerHTML = `
    <div class="at-section-header">
      <span class="at-section-toggle">▼</span>
      <span class="at-section-title">${title}</span>
      ${badgeHtml}
    </div>
    <div class="at-section-body"></div>
  `;

  // 填充内容
  const body = section.querySelector('.at-section-body');
  if (typeof content === 'string') {
    body.innerHTML = content;
  } else if (content && content.nodeType === 1) {
    // 使用 nodeType === 1 检查元素节点，避免跨框架 instanceof 问题
    body.appendChild(content);
  }

  // 绑定折叠切换事件
  const header = section.querySelector('.at-section-header');
  header.addEventListener('click', () => {
    section.classList.toggle('collapsed');
    expandedSections[id] = !section.classList.contains('collapsed');
  });

  return section;
}

/**
 * 创建表单输入框
 */
function buildInput(options) {
  const { label, value, placeholder, type = 'text', onChange, disabled } = options;

  const group = mainDoc.createElement('div');
  group.className = 'at-form-group';

  if (label) {
    const labelEl = mainDoc.createElement('label');
    labelEl.className = 'at-form-label';
    labelEl.textContent = label;
    group.appendChild(labelEl);
  }

  const input = mainDoc.createElement('input');
  input.type = type;
  input.className = 'at-form-input';
  input.value = value ?? '';
  if (placeholder) input.placeholder = placeholder;
  if (disabled) input.disabled = true;

  if (onChange) {
    input.addEventListener('input', (e) => onChange(e.target.value));
  }

  group.appendChild(input);
  return group;
}

/**
 * 创建表单文本域
 */
function buildTextarea(options) {
  const { label, value, placeholder, rows = 3, onChange, disabled } = options;

  const group = mainDoc.createElement('div');
  group.className = 'at-form-group';

  if (label) {
    const labelEl = mainDoc.createElement('label');
    labelEl.className = 'at-form-label';
    labelEl.textContent = label;
    group.appendChild(labelEl);
  }

  const textarea = mainDoc.createElement('textarea');
  textarea.className = 'at-form-textarea';
  textarea.rows = rows;
  textarea.value = value ?? '';
  if (placeholder) textarea.placeholder = placeholder;
  if (disabled) textarea.disabled = true;

  if (onChange) {
    textarea.addEventListener('input', (e) => onChange(e.target.value));
  }

  group.appendChild(textarea);
  return group;
}

/**
 * 创建表单下拉选择
 */
function buildSelect(options) {
  const { label, value, choices, onChange, disabled } = options;

  const group = mainDoc.createElement('div');
  group.className = 'at-form-group';

  if (label) {
    const labelEl = mainDoc.createElement('label');
    labelEl.className = 'at-form-label';
    labelEl.textContent = label;
    group.appendChild(labelEl);
  }

  const select = mainDoc.createElement('select');
  select.className = 'at-form-select';
  if (disabled) select.disabled = true;

  // choices: Array<{value: any, label: string}>
  for (const choice of choices) {
    const option = mainDoc.createElement('option');
    option.value = choice.value;
    option.textContent = choice.label;
    if (choice.value === value) option.selected = true;
    select.appendChild(option);
  }

  if (onChange) {
    select.addEventListener('change', (e) => onChange(e.target.value));
  }

  group.appendChild(select);
  return group;
}

/**
 * 创建复选框
 */
function buildCheckbox(options) {
  const { label, checked, onChange, disabled } = options;

  const wrapper = mainDoc.createElement('label');
  wrapper.className = 'at-form-checkbox';

  const input = mainDoc.createElement('input');
  input.type = 'checkbox';
  input.checked = checked ?? false;
  if (disabled) input.disabled = true;

  if (onChange) {
    input.addEventListener('change', (e) => onChange(e.target.checked));
  }

  const text = mainDoc.createElement('span');
  text.textContent = label;

  wrapper.appendChild(input);
  wrapper.appendChild(text);
  return wrapper;
}

/**
