/**
 * 创建标签列表（用于显示如触发位置、关键词等）
 */
function buildTagList(tags, options = {}) {
  const { onRemove, editable } = options;

  const container = mainDoc.createElement('div');
  container.className = 'at-flex at-gap-sm';
  container.style.flexWrap = 'wrap';

  for (const tag of tags) {
    const tagEl = mainDoc.createElement('span');
    tagEl.className = 'at-section-badge';
    tagEl.style.display = 'inline-flex';
    tagEl.style.alignItems = 'center';
    tagEl.style.gap = '4px';
    tagEl.textContent = tag;

    if (editable && onRemove) {
      const removeBtn = mainDoc.createElement('span');
      removeBtn.textContent = '×';
      removeBtn.style.cursor = 'pointer';
      removeBtn.style.marginLeft = '2px';
      removeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        onRemove(tag);
      });
      tagEl.appendChild(removeBtn);
    }

    container.appendChild(tagEl);
  }

  return container;
}

