/**
 * 标签页切换
 */
async function handleTabSwitch(targetTab) {
  if (currentTab === targetTab) return;

  // 从创作页离开时检查未保存修改
  if (currentTab === 'creator' && isDirty) {
    const confirmed = await SillyTavern.callGenericPopup(
      '有未保存的更改，切换页签将丢失修改。确定吗？',
      SillyTavern.POPUP_TYPE.CONFIRM
    );
    if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
      return;
    }
    // 用户确认，丢弃修改
    configDraft = deepClone(await loadConfig());
    isDirty = false;
  }

  // 更新标签状态
  currentTab = targetTab;

  // 更新UI（注意：从主文档查询元素）
  const overlay = mainDoc.getElementById('at-overlay');
  if (!overlay) return;

  overlay.querySelectorAll('.at-tab').forEach(tab => {
    tab.classList.toggle('active', tab.dataset.tab === targetTab);
  });

  overlay.querySelectorAll('.at-page').forEach(page => {
    page.classList.toggle('active', page.dataset.page === targetTab);
  });

  // 渲染对应页面
  renderPage(targetTab);
}

/**
 * 绑定面板事件
 */
function attachEventHandlers() {
  const overlay = mainDoc.getElementById('at-overlay');
  if (!overlay) return;

  // 遮罩点击关闭
  const mask = overlay.querySelector('#at-mask');
  if (mask) {
    mask.addEventListener('click', () => closePanel());
  }

  // 关闭按钮
  const closeBtn = overlay.querySelector('.at-close-btn');
  if (closeBtn) {
    closeBtn.addEventListener('click', () => closePanel());
  }

  // 标签页切换
  overlay.querySelectorAll('.at-tab').forEach(tab => {
    tab.addEventListener('click', () => handleTabSwitch(tab.dataset.tab));
  });

  console.log('[AutoTask] 事件已绑定');
}

