/**
 * 渲染指定页面
 */
function renderPage(tabId) {
  console.log(`[AutoTask] 渲染页面: ${tabId}`);

  const overlay = mainDoc.getElementById('at-overlay');
  if (!overlay) return;

  const pageEl = overlay.querySelector(`.at-page[data-page="${tabId}"]`);
  if (!pageEl) return;

  // 清空当前内容
  pageEl.innerHTML = '';

  // 根据页面类型渲染
