/**
 * 首页 - 系统状态区块
 */
function buildHomeStatusSection() {
  const engineState = getEngineState();
  const engineRunning = isEngineRunning();
  const activePreset = getActivePreset();

  const content = mainDoc.createElement('div');

  // 引擎状态行
  content.appendChild(buildStatusRow([
    {
      label: '引擎',
      value: engineRunning ? '✓ 运行中' : '✗ 未启动',
      status: engineRunning ? 'ok' : 'error'
    },
    {
      label: '执行',
      value: engineRunning ? (engineState.isRunning ? '执行中' : '空闲') : '-',
      status: engineRunning ? 'ok' : null
    }
  ]));

  // 配置状态行
  const hasPresets = configDraft && configDraft.presets && configDraft.presets.length > 0;
  const configOk = hasPresets && configDraft.activePresetId;

  content.appendChild(buildInfoRow(
    '配置',
    configOk ? '✓ 就绪' : (hasPresets ? '⚠ 未激活方案' : '⚠ 无方案'),
    configOk ? 'ok' : 'warn'
  ));

  // 当前方案
  content.appendChild(buildInfoRow(
    '方案',
    activePreset ? activePreset.name : (hasPresets ? '未选择' : '请创建方案')
  ));

  // MVU状态（含冲突检测）
  const mvuStatus = getMvuConflictStatus();
  let mvuText, mvuState;

  switch (mvuStatus) {
    case 'ok':
      mvuText = '✓ 可用';
      mvuState = 'ok';
      break;
    case 'conflict':
      mvuText = '⚠ 冲突：MVU启用了额外模型解析';
      mvuState = 'error';
      break;
    case 'unavailable':
    default:
      mvuText = '⚠ 不可用';
      mvuState = 'warn';
      break;
  }

  content.appendChild(buildInfoRow('MVU', mvuText, mvuState));

  // 如果有冲突，显示解决提示
  if (mvuStatus === 'conflict') {
    const conflictHint = mainDoc.createElement('div');
    conflictHint.style.cssText = `
      background: rgba(184, 106, 90, 0.15);
      border: 1px solid var(--error);
      border-radius: 4px;
      padding: 8px 10px;
      margin-top: 8px;
      font-size: 12px;
      color: var(--error);
    `;
    conflictHint.innerHTML = `
      <strong>冲突说明：</strong><br>
      MVU 和 AutoTask 的变量更新功能同时启用会导致重复触发。<br>
      <strong>解决方法：</strong>在 MVU 设置中将"更新方式"改为"随AI输出"。
    `;
    content.appendChild(conflictHint);
  }

  return buildSection({
    id: 'home_status',
    title: '系统状态',
    content: content,
    defaultCollapsed: false
  });
}

/**
 * 首页 - 周期信息区块
 */
function buildHomeCycleSection() {
  const engineState = getEngineState();
  const engineRunning = isEngineRunning();
  const activePreset = getActivePreset();

  const content = mainDoc.createElement('div');

  // 计算周期信息
  let cycleLength = 0;
  let cycleCounter = 0;
  let currentPosition = 0;

  if (engineRunning && engineState) {
    cycleLength = engineState.cycleLength || 0;
    cycleCounter = engineState.cycleCounter || 0;
    currentPosition = cycleLength > 0 ? ((cycleCounter - 1) % cycleLength) + 1 : 0;
  } else if (activePreset) {
    // 从配置计算周期长度
    const positions = [];
    for (const task of activePreset.tasks || []) {
      if (task.enabled && task.trigger?.type === 'cycle') {
        positions.push(...(task.trigger.positions || []));
      }
    }
    cycleLength = positions.length > 0 ? Math.max(...positions) : 0;
  }

  // 周期进度
  const progressText = cycleLength > 0 ? `${currentPosition}/${cycleLength}` : '-/-';
  content.appendChild(buildInfoRow('位置', progressText));

  // 进度条
  if (cycleLength > 0) {
    const progressBar = mainDoc.createElement('div');
    progressBar.style.cssText = `
      height: 8px;
      background: var(--bg-tertiary);
      border-radius: 4px;
      margin: 8px 0;
      overflow: hidden;
    `;
    const progressFill = mainDoc.createElement('div');
    const percent = cycleLength > 0 ? (currentPosition / cycleLength * 100) : 0;
    progressFill.style.cssText = `
      height: 100%;
      width: ${percent}%;
      background: var(--accent-secondary);
      transition: width 0.3s;
    `;
    progressBar.appendChild(progressFill);
    content.appendChild(progressBar);
  }

  // 下一任务提示
  if (activePreset && cycleLength > 0) {
    const nextTask = findNextCycleTask(activePreset, currentPosition, cycleLength);
    if (nextTask) {
      const roundsLeft = nextTask.position > currentPosition
        ? nextTask.position - currentPosition
        : cycleLength - currentPosition + nextTask.position;
      content.appendChild(buildInfoRow(
        '下一任务',
        `位置${nextTask.position} · ${nextTask.name} (还需${roundsLeft}轮)`
      ));
    }
  }

  // 重置按钮
  const btnGroup = mainDoc.createElement('div');
  btnGroup.className = 'at-mt-sm';
  btnGroup.appendChild(buildButton({
    text: '重置计数器',
    disabled: !engineRunning,
    title: engineRunning ? '重置周期计数器' : '引擎未启动',
    onClick: async () => {
      await eventEmit('autotask_reset_counter');
      toastr.info('已发送重置请求');
      setTimeout(() => renderPage('home'), 500);
    }
  }));
  content.appendChild(btnGroup);

  return buildSection({
    id: 'home_cycle',
    title: '周期进度',
    content: content,
    defaultCollapsed: false
  });
}

/**
 * 查找下一个周期任务
 */
function findNextCycleTask(preset, currentPosition, cycleLength) {
  if (!preset || !preset.tasks) return null;

  const cycleTasks = [];
  for (const task of preset.tasks) {
    if (task.enabled && task.trigger?.type === 'cycle') {
      for (const pos of task.trigger.positions || []) {
        cycleTasks.push({ position: pos, name: task.name, taskId: task.id });
      }
    }
  }

  if (cycleTasks.length === 0) return null;

  // 排序
  cycleTasks.sort((a, b) => a.position - b.position);

  // 找当前位置之后的第一个
  for (const task of cycleTasks) {
    if (task.position > currentPosition) {
      return task;
    }
  }

  // 没有则返回第一个（下一轮）
  return cycleTasks[0];
}

/**
