/**
 * 拉取并显示模型列表
 * @param {Object} preset - API预设对象
 * @param {HTMLInputElement} modelInput - 模型输入框元素
 */
async function fetchAndShowModels(preset, modelInput) {
  // 检查必要配置
  if (!preset.apiurl) {
    toastr.warning('请先填写API地址');
    return;
  }
  if (!preset.key) {
    toastr.warning('请先填写API密钥');
    return;
  }

  // 构建请求URL
  let baseUrl = preset.apiurl.replace(/\/+$/, ''); // 移除末尾斜杠
  if (preset.autoAppendV1 && !baseUrl.endsWith('/v1')) {
    baseUrl += '/v1';
  }
  const modelsUrl = `${baseUrl}/models`;

  toastr.info('正在获取模型列表...');

  try {
    const response = await fetch(modelsUrl, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${preset.key}`,
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    const data = await response.json();
    let models = [];

    // 解析不同API的响应格式
    if (data.data && Array.isArray(data.data)) {
      // OpenAI 格式
      models = data.data.map(m => m.id).filter(Boolean);
    } else if (data.models && Array.isArray(data.models)) {
      // 某些API的格式
      models = data.models.map(m => m.name || m.id).filter(Boolean);
    } else if (Array.isArray(data)) {
      // 直接数组格式
      models = data.map(m => typeof m === 'string' ? m : (m.id || m.name)).filter(Boolean);
    }

    if (models.length === 0) {
      toastr.warning('未获取到模型列表');
      return;
    }

    // 排序：常用模型优先
    const priorityKeywords = ['gpt-4', 'claude', 'gemini', 'deepseek', 'command'];
    models.sort((a, b) => {
      const aPriority = priorityKeywords.some(k => a.toLowerCase().includes(k)) ? 0 : 1;
      const bPriority = priorityKeywords.some(k => b.toLowerCase().includes(k)) ? 0 : 1;
      if (aPriority !== bPriority) return aPriority - bPriority;
      return a.localeCompare(b);
    });

    // 显示模型下拉列表
    showModelDropdown(preset.id, models, modelInput);
    toastr.success(`获取到 ${models.length} 个模型`);

  } catch (err) {
    console.error('[AutoTask] Fetch models error:', err);
    toastr.error('获取模型列表失败: ' + err.message);
  }
}

/**
 * 显示模型下拉选择列表
 */
function showModelDropdown(presetId, models, modelInput) {
  const dropdown = mainDoc.getElementById(`model-dropdown-${presetId}`);
  if (!dropdown) return;

  dropdown.innerHTML = '';
  dropdown.style.display = 'block';
  dropdown.style.cssText = `
    display: block;
    max-height: 200px;
    overflow-y: auto;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    margin-top: 4px;
  `;

  for (const model of models) {
    const item = mainDoc.createElement('div');
    item.style.cssText = `
      padding: 8px 10px;
      cursor: pointer;
      font-size: 13px;
      border-bottom: 1px solid var(--border-light);
    `;
    item.textContent = model;

    item.addEventListener('mouseenter', () => {
      item.style.background = 'var(--bg-hover)';
    });
    item.addEventListener('mouseleave', () => {
      item.style.background = 'transparent';
    });
    item.addEventListener('click', () => {
      modelInput.value = model;
      modelInput.dispatchEvent(new Event('input')); // 触发保存
      dropdown.style.display = 'none';
    });

    dropdown.appendChild(item);
  }

  // 点击其他地方关闭下拉
  const closeHandler = (e) => {
    if (!dropdown.contains(e.target) && e.target !== modelInput) {
      dropdown.style.display = 'none';
      mainDoc.removeEventListener('click', closeHandler);
    }
  };
  setTimeout(() => mainDoc.addEventListener('click', closeHandler), 100);
}


