/**
 * 玩家页 - 周期任务区块
 */
function buildPlayerCycleTasksSection(preset) {
  const engineState = getEngineState();
  const engineRunning = isEngineRunning();

  // 计算周期信息
  let cycleLength = 0;
  let currentPosition = 0;

  // 收集所有周期任务及其位置
  const cycleTasksByPosition = new Map(); // position -> tasks[]

  for (const task of preset.tasks || []) {
    if (task.enabled && task.trigger?.type === 'cycle') {
      for (const pos of task.trigger.positions || []) {
        if (!cycleTasksByPosition.has(pos)) {
          cycleTasksByPosition.set(pos, []);
        }
        cycleTasksByPosition.get(pos).push(task);
        if (pos > cycleLength) cycleLength = pos;
      }
    }
  }

  if (engineRunning && engineState) {
    cycleLength = engineState.cycleLength || cycleLength;
    const cycleCounter = engineState.cycleCounter || 0;
    currentPosition = cycleLength > 0 ? ((cycleCounter - 1) % cycleLength) + 1 : 0;
  }

  const content = mainDoc.createElement('div');

  if (cycleTasksByPosition.size === 0) {
    content.innerHTML = '<div class="at-text-muted">暂无周期任务</div>';
  } else {
    // 按位置排序
    const sortedPositions = Array.from(cycleTasksByPosition.keys()).sort((a, b) => a - b);

    // 找到下一个任务的位置
    let nextPosition = null;
    for (const pos of sortedPositions) {
      if (pos > currentPosition) {
        nextPosition = pos;
        break;
      }
    }
    if (nextPosition === null && sortedPositions.length > 0) {
      nextPosition = sortedPositions[0]; // 下一轮的第一个
    }

    for (const pos of sortedPositions) {
      const tasks = cycleTasksByPosition.get(pos);
      const isPast = pos <= currentPosition;
      const isNext = pos === nextPosition;

      const row = mainDoc.createElement('div');
      row.className = 'at-task-row';
      row.style.cssText = `
        display: flex;
        align-items: center;
        padding: 10px;
        margin-bottom: 6px;
        background: var(--bg-tertiary);
        border-radius: 4px;
        border-left: 3px solid ${isNext ? 'var(--accent-primary)' : (isPast ? 'var(--accent-secondary)' : 'var(--border-color)')};
      `;

      // 位置标记
      const posMarker = mainDoc.createElement('span');
      posMarker.style.cssText = `
        color: ${isPast ? 'var(--accent-secondary)' : 'var(--text-muted)'};
        font-weight: 500;
        min-width: 60px;
      `;
      posMarker.textContent = `${isPast ? '●' : '○'} 位置 ${pos}`;
      row.appendChild(posMarker);

      // 任务信息
      const taskInfo = mainDoc.createElement('div');
      taskInfo.style.cssText = 'flex: 1; margin: 0 12px;';

      if (tasks.length === 1) {
        taskInfo.innerHTML = `
          <div style="font-weight: 500;">${tasks[0].name}</div>
          ${isNext ? '<div class="at-text-muted">← 下一个</div>' : ''}
        `;
      } else {
        taskInfo.innerHTML = `
          <div style="font-weight: 500;">[${tasks.length}个任务]</div>
          <div class="at-text-muted">${tasks.map(t => t.name).join(', ')}</div>
          ${isNext ? '<div style="color: var(--accent-primary);">← 下一个</div>' : ''}
        `;
      }
      row.appendChild(taskInfo);

      // 执行按钮
      const btnContainer = mainDoc.createElement('div');
      for (const task of tasks) {
        const btn = buildButton({
          text: tasks.length > 1 ? `执行` : '执行',
          small: true,
          disabled: !engineRunning,
          title: engineRunning ? `执行 ${task.name}` : '引擎未启动',
          onClick: async () => {
            toastr.info(`🔄 正在执行: ${task.name}`);
            try {
              await eventEmit('autotask_manual_trigger', { taskId: task.id });
            } catch (err) {
              toastr.error(`执行失败: ${err.message}`);
            }
          }
        });
        btn.style.marginLeft = '4px';
        btnContainer.appendChild(btn);
      }
      row.appendChild(btnContainer);

      content.appendChild(row);
    }
  }

  return buildSection({
    id: 'player_cycle',
    title: '周期任务',
    badge: cycleLength > 0 ? `${currentPosition}/${cycleLength}` : null,
    content: content,
    defaultCollapsed: false
  });
}

