/**
 * 玩家页 - 剧情摘要区块
 */
function buildPlayerSummarySection(preset) {
  const engineState = getEngineState();
  const engineRunning = isEngineRunning();
  const summaryTask = preset.summaryTask || {};
  const updateConfig = summaryTask.update || {};
  const compressConfig = summaryTask.compress || {};

  const content = mainDoc.createElement('div');

  // ─────────────────────────────────────
  // 小总结部分
  // ─────────────────────────────────────
  const updateSection = mainDoc.createElement('div');
  updateSection.style.marginBottom = '16px';

  const updateHeader = mainDoc.createElement('div');
  updateHeader.className = 'at-flex at-flex-between at-flex-center';
  updateHeader.innerHTML = `
    <strong>小总结 (增量更新)</strong>
    <span class="at-section-badge" style="background: ${updateConfig.enabled ? 'var(--success)' : 'var(--bg-hover)'}">
      ${updateConfig.enabled ? '已启用' : '未启用'}
    </span>
  `;
  updateSection.appendChild(updateHeader);

  // 触发间隔
  const interval = updateConfig.interval || 20;
  updateSection.appendChild(buildInfoRow('触发间隔', `每 ${interval} 轮`));

  // 进度（从引擎获取）
  const totalFloorCount = getSafeTotalFloorCount();
  const progress = totalFloorCount % interval;
  const justTriggered = (progress === 0 && totalFloorCount > 0);
  const remaining = justTriggered ? interval : (interval - progress);

  if (updateConfig.enabled) {
    // 进度条
    const progressContainer = mainDoc.createElement('div');
    progressContainer.style.margin = '8px 0';

    const progressLabel = mainDoc.createElement('div');
    progressLabel.className = 'at-text-muted';
    progressLabel.style.marginBottom = '4px';
    progressLabel.textContent = justTriggered
      ? `进度: ${interval}/${interval} (本轮已触发，下次${interval}轮后)`
      : `进度: ${progress}/${interval} (还需${remaining}轮)`;
    progressContainer.appendChild(progressLabel);

    const progressBar = mainDoc.createElement('div');
    progressBar.style.cssText = `
      height: 8px;
      background: var(--bg-hover);
      border-radius: 4px;
      overflow: hidden;
    `;
    const progressFill = mainDoc.createElement('div');
    const progressPercent = justTriggered ? 100 : (progress / interval) * 100;
    progressFill.style.cssText = `
      height: 100%;
      width: ${progressPercent}%;
      background: var(--accent-secondary);
      transition: width 0.3s;
    `;
    progressBar.appendChild(progressFill);
    progressContainer.appendChild(progressBar);
    updateSection.appendChild(progressContainer);
  }

  // 小总结执行按钮
  updateSection.appendChild(buildButton({
    text: '立即执行',
    disabled: !engineRunning,
    title: engineRunning ? '立即执行小总结' : '引擎未启动',
    onClick: async () => {
      toastr.info('🔄 正在执行小总结...');
      try {
        await eventEmit('autotask_manual_summary');
      } catch (err) {
        toastr.error(`执行失败: ${err.message}`);
      }
    }
  }));

  content.appendChild(updateSection);
  content.appendChild(buildDivider());

  // ─────────────────────────────────────
  // 大总结部分
  // ─────────────────────────────────────
  const compressSection = mainDoc.createElement('div');
  compressSection.style.marginBottom = '16px';

  const compressHeader = mainDoc.createElement('div');
  compressHeader.className = 'at-flex at-flex-between at-flex-center';
  compressHeader.innerHTML = `
    <strong>大总结 (压缩)</strong>
    <span class="at-section-badge">手动</span>
  `;
  compressSection.appendChild(compressHeader);

  // EVENTS字数统计
  const eventsCharCount = getEventsCharCount();
  const threshold = 20000;
  const percent = Math.min((eventsCharCount / threshold) * 100, 100);
  const needCompress = eventsCharCount >= threshold;

  compressSection.appendChild(buildInfoRow(
    'EVENTS',
    `${formatNumber(eventsCharCount)} 字 / ${formatNumber(threshold)}`,
    needCompress ? 'warn' : 'ok'
  ));

  // EVENTS状态条
  const eventsBar = mainDoc.createElement('div');
  eventsBar.style.cssText = `
    height: 8px;
    background: var(--bg-hover);
    border-radius: 4px;
    overflow: hidden;
    margin: 8px 0;
  `;
  const eventsFill = mainDoc.createElement('div');
  eventsFill.style.cssText = `
    height: 100%;
    width: ${percent}%;
    background: ${needCompress ? 'var(--warning)' : 'var(--accent-secondary)'};
    transition: width 0.3s;
  `;
  eventsBar.appendChild(eventsFill);
  compressSection.appendChild(eventsBar);

  if (needCompress) {
    const warnText = mainDoc.createElement('div');
    warnText.style.cssText = 'color: var(--warning); font-size: 12px; margin-bottom: 8px;';
    warnText.textContent = '⚠️ 建议执行大总结压缩EVENTS';
    compressSection.appendChild(warnText);
  }

  // 大总结执行按钮
  compressSection.appendChild(buildButton({
    text: '立即执行',
    disabled: !engineRunning,
    title: engineRunning ? '立即执行大总结' : '引擎未启动',
    onClick: async () => {
      toastr.info('🔄 正在执行大总结...');
      try {
        await eventEmit('autotask_manual_compress');
      } catch (err) {
        toastr.error(`执行失败: ${err.message}`);
      }
    }
  }));

  content.appendChild(compressSection);
  content.appendChild(buildDivider());

  // ─────────────────────────────────────
  // 摘要范围信息
  // ─────────────────────────────────────
  const rangeSection = mainDoc.createElement('div');
  rangeSection.style.marginBottom = '16px';

  rangeSection.innerHTML = '<strong style="display: block; margin-bottom: 8px;">摘要范围</strong>';

  // 获取摘要位置信息
  const lastSummarizedId = getSafeLastSummarizedId();
  let lastMessageId = -1;

  try {
    lastMessageId = getLastMessageId();
  } catch (e) {
    lastMessageId = -1;
  }

  const hasSummary = lastSummarizedId >= 0;
  const pendingMessages = hasSummary ? Math.max(0, lastMessageId - lastSummarizedId) : (lastMessageId + 1);

  rangeSection.appendChild(buildInfoRow('已摘要', hasSummary ? `0-${lastSummarizedId} 楼` : '暂无'));
  rangeSection.appendChild(buildInfoRow('当前楼层', lastMessageId >= 0 ? lastMessageId.toString() : '-'));
  rangeSection.appendChild(buildInfoRow('待摘要', `${pendingMessages} 条消息`));

  content.appendChild(rangeSection);
  content.appendChild(buildDivider());

  // ─────────────────────────────────────
  // 隐藏已摘要楼层开关
  // ─────────────────────────────────────
  const hideSection = mainDoc.createElement('div');

  const hideToggle = buildHideMessagesToggle(preset, lastSummarizedId);
  hideSection.appendChild(hideToggle);

  content.appendChild(hideSection);

  return buildSection({
    id: 'player_summary',
    title: '剧情摘要',
    content: content,
    defaultCollapsed: false
  });
}

