/**
 * 构建隐藏已摘要楼层开关
 */
function buildHideMessagesToggle(preset, lastSummarizedId) {
  const container = mainDoc.createElement('div');
  container.className = 'at-flex at-flex-between at-flex-center';

  const label = mainDoc.createElement('span');
  label.textContent = '自动隐藏已摘要楼层';
  container.appendChild(label);

  // 判断是否禁用
  const disabled = lastSummarizedId < 0;
  const autoHide = preset.summaryTask?.update?.autoHideMessages ?? true;

  // 创建开关
  const toggle = mainDoc.createElement('div');
  toggle.className = 'at-toggle';
  toggle.style.cssText = `
    width: 48px;
    height: 26px;
    border-radius: 13px;
    background: ${disabled ? 'var(--bg-hover)' : (autoHide ? 'var(--accent-secondary)' : 'var(--bg-hover)')};
    cursor: ${disabled ? 'not-allowed' : 'pointer'};
    position: relative;
    transition: background 0.2s;
    opacity: ${disabled ? '0.5' : '1'};
  `;

  const knob = mainDoc.createElement('div');
  knob.style.cssText = `
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--text-primary);
    position: absolute;
    top: 2px;
    left: ${autoHide ? '24px' : '2px'};
    transition: left 0.2s;
  `;
  toggle.appendChild(knob);

  if (disabled) {
    toggle.title = '暂无摘要记录';
  } else {
    toggle.title = autoHide ? '点击关闭自动隐藏' : '点击开启自动隐藏';

    toggle.addEventListener('click', async () => {
      const newValue = !autoHide;
      try {
        // 更新配置
        if (!configDraft) return;
        const activePreset = getActivePreset();
        if (!activePreset) return;

        if (!activePreset.summaryTask) activePreset.summaryTask = {};
        if (!activePreset.summaryTask.update) activePreset.summaryTask.update = {};
        activePreset.summaryTask.update.autoHideMessages = newValue;

        // 修改消息隐藏状态
        await toggleHideMessages(0, lastSummarizedId, newValue);

        // 保存配置
        await saveConfig(configDraft);
        await eventEmit('autotask_config_updated');

        toastr.success(newValue ? '已隐藏已摘要楼层' : '已显示已摘要楼层');

        // 刷新页面
        renderPage('player');
      } catch (err) {
        toastr.error('操作失败: ' + err.message);
      }
    });
  }

  container.appendChild(toggle);
  return container;
}

/**
 * 切换消息隐藏状态
 */
async function toggleHideMessages(startId, endId, hide) {
  if (startId < 0 || endId < 0 || startId > endId) return;

  try {
    // 获取范围内的消息
    const messages = getChatMessages(`${startId}-${endId}`, {
      hide_state: hide ? 'unhidden' : 'hidden'
    });

    if (messages.length === 0) return;

    // 批量修改
    const updates = messages.map(m => ({
      message_id: m.message_id,
      is_hidden: hide
    }));

    await setChatMessages(updates, { refresh: 'all' });
  } catch (err) {
    console.error('[AutoTask] Toggle hide messages error:', err);
    throw err;
  }
}

