      <div style="font-size: 48px; margin-bottom: 16px;">📋</div>
      <div style="font-size: 16px; color: var(--text-primary); margin-bottom: 8px;">暂无配置方案</div>
      <div class="at-text-muted" style="margin-bottom: 20px;">创建一个方案开始配置自动任务</div>
    `;

    const createBtn = buildButton({
      text: '创建方案',
      primary: true,
      onClick: () => {
        const newPreset = createEmptyPreset();
        configDraft.presets.push(newPreset);
        configDraft.activePresetId = newPreset.id;
        currentEditingPresetId = newPreset.id;
        markDirty();
        renderPage('creator');
        toastr.info('已创建新方案');
      }
    });
    emptyState.appendChild(createBtn);

    container.appendChild(emptyState);

    // 仍然显示导入导出区块（允许导入配置）
    container.appendChild(buildCreatorExportSection());

    // 底部: 保存按钮（即使无方案也需要能保存）
    container.appendChild(buildCreatorSaveButtons());

    return;
  }

  // 确保有编辑中的方案
  if (!currentEditingPresetId || !configDraft.presets.find(p => p.id === currentEditingPresetId)) {
    currentEditingPresetId = configDraft.activePresetId || configDraft.presets[0]?.id;
  }

  const editingPreset = getCurrentEditingPreset();

  // 区块1: 方案管理
  container.appendChild(buildCreatorPresetSection());

  // 区块2: 提示词模板
  container.appendChild(buildCreatorTemplateSection(editingPreset));

  // 区块3: 参考条目池
  container.appendChild(buildCreatorReferenceSection(editingPreset));

  // 区块4: 任务列表
  container.appendChild(buildCreatorTasksSection(editingPreset));

  // 区块5: 摘要设置
  container.appendChild(buildCreatorSummarySection(editingPreset));

  // 区块6: 变量更新任务
  container.appendChild(buildCreatorVarUpdateSection(editingPreset));

  // 区块7: 依赖检查
  container.appendChild(buildCreatorCheckSection(editingPreset));

  // 区块8: 导入导出
  container.appendChild(buildCreatorExportSection());

  // 底部: 保存按钮
  container.appendChild(buildCreatorSaveButtons());
}

// ─────────────────────────────────────────────────────────────────
// 创作者页 - 方案管理区块
