/**
 * 创作者页 - 方案管理区块
 */
function buildCreatorPresetSection() {
  const content = mainDoc.createElement('div');
  const editingPreset = getCurrentEditingPreset();

  // 方案选择下拉
  const presetChoices = (configDraft?.presets || []).map(p => ({
    value: p.id,
    label: p.name + (p.id === configDraft.activePresetId ? ' (当前激活)' : '')
  }));

  content.appendChild(buildSelect({
    label: '编辑方案',
    value: currentEditingPresetId,
    choices: presetChoices.length > 0 ? presetChoices : [{ value: '', label: '无可用方案' }],
    onChange: async (value) => {
      if (value === currentEditingPresetId) return;

      // 检查未保存修改
      if (isDirty) {
        const confirmed = await SillyTavern.callGenericPopup(
          '当前方案有未保存的修改，切换将丢失。确定吗？',
          SillyTavern.POPUP_TYPE.CONFIRM
        );
        if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
          // 恢复下拉框选项
          renderPage('creator');
          return;
        }
        // 重新加载配置丢弃修改
        configDraft = deepClone(await loadConfig());
        isDirty = false;
      }

      currentEditingPresetId = value;
      renderPage('creator');
    }
  }));

  // 方案名称编辑
  if (editingPreset) {
    content.appendChild(buildInput({
      label: '方案名称',
      value: editingPreset.name,
      placeholder: '输入方案名称',
      onChange: (value) => {
        editingPreset.name = value;
        markDirty();
      }
    }));

    // 方案描述编辑
    content.appendChild(buildTextarea({
      label: '方案描述',
      value: editingPreset.description || '',
      placeholder: '可选的方案描述',
      rows: 2,
      onChange: (value) => {
        editingPreset.description = value;
        markDirty();
      }
    }));

    content.appendChild(buildDivider());

    // 聊天记录范围设置
    const historyRangeContainer = mainDoc.createElement('div');
    historyRangeContainer.className = 'at-form-group';

    const historyLabel = mainDoc.createElement('label');
    historyLabel.className = 'at-form-label';
    historyLabel.textContent = '聊天记录范围';
    historyRangeContainer.appendChild(historyLabel);

    const rangeOptions = mainDoc.createElement('div');
    rangeOptions.className = 'at-flex at-gap-md at-flex-center';
    rangeOptions.style.marginBottom = '8px';

    const isAfterSummary = editingPreset.chatHistoryRange === 'after_summary';

    // 摘要之后选项
    const afterSummaryLabel = mainDoc.createElement('label');
    afterSummaryLabel.className = 'at-form-checkbox';
    afterSummaryLabel.innerHTML = `
      <input type="radio" name="historyRange" value="after_summary" ${isAfterSummary ? 'checked' : ''}>
      <span>摘要之后</span>
    `;
    afterSummaryLabel.querySelector('input').addEventListener('change', () => {
      editingPreset.chatHistoryRange = 'after_summary';
      markDirty();
      renderPage('creator');
    });
    rangeOptions.appendChild(afterSummaryLabel);

    // 固定条数选项
    const fixedLabel = mainDoc.createElement('label');
    fixedLabel.className = 'at-form-checkbox';
    fixedLabel.innerHTML = `
      <input type="radio" name="historyRange" value="fixed" ${!isAfterSummary ? 'checked' : ''}>
      <span>固定条数</span>
    `;
    fixedLabel.querySelector('input').addEventListener('change', () => {
      editingPreset.chatHistoryRange = 50;
      markDirty();
      renderPage('creator');
    });
    rangeOptions.appendChild(fixedLabel);

    // 条数输入框
    const countInput = mainDoc.createElement('input');
    countInput.type = 'number';
    countInput.className = 'at-form-input';
    countInput.style.width = '80px';
    countInput.value = typeof editingPreset.chatHistoryRange === 'number' ? editingPreset.chatHistoryRange : 50;
    countInput.disabled = isAfterSummary;
    countInput.addEventListener('input', (e) => {
      const val = parseInt(e.target.value) || 50;
      editingPreset.chatHistoryRange = val;
      markDirty();
    });
    rangeOptions.appendChild(countInput);

    historyRangeContainer.appendChild(rangeOptions);

    // 警告信息
    const summaryEnabled = editingPreset.summaryTask?.update?.enabled;
    const engineState = getEngineState();
    const lastSummarizedId = engineState?.lastSummarizedId ?? -1;

    if (isAfterSummary && (!summaryEnabled || lastSummarizedId < 0)) {
      const warning = mainDoc.createElement('div');
      warning.style.cssText = 'color: var(--warning); font-size: 12px; margin-top: 4px;';
      warning.textContent = '⚠️ 当前将读取全部历史消息，可能导致提示词过长';
      historyRangeContainer.appendChild(warning);
    }

    content.appendChild(historyRangeContainer);

    // 转换system消息选项
    content.appendChild(buildCheckbox({
      label: '将system消息转为user角色',
      checked: editingPreset.chatHistoryOptions?.convertSystemToUser ?? true,
      onChange: (checked) => {
        if (!editingPreset.chatHistoryOptions) {
          editingPreset.chatHistoryOptions = {};
        }
        editingPreset.chatHistoryOptions.convertSystemToUser = checked;
        markDirty();
      }
    }));

    content.appendChild(buildDivider());
  }

  // 方案操作按钮
  const btnGroup = mainDoc.createElement('div');
  btnGroup.className = 'at-flex at-gap-sm';
  btnGroup.style.flexWrap = 'wrap';

  // 新建方案
  btnGroup.appendChild(buildButton({
    text: '新建方案',
    onClick: () => {
      const newPreset = createEmptyPreset();
      configDraft.presets.push(newPreset);
      currentEditingPresetId = newPreset.id;
      // 如果是第一个方案，自动设为激活
      if (configDraft.presets.length === 1) {
        configDraft.activePresetId = newPreset.id;
      }
      markDirty();
      renderPage('creator');
      toastr.info('已创建新方案');
    }
  }));

  // 复制方案
  btnGroup.appendChild(buildButton({
    text: '复制方案',
    disabled: !editingPreset,
    onClick: () => {
      if (!editingPreset) return;
      const copied = deepClone(editingPreset);
      copied.id = generateUUID();
      copied.name = editingPreset.name + ' (副本)';
      // 复制时重新生成所有任务ID
      for (const task of copied.tasks || []) {
        task.id = generateUUID();
      }
      configDraft.presets.push(copied);
      currentEditingPresetId = copied.id;
      markDirty();
      renderPage('creator');
      toastr.info('已复制方案');
    }
  }));

  // 清空方案（新增）
  btnGroup.appendChild(buildButton({
    text: '清空方案',
    disabled: !editingPreset,
    title: '清空当前方案的所有任务、参考条目和设置',
    onClick: async () => {
      if (!editingPreset) return;

      const confirmed = await SillyTavern.callGenericPopup(
        `确定清空方案「${editingPreset.name}」的所有内容吗？\n\n将清空：任务列表、参考条目池、提示词模板、摘要设置\n\n方案本身会保留，仅清空内容。`,
        SillyTavern.POPUP_TYPE.CONFIRM
      );

      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) return;

      // 清空方案内容，保留id和name
      editingPreset.tasks = [];
      editingPreset.referencePool = [];
      editingPreset.promptTemplates = {
        identity: null,
        moduleConfig: null,
        prefill: null,
      };
      editingPreset.summaryTask = {
        update: {
          enabled: false,
          interval: 20,
          promptKey: null,
          apiPresetId: null,
          autoHideMessages: true,
        },
        compress: {
          promptKey: null,
          apiPresetId: null,
        },
        outputAttributes: {
          events: null,
          relations: null,
          active: null,
        },
      };
      editingPreset.chatHistoryRange = 50;
      editingPreset.chatHistoryOptions = {
        convertSystemToUser: true,
      };

      markDirty();
      renderPage('creator');
      toastr.info('方案已清空');
    }
  }));

  // 删除方案（移除数量限制）
  btnGroup.appendChild(buildButton({
    text: '删除方案',
    disabled: !editingPreset,
    onClick: async () => {
      if (!editingPreset) return;

      const isLastPreset = configDraft.presets.length === 1;
      let confirmMsg = `确定删除方案「${editingPreset.name}」吗？此操作不可撤销。`;

      if (isLastPreset) {
        confirmMsg += '\n\n⚠️ 这是最后一个方案，删除后需要新建方案才能使用功能。';
      }

      const confirmed = await SillyTavern.callGenericPopup(
        confirmMsg,
        SillyTavern.POPUP_TYPE.CONFIRM
      );

      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) return;

      // 删除方案
      configDraft.presets = configDraft.presets.filter(p => p.id !== editingPreset.id);

      // 如果删除的是激活方案，切换到第一个（如果有）
      if (configDraft.activePresetId === editingPreset.id) {
        configDraft.activePresetId = configDraft.presets[0]?.id || null;
      }

      currentEditingPresetId = configDraft.presets[0]?.id || null;
      markDirty();
      renderPage('creator');
      toastr.info('方案已删除');
    }
  }));

  content.appendChild(btnGroup);

  return buildSection({
    id: 'creator_preset',
    title: '方案管理',
    content: content,
    defaultCollapsed: false
  });
}

