  return {
    id: generateUUID(),
    name: '新方案',
    description: '',
    tasks: [],
    referencePool: [],
    promptTemplates: {
      identity: { mode: 'default', customContent: '' },
      moduleConfig: { mode: 'default', customContent: '' },
