/**
 * 创作者页 - 提示词模板区块
 */
function buildCreatorTemplateSection(preset) {
  const content = mainDoc.createElement('div');

  if (!preset) {
    content.innerHTML = '<div class="at-text-muted">请先选择方案</div>';
    return buildSection({
      id: 'creator_template',
      title: '提示词模板',
      content: content,
      defaultCollapsed: true
    });
  }

  // 确保promptTemplates存在且结构正确
  if (!preset.promptTemplates) {
    preset.promptTemplates = {
      identity: { mode: 'default', customContent: '' },
      moduleConfig: { mode: 'default', customContent: '' },
      prefill: { mode: 'default', customContent: '' }
    };
  }

  // 兼容旧数据结构（如果是null或string，转为新结构）
  const ensurePromptConfig = (value) => {
    if (!value || typeof value !== 'object' || !value.mode) {
      return { mode: 'default', customContent: '' };
    }
    return { mode: value.mode, customContent: value.customContent || '' };
  };

  preset.promptTemplates.identity = ensurePromptConfig(preset.promptTemplates.identity);
  preset.promptTemplates.moduleConfig = ensurePromptConfig(preset.promptTemplates.moduleConfig);
  preset.promptTemplates.prefill = ensurePromptConfig(preset.promptTemplates.prefill);

  const templates = preset.promptTemplates;

  // 说明文字
