  identitySection.appendChild(buildPromptConfigEditor(
    templates.identity,
    () => markDirty(),
    getDefaultIdentityPrompt,
    { rows: 4 }
  ));

  content.appendChild(identitySection);
  content.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 权限声明 (moduleConfig)
  // ═══════════════════════════════════════
