  moduleLabel.style.cssText = 'font-weight: 500; margin-bottom: 4px;';
  moduleLabel.textContent = '权限声明 (moduleConfig)';
  moduleSection.appendChild(moduleLabel);

  const moduleDesc = mainDoc.createElement('div');
  moduleDesc.className = 'at-text-muted';
  moduleDesc.style.cssText = 'font-size: 12px; margin-bottom: 8px;';
  moduleDesc.textContent = '声明模块的权限和限制';
  moduleSection.appendChild(moduleDesc);

  moduleSection.appendChild(buildPromptConfigEditor(
    templates.moduleConfig,
    () => markDirty(),
