// ═══════════════════════════════════════════════════════════════
// 世界书条目选择器
// ═══════════════════════════════════════════════════════════════

/**
 * 构建世界书条目选择器（复选框多选版）
 * @param {Function} onBatchAdd - 批量添加回调，参数为选中的条目数组
 * @param {string[]} existingKeys - 已添加的关键词
 */
async function buildWorldbookEntrySelector(onBatchAdd, existingKeys = []) {
  const wrapper = mainDoc.createElement('div');

  // ═══ 选中状态 ═══
  const selectedKeys = new Set();

  // ═══ 顶部：搜索框 + 已选计数 ═══
  const headerBox = mainDoc.createElement('div');
  headerBox.style.cssText = `
    padding: 8px;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    gap: 8px;
    align-items: center;
  `;

  const searchInput = mainDoc.createElement('input');
  searchInput.type = 'text';
  searchInput.className = 'at-form-input';
  searchInput.placeholder = '🔍 搜索条目名称或关键词...';
  searchInput.style.flex = '1';
  headerBox.appendChild(searchInput);

  const selectedCountSpan = mainDoc.createElement('span');
  selectedCountSpan.style.cssText = `
    color: var(--accent-primary);
    font-size: 13px;
    white-space: nowrap;
  `;
  selectedCountSpan.textContent = '已选 0 项';
  headerBox.appendChild(selectedCountSpan);

  wrapper.appendChild(headerBox);

  // ═══ 条目列表容器 ═══
  const listContainer = mainDoc.createElement('div');
  listContainer.style.cssText = 'max-height: 280px; overflow-y: auto;';
  wrapper.appendChild(listContainer);

  // ═══ 底部：添加按钮 ═══
  const footerBox = mainDoc.createElement('div');
  footerBox.style.cssText = `
    padding: 8px;
    border-top: 1px solid var(--border-light);
    display: flex;
    justify-content: center;
  `;

  const addSelectedBtn = buildButton({
    text: '➕ 添加选中项',
    primary: true,
    disabled: true,
    onClick: () => {
      if (selectedKeys.size === 0) return;

      // 收集选中的条目信息
      const selectedEntries = [];
      for (const key of selectedKeys) {
        const entry = allEntries.find(e => e.primaryKey === key);
        if (entry) {
          selectedEntries.push({
            name: entry.name,
            primaryKey: entry.primaryKey,
            allKeys: entry.keys,
            enabled: entry.enabled
          });
        }
      }

      // 回调批量添加
      onBatchAdd(selectedEntries);

      // 清空选择
      selectedKeys.clear();
      updateSelectedCount();

      // 更新列表状态（已添加的变灰）
      renderEntries(searchInput.value);
    }
  });
  footerBox.appendChild(addSelectedBtn);

  wrapper.appendChild(footerBox);

  // ═══ 加载世界书 ═══
  const charWB = getCharWorldbookNames('current');
  if (!charWB.primary) {
    listContainer.innerHTML = '<div class="at-text-muted" style="text-align: center; padding: 20px;">当前角色卡未绑定主世界书</div>';
    return wrapper;
  }

  const worldbookName = charWB.primary;
  let allEntries = [];

  try {
    const entries = await getWorldbook(worldbookName);

    allEntries = entries
      .filter(e => !e.strategy.keys.some(k => k === CONFIG_ENTRY_KEY))
      .map(e => {
        const allKeys = (e.strategy.keys || []).map(k =>
          k instanceof RegExp ? k.source : String(k)
        ).filter(k => k.trim() !== '');

        return {
          uid: e.uid,
          name: e.name || '',
          keys: allKeys,
          primaryKey: allKeys[0] || '',
          enabled: e.enabled,
          type: e.strategy.type,
          hasKeys: allKeys.length > 0
        };
      })
      .sort((a, b) => {
        if (a.hasKeys !== b.hasKeys) return a.hasKeys ? -1 : 1;
        return (a.name || a.primaryKey || '').localeCompare(b.name || b.primaryKey || '');
      });

  } catch (err) {
    listContainer.innerHTML = `<div class="at-status-error" style="padding: 16px;">加载失败: ${err.message}</div>`;
    return wrapper;
  }

  if (allEntries.length === 0) {
    listContainer.innerHTML = '<div class="at-text-muted" style="text-align: center; padding: 20px;">世界书中没有可用条目</div>';
    return wrapper;
  }

  // ═══ 更新已选计数 ═══
  function updateSelectedCount() {
    const count = selectedKeys.size;
    selectedCountSpan.textContent = `已选 ${count} 项`;
    addSelectedBtn.disabled = count === 0;
    addSelectedBtn.textContent = count > 0 ? `➕ 添加选中的 ${count} 项` : '➕ 添加选中项';
  }

  // ═══ 为无关键词条目添加关键词 ═══
  async function addKeywordToEntry(entry, keyword) {
    try {
      await updateWorldbookWith(worldbookName, (entries) => {
        return entries.map(e => {
          if (e.uid === entry.uid) {
            const newKeys = [...(e.strategy.keys || []), keyword];
            return {
              ...e,
              strategy: { ...e.strategy, keys: newKeys }
            };
          }
          return e;
        });
      });
      return true;
    } catch (err) {
      console.error('[AutoTask] 写入关键词失败:', err);
      toastr.error('写入关键词失败: ' + err.message);
      return false;
    }
  }

  // ═══ 渲染条目列表 ═══
  function renderEntries(filter = '') {
    listContainer.innerHTML = '';

    const filterLower = filter.toLowerCase().trim();

    const filteredEntries = filterLower
      ? allEntries.filter(e =>
          e.name.toLowerCase().includes(filterLower) ||
          e.keys.some(k => k.toLowerCase().includes(filterLower))
        )
      : allEntries;

    if (filteredEntries.length === 0) {
      listContainer.innerHTML = '<div class="at-text-muted" style="text-align: center; padding: 20px;">没有匹配的条目</div>';
      return;
    }

    for (const entry of filteredEntries) {
      const isAdded = entry.hasKeys && existingKeys.includes(entry.primaryKey);
      const isSelected = selectedKeys.has(entry.primaryKey);

      const item = mainDoc.createElement('div');
      item.dataset.entryKey = entry.primaryKey;
      item.dataset.entryUid = entry.uid;
      item.style.cssText = `
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 6px 10px;
        border-bottom: 1px solid var(--border-light);
        ${isAdded ? 'opacity: 0.5; background: var(--bg-tertiary);' : ''}
      `;

      if (entry.hasKeys) {
        // ═══ 有关键词：显示复选框 ═══
        const checkbox = mainDoc.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = isSelected;
        checkbox.disabled = isAdded;
        checkbox.style.cssText = 'width: 16px; height: 16px; accent-color: var(--accent-primary); flex-shrink: 0;';

        if (!isAdded) {
          checkbox.addEventListener('change', () => {
            if (checkbox.checked) {
              selectedKeys.add(entry.primaryKey);
            } else {
              selectedKeys.delete(entry.primaryKey);
            }
            updateSelectedCount();
          });
        }

        item.appendChild(checkbox);

        // 名称
        const nameSpan = mainDoc.createElement('span');
        nameSpan.style.cssText = `
          flex: 0 0 auto;
          max-width: 120px;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
          font-weight: 500;
        `;
        nameSpan.textContent = entry.name || '(无名称)';
        nameSpan.title = entry.name;
        item.appendChild(nameSpan);

        // 分隔
        const sep = mainDoc.createElement('span');
        sep.style.color = 'var(--text-muted)';
        sep.textContent = '|';
        item.appendChild(sep);

        // 关键词（省略显示）
        const keySpan = mainDoc.createElement('span');
        keySpan.style.cssText = `
          flex: 1;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
          color: var(--text-secondary);
          font-size: 12px;
          font-family: monospace;
        `;
        const keyDisplay = entry.keys.length > 1
          ? `${entry.primaryKey} +${entry.keys.length - 1}`
          : entry.primaryKey;
        keySpan.textContent = keyDisplay;
        keySpan.title = entry.keys.join(', ');
        item.appendChild(keySpan);

        // 已添加标记
        if (isAdded) {
          const addedBadge = mainDoc.createElement('span');
          addedBadge.style.cssText = `
            font-size: 11px;
            color: var(--success);
            white-space: nowrap;
          `;
          addedBadge.textContent = '✓已添加';
          item.appendChild(addedBadge);
        }

      } else {
        // ═══ 无关键词：显示警告图标 + 行内输入框 ═══
        const warnIcon = mainDoc.createElement('span');
        warnIcon.style.cssText = 'color: var(--warning); flex-shrink: 0;';
        warnIcon.textContent = '⚠';
        item.appendChild(warnIcon);

        // 名称
        const nameSpan = mainDoc.createElement('span');
        nameSpan.style.cssText = `
          flex: 0 0 auto;
          max-width: 100px;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
          font-weight: 500;
        `;
        nameSpan.textContent = entry.name || '(无名称)';
        nameSpan.title = entry.name;
        item.appendChild(nameSpan);

        // 分隔
        const sep = mainDoc.createElement('span');
        sep.style.color = 'var(--text-muted)';
        sep.textContent = '|';
        item.appendChild(sep);

        // 关键词输入框
        const keyInput = mainDoc.createElement('input');
        keyInput.type = 'text';
        keyInput.className = 'at-form-input';
        keyInput.style.cssText = 'flex: 1; min-width: 80px; font-size: 12px; padding: 3px 6px;';
        keyInput.placeholder = '输入关键词...';
        // 默认填充条目名称的简化版
        keyInput.value = (entry.name || 'entry')
          .replace(/[^a-zA-Z0-9_\u4e00-\u9fa5]/g, '_')
          .replace(/^_+|_+$/g, '')
          .substring(0, 30);
        item.appendChild(keyInput);

        // 确认按钮
        const confirmBtn = mainDoc.createElement('button');
        confirmBtn.className = 'at-btn at-btn-sm';
        confirmBtn.textContent = '✓';
        confirmBtn.title = '设置关键词并添加到可选列表';
        confirmBtn.style.cssText = 'padding: 3px 8px; min-width: auto;';
        confirmBtn.addEventListener('click', async () => {
          const keyword = keyInput.value.trim();
          if (!keyword) {
            toastr.warning('请输入关键词');
            return;
          }

          // 写入世界书
          confirmBtn.disabled = true;
          confirmBtn.textContent = '...';

          const success = await addKeywordToEntry(entry, keyword);
          if (!success) {
            confirmBtn.disabled = false;
            confirmBtn.textContent = '✓';
            return;
          }

          // 更新本地数据
          entry.keys = [keyword];
          entry.primaryKey = keyword;
          entry.hasKeys = true;

          // 自动选中
          selectedKeys.add(keyword);
          updateSelectedCount();

          // 重新渲染该条目（变成复选框样式）
          renderEntries(searchInput.value);

          toastr.success(`已为「${entry.name}」设置关键词`);
        });
        item.appendChild(confirmBtn);
      }

      listContainer.appendChild(item);
    }

    // 底部统计
    const stats = mainDoc.createElement('div');
    stats.className = 'at-text-muted';
    stats.style.cssText = 'text-align: center; padding: 6px 0; font-size: 11px;';
    const withKeys = filteredEntries.filter(e => e.hasKeys).length;
    const withoutKeys = filteredEntries.length - withKeys;
    stats.textContent = filterLower
      ? `找到 ${filteredEntries.length} 个`
      : `共 ${allEntries.length} 个条目${withoutKeys > 0 ? ` · ${withoutKeys} 个无关键词` : ''}`;
    listContainer.appendChild(stats);
  }

  // ═══ 搜索事件 ═══
  searchInput.addEventListener('input', (e) => {
    renderEntries(e.target.value);
  });

  // 初始渲染
  renderEntries();

  return wrapper;
}

/**
 * 创作者页 - 参考条目池区块
 */
function buildCreatorReferenceSection(preset) {
  const refCount = preset?.referencePool?.length || 0;

  const content = mainDoc.createElement('div');

  if (!preset) {
    content.innerHTML = '<div class="at-text-muted">请先选择方案</div>';
    return buildSection({
      id: 'creator_reference',
      title: '参考条目池',
      content: content,
      defaultCollapsed: true
    });
  }

  // 确保referencePool存在
  if (!preset.referencePool) {
    preset.referencePool = [];
  }

  const pool = preset.referencePool;

  // 说明文字
  const hint = mainDoc.createElement('div');
  hint.className = 'at-text-muted';
  hint.style.marginBottom = '12px';
  hint.textContent = '参考条目池定义可被任务引用的世界书条目。任务通过变量名引用这些条目的内容。';
  content.appendChild(hint);

  // 条目列表（卡片式）
  if (pool.length === 0) {
    const emptyHint = mainDoc.createElement('div');
    emptyHint.className = 'at-text-muted';
    emptyHint.style.cssText = 'text-align: center; padding: 16px;';
    emptyHint.textContent = '暂无参考条目';
    content.appendChild(emptyHint);
  } else {
    const listContainer = mainDoc.createElement('div');
    listContainer.className = 'at-ref-pool-list';
    listContainer.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

    pool.forEach((ref, index) => {
      listContainer.appendChild(buildReferenceCard(ref, index, pool, preset));
    });

    content.appendChild(listContainer);
  }

  // 添加按钮
  const btnContainer = mainDoc.createElement('div');
  btnContainer.style.marginTop = '12px';
  btnContainer.appendChild(buildButton({
    text: '+ 添加参考条目',
    onClick: () => {
      // 生成默认变量名
      const varNameBase = 'ref';
      let varNameNum = pool.length + 1;
      let varName = `${varNameBase}${varNameNum}`;
      while (pool.some(r => r.varName === varName)) {
        varNameNum++;
        varName = `${varNameBase}${varNameNum}`;
      }

      pool.push({
        label: '新参考条目',
        entryKey: '',
        varName: varName,
        requireEnabled: false
      });
      markDirty();
      renderPage('creator');
    }
  }));
  content.appendChild(btnContainer);

  // ═══════════════════════════════════════
  // 世界书条目快速选取
  // ═══════════════════════════════════════
  const selectorSection = mainDoc.createElement('details');
  selectorSection.style.marginTop = '16px';

  // ═══ 恢复展开状态 ═══
  if (worldbookSelectorOpen) {
    selectorSection.open = true;
  }

  const selectorSummary = mainDoc.createElement('summary');
  selectorSummary.style.cssText = `
    cursor: pointer;
    color: var(--accent-secondary);
    font-size: 13px;
    padding: 10px 12px;
    background: var(--bg-tertiary);
    border-radius: 6px;
    user-select: none;
    display: flex;
    align-items: center;
    gap: 8px;
  `;
  selectorSummary.innerHTML = '📚 <span>从世界书选取条目</span> <span style="color: var(--text-muted); font-size: 12px;">（点击展开）</span>';
  selectorSection.appendChild(selectorSummary);

  const selectorBody = mainDoc.createElement('div');
  selectorBody.style.cssText = `
    margin-top: 8px;
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: 6px;
    overflow: hidden;
  `;

  // ═══ 加载选择器内容的函数 ═══
  async function loadSelector() {
    selectorBody.innerHTML = '<div class="at-text-muted" style="text-align: center; padding: 20px;">加载中...</div>';

    const existingKeys = preset.referencePool.map(r => r.entryKey);

    // 获取参考池列表容器的引用（用于局部更新）
    const poolListContainer = content.querySelector('.at-ref-pool-list');

    const selector = await buildWorldbookEntrySelector((selectedEntries) => {
      // ═══ 批量添加逻辑 ═══
      for (const selected of selectedEntries) {
        // 检查是否已存在
        if (preset.referencePool.some(r => r.entryKey === selected.primaryKey)) {
          continue;
        }

        // 生成变量名
        let baseVarName = (selected.primaryKey || 'ref')
          .replace(/[^a-zA-Z0-9_\u4e00-\u9fa5]/g, '_')
          .replace(/^_+|_+$/g, '')
          .substring(0, 20) || 'ref';

        let varName = baseVarName;
        let counter = 1;
        while (preset.referencePool.some(r => r.varName === varName)) {
          varName = `${baseVarName}_${counter++}`;
        }

        // 创建新条目
        const newRef = {
          label: selected.name || selected.primaryKey,
          entryKey: selected.primaryKey,
          varName: varName,
          requireEnabled: false
        };

        // 添加到数据
        preset.referencePool.push(newRef);

        // 局部更新DOM：添加新卡片
        if (poolListContainer) {
          const newCard = buildReferenceCard(
            newRef,
            preset.referencePool.length - 1,
            preset.referencePool,
            preset
          );
          poolListContainer.appendChild(newCard);
        }

        // 更新existingKeys以便选择器知道已添加
        existingKeys.push(selected.primaryKey);
      }

      markDirty();

      // 更新徽章
      updateRefPoolBadge();

      toastr.success(`已添加 ${selectedEntries.length} 个条目`);

      // 注意：不调用 renderPage()，保持位置不变！
    }, existingKeys);

    selectorBody.innerHTML = '';
    selectorBody.appendChild(selector);
  }

  // ═══ 监听展开/折叠事件 ═══
  selectorSection.addEventListener('toggle', async () => {
    // 保存展开状态
    worldbookSelectorOpen = selectorSection.open;

    if (selectorSection.open) {
      // 每次展开都重新加载（确保数据最新）
      await loadSelector();
    }
  });

  selectorSection.appendChild(selectorBody);
  content.appendChild(selectorSection);

  // ═══ 如果状态为展开，立即加载 ═══
  if (worldbookSelectorOpen) {
    loadSelector();
  }

  return buildSection({
    id: 'creator_reference',
    title: '参考条目池',
    badge: refCount > 0 ? `${refCount}个` : null,
    content: content,
    defaultCollapsed: true
  });
}

/**
 * 构建单个参考条目卡片（双行紧凑布局）
 */
function buildReferenceCard(ref, index, pool, preset) {
  const card = mainDoc.createElement('div');
  card.className = 'at-ref-card';
  card.dataset.refIndex = index;
  card.style.cssText = `
    background: var(--bg-tertiary);
    border-radius: 4px;
    padding: 8px 10px;
    border-left: 3px solid var(--accent-secondary);
  `;

  // ═══ 第一行：显示名 ← 关键词 ═══
  const row1 = mainDoc.createElement('div');
  row1.style.cssText = `
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 6px;
    flex-wrap: wrap;
  `;

  // 显示名（可编辑）
  const labelInput = mainDoc.createElement('input');
  labelInput.type = 'text';
  labelInput.className = 'at-form-input';
  labelInput.style.cssText = 'flex: 0 0 auto; width: 120px; font-size: 13px; padding: 4px 8px;';
  labelInput.value = ref.label || '';
  labelInput.placeholder = '显示名';
  labelInput.title = '显示名称（仅用于面板展示）';
  labelInput.addEventListener('input', (e) => {
    ref.label = e.target.value;
    markDirty();
  });
  row1.appendChild(labelInput);

  // 箭头
  const arrow1 = mainDoc.createElement('span');
  arrow1.style.color = 'var(--text-muted)';
  arrow1.textContent = '←';
  row1.appendChild(arrow1);

  // 关键词（可编辑）
  const keyInput = mainDoc.createElement('input');
  keyInput.type = 'text';
  keyInput.className = 'at-form-input';
  keyInput.style.cssText = 'flex: 1; min-width: 100px; font-size: 13px; padding: 4px 8px;';
  keyInput.value = ref.entryKey || '';
  keyInput.placeholder = '世界书关键词';
  keyInput.title = '用于匹配角色世界书中的条目';
  keyInput.addEventListener('input', (e) => {
    ref.entryKey = e.target.value;
    markDirty();
  });
  row1.appendChild(keyInput);

  card.appendChild(row1);

  // ═══ 第二行：→ 变量名 + 仅启用 + 删除 ═══
  const row2 = mainDoc.createElement('div');
  row2.style.cssText = `
    display: flex;
    align-items: center;
    gap: 8px;
  `;

  // 箭头
  const arrow2 = mainDoc.createElement('span');
  arrow2.style.color = 'var(--text-muted)';
  arrow2.textContent = '→';
  row2.appendChild(arrow2);

  // 变量名显示（带双花括号样式）
  const varContainer = mainDoc.createElement('div');
  varContainer.style.cssText = 'display: flex; align-items: center; gap: 2px;';

  const varPrefix = mainDoc.createElement('span');
  varPrefix.style.cssText = 'color: var(--accent-primary); font-family: monospace;';
  varPrefix.textContent = '{{';
  varContainer.appendChild(varPrefix);

  const varInput = mainDoc.createElement('input');
  varInput.type = 'text';
  varInput.className = 'at-form-input';
  varInput.style.cssText = 'width: 100px; font-size: 13px; padding: 4px 6px; font-family: monospace;';
  varInput.value = ref.varName || '';
  varInput.placeholder = 'varName';
  varInput.title = '任务中引用此条目的变量名';
  varInput.addEventListener('input', (e) => {
    const newVarName = e.target.value;
    // 检查变量名冲突
    const conflict = pool.some((r, i) => i !== index && r.varName === newVarName);
    if (conflict) {
      varInput.style.borderColor = 'var(--error)';
      varInput.title = '变量名已被其他条目使用';
    } else {
      varInput.style.borderColor = '';
      varInput.title = '任务中引用此条目的变量名';
      ref.varName = newVarName;
      markDirty();
    }
  });
  varContainer.appendChild(varInput);

  const varSuffix = mainDoc.createElement('span');
  varSuffix.style.cssText = 'color: var(--accent-primary); font-family: monospace;';
  varSuffix.textContent = '}}';
  varContainer.appendChild(varSuffix);

  row2.appendChild(varContainer);

  // 弹性空间
  const spacer = mainDoc.createElement('div');
  spacer.style.flex = '1';
  row2.appendChild(spacer);

  // 仅启用复选框
  const enabledCheck = buildCheckbox({
    label: '仅启用',
    checked: ref.requireEnabled || false,
    onChange: (v) => {
      ref.requireEnabled = v;
      markDirty();
    }
  });
  enabledCheck.title = '勾选后仅读取处于启用状态的条目';
  enabledCheck.style.fontSize = '12px';
  row2.appendChild(enabledCheck);

  // 删除按钮
  const deleteBtn = mainDoc.createElement('button');
  deleteBtn.className = 'at-btn at-btn-sm';
  deleteBtn.textContent = '✕';
  deleteBtn.title = '删除此参考条目';
  deleteBtn.style.cssText = 'padding: 2px 8px; min-width: auto;';
  deleteBtn.addEventListener('click', async () => {
    // 检查是否有任务使用此参考条目
    const usedByTasks = (preset.tasks || []).filter(
      t => (t.dataSource?.useReferences || []).includes(ref.varName)
    );

    // 检查变量更新任务
    const usedByVarTasks = (preset.varUpdateTasks || []).filter(
      t => (t.dataSource?.useReferences || []).includes(ref.varName)
    );

    // 检查摘要任务
    const usedBySummary = (preset.summaryTask?.update?.dataSource?.useReferences || [])
      .includes(ref.varName);

    // 汇总所有使用者
    const allUsers = [
      ...usedByTasks.map(t => t.name),
      ...usedByVarTasks.map(t => `[变量更新] ${t.name}`),
      ...(usedBySummary ? ['[摘要任务]'] : [])
    ];

    if (allUsers.length > 0) {
      const userNames = allUsers.join('、');
      const confirmed = await SillyTavern.callGenericPopup(
        `参考条目「${ref.label || ref.varName}」正在被以下功能使用：\n${userNames}\n\n删除后这些功能将无法读取该条目。确定删除吗？`,
        SillyTavern.POPUP_TYPE.CONFIRM
      );
      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
        return;
      }
      // 从普通任务中移除引用
      for (const task of usedByTasks) {
        task.dataSource.useReferences = task.dataSource.useReferences.filter(
          v => v !== ref.varName
        );
      }
      // 从变量更新任务中移除引用
      for (const task of usedByVarTasks) {
        task.dataSource.useReferences = task.dataSource.useReferences.filter(
          v => v !== ref.varName
        );
      }
      // 从摘要任务中移除引用
      if (usedBySummary && preset.summaryTask?.update?.dataSource?.useReferences) {
        preset.summaryTask.update.dataSource.useReferences =
          preset.summaryTask.update.dataSource.useReferences.filter(v => v !== ref.varName);
      }
    }

    // 从池中删除（使用varName定位，避免索引错位）
    const targetIndex = pool.findIndex(r => r.varName === ref.varName);
    if (targetIndex !== -1) {
      pool.splice(targetIndex, 1);
    }
    markDirty();

    // 局部更新：移除DOM而非整页刷新
    card.remove();

    // 更新徽章数量
    updateRefPoolBadge();
  });
  row2.appendChild(deleteBtn);

  card.appendChild(row2);

  return card;
}

/**
 * 更新参考池徽章数量（局部更新辅助函数）
 */
function updateRefPoolBadge() {
  const preset = getCurrentEditingPreset();
  const count = preset?.referencePool?.length || 0;
  const badge = mainDoc.querySelector('#at-overlay .at-section[data-section-id="creator_reference"] .at-section-badge');
  if (badge) {
    badge.textContent = count > 0 ? `${count}个` : '';
    badge.style.display = count > 0 ? '' : 'none';
  }
}

