/**
 * 创建空白任务
 */
function createEmptyTask() {
  const taskId = generateUUID();
  return {
    id: taskId,
    name: '新任务',
    enabled: true,
    taskType: 'worldbook_update',
    taskBrief: '',
    trigger: {
      type: 'cycle',
      positions: [5],
      condition: {
        groupRelation: 'AND',
        groups: []
      }
    },
    triggerOnChatStart: false,
    dataSource: {
      useReferences: [],
      useTaskOutputs: [taskId]  // 默认引用自己上一轮的输出
    },
    prompt: {
      entryKey: ''
    },
    output: {
      entryKey: '',
      triggerKeys: [],
      xmlTag: 'auto_output',
      disableSourceEntry: true,
      updateMode: 'replace',
      appendConfig: {
        addTimestamp: true,
        separator: '\n\n',
        maxLength: null
      },
      attributes: {
        enabled: true,
        constant: true,
        position: 1,
        depth: 4,
        role: 'system',
        order: 100,
        probability: 100,
        preventRecursionIn: false,
        preventRecursionOut: false,
        sticky: null,
        cooldown: null,
        delay: null
      }
    },
    apiPresetId: null,
    maxRetries: 3
  };
}

/**
 * 构建单个任务列表项
 */
function buildTaskListItem(task, index, total, preset) {
  const isExpanded = expandedTaskId === task.id;

  const container = mainDoc.createElement('div');
  container.className = 'at-task-item';
  container.style.cssText = `
    margin-bottom: 8px;
    background: var(--bg-tertiary);
    border-radius: 6px;
    border-left: 3px solid ${task.enabled ? 'var(--accent-secondary)' : 'var(--border-color)'};
    overflow: hidden;
  `;

  // 任务头部（始终显示）
  const header = mainDoc.createElement('div');
  header.className = 'at-task-header';
  header.style.cssText = `
    display: flex;
    align-items: center;
    padding: 10px 12px;
    cursor: pointer;
    gap: 8px;
  `;

  // 启用复选框
  const enableCheck = mainDoc.createElement('input');
  enableCheck.type = 'checkbox';
  enableCheck.checked = task.enabled;
  enableCheck.style.cssText = 'width: 16px; height: 16px; accent-color: var(--accent-primary);';
  enableCheck.addEventListener('click', (e) => {
    e.stopPropagation();
  });
  enableCheck.addEventListener('change', (e) => {
    task.enabled = e.target.checked;
    markDirty();
    renderPage('creator');
  });
  header.appendChild(enableCheck);

  // 排序按钮
  const sortBtns = mainDoc.createElement('div');
  sortBtns.className = 'at-flex';
  sortBtns.style.gap = '2px';

  const upBtn = mainDoc.createElement('button');
  upBtn.className = 'at-btn at-btn-icon at-btn-sm';
  upBtn.textContent = '↑';
  upBtn.disabled = index === 0;
  upBtn.title = '上移';
  upBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (index > 0) {
      [preset.tasks[index - 1], preset.tasks[index]] = [preset.tasks[index], preset.tasks[index - 1]];
      markDirty();
      renderPage('creator');
    }
  });
  sortBtns.appendChild(upBtn);

  const downBtn = mainDoc.createElement('button');
  downBtn.className = 'at-btn at-btn-icon at-btn-sm';
  downBtn.textContent = '↓';
  downBtn.disabled = index === total - 1;
  downBtn.title = '下移';
  downBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (index < total - 1) {
      [preset.tasks[index], preset.tasks[index + 1]] = [preset.tasks[index + 1], preset.tasks[index]];
      markDirty();
      renderPage('creator');
    }
  });
  sortBtns.appendChild(downBtn);
  header.appendChild(sortBtns);

  // 序号
  const indexSpan = mainDoc.createElement('span');
  indexSpan.style.cssText = 'color: var(--text-muted); min-width: 24px;';
  indexSpan.textContent = `${index + 1}.`;
  header.appendChild(indexSpan);

  // 任务名称（添加data属性用于实时更新）
  const nameSpan = mainDoc.createElement('span');
  nameSpan.style.cssText = 'flex: 1; font-weight: 500;';
  nameSpan.textContent = task.name;
  nameSpan.dataset.taskNameDisplay = task.id; // 用于定位更新
  header.appendChild(nameSpan);

  // 触发类型标签
  const triggerBadge = mainDoc.createElement('span');
  triggerBadge.className = 'at-section-badge';
  if (task.trigger?.type === 'cycle') {
    const positions = task.trigger.positions || [];
    triggerBadge.textContent = positions.length > 0 ? `@${positions.join(',')}` : '周期';
  } else if (task.trigger?.type === 'variable') {
    triggerBadge.textContent = '变量';
  }
  header.appendChild(triggerBadge);

  // 展开/折叠指示
  const toggleIcon = mainDoc.createElement('span');
  toggleIcon.style.cssText = `
    color: var(--text-muted);
    transition: transform 0.2s;
    transform: rotate(${isExpanded ? '0' : '-90'}deg);
  `;
  toggleIcon.textContent = '▼';
  header.appendChild(toggleIcon);

  // 点击头部切换展开状态
  header.addEventListener('click', () => {
    expandedTaskId = isExpanded ? null : task.id;
    renderPage('creator');
  });

  container.appendChild(header);

  // 展开的编辑表单
  if (isExpanded) {
    container.appendChild(buildTaskEditForm(task, preset));
  }

  return container;
}

/**
 * 构建任务编辑表单
 */
function buildTaskEditForm(task, preset) {
  const form = mainDoc.createElement('div');
  form.className = 'at-task-form';
  form.style.cssText = `
    padding: 12px;
    border-top: 1px solid var(--border-light);
    background: var(--bg-secondary);
  `;

  // ═══════════════════════════════════════
  // 基础信息
  // ═══════════════════════════════════════
  const basicSection = mainDoc.createElement('div');
  basicSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">基础信息</div>';

  // 任务名称
  basicSection.appendChild(buildInput({
    label: '任务名称',
    value: task.name,
    onChange: (v) => {
      task.name = v;
      markDirty();
      // 实时更新标题显示
      const nameDisplay = mainDoc.querySelector(`[data-task-name-display="${task.id}"]`);
      if (nameDisplay) nameDisplay.textContent = v;
    }
  }));

  // 任务类型
  basicSection.appendChild(buildSelect({
    label: '任务类型',
    value: task.taskType,
    choices: [
      { value: 'worldbook_update', label: '世界书更新' },
      { value: 'direct_output', label: '直接输出' }
    ],
    onChange: (v) => { task.taskType = v; markDirty(); renderPage('creator'); }
  }));

  // 任务简述（带说明）
  const briefGroup = buildTextarea({
    label: '任务简述（可选）',
    value: task.taskBrief || '',
    placeholder: '例如：更新角色当前状态',
    rows: 2,
    onChange: (v) => { task.taskBrief = v; markDirty(); }
  });
  briefGroup.title = '简短的一句话概述，在开头用于强调任务。详细指令请写在「提示词条目」中';
  basicSection.appendChild(briefGroup);

  form.appendChild(basicSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 触发设置
  // ═══════════════════════════════════════
  const triggerSection = mainDoc.createElement('div');
  triggerSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">触发设置</div>';

  // 触发类型
  triggerSection.appendChild(buildSelect({
    label: '触发类型',
    value: task.trigger?.type || 'cycle',
    choices: [
      { value: 'cycle', label: '周期触发' },
      { value: 'variable', label: '变量条件' }
    ],
    onChange: (v) => {
      if (!task.trigger) task.trigger = {};
      task.trigger.type = v;
      markDirty();
      renderPage('creator');
    }
  }));

  // 根据触发类型显示不同编辑器
  if (task.trigger?.type === 'cycle') {
    triggerSection.appendChild(buildPositionsEditor(task));
  } else if (task.trigger?.type === 'variable') {
    triggerSection.appendChild(buildConditionEditor(task));
  }

  // 聊天开始触发
  const chatStartCheck = buildCheckbox({
    label: '新聊天开始时也触发',
    checked: task.triggerOnChatStart || false,
    onChange: (v) => { task.triggerOnChatStart = v; markDirty(); }
  });
  chatStartCheck.title = '独立于上述触发条件，仅在创建全新空聊天后的首条AI回复时触发';
  chatStartCheck.style.marginTop = '8px';
  triggerSection.appendChild(chatStartCheck);

  form.appendChild(triggerSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 数据源
  // ═══════════════════════════════════════
  const dataSection = mainDoc.createElement('div');
  dataSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">数据源</div>';

  // 参考条目（从参考池选择）
  const refPool = preset?.referencePool || [];
  if (refPool.length > 0) {
    const refLabel = mainDoc.createElement('label');
    refLabel.className = 'at-form-label';
    refLabel.textContent = '参考条目';
    dataSection.appendChild(refLabel);

    const refContainer = mainDoc.createElement('div');
    refContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px;';

    for (const ref of refPool) {
      const refCheck = buildCheckbox({
        label: ref.label || ref.varName,
        checked: (task.dataSource?.useReferences || []).includes(ref.varName),
        onChange: (checked) => {
          if (!task.dataSource) task.dataSource = { useReferences: [], useTaskOutputs: [] };
          if (checked) {
            if (!task.dataSource.useReferences.includes(ref.varName)) {
              task.dataSource.useReferences.push(ref.varName);
            }
          } else {
            task.dataSource.useReferences = task.dataSource.useReferences.filter(v => v !== ref.varName);
          }
          markDirty();
        }
      });
      refContainer.appendChild(refCheck);
    }
    dataSection.appendChild(refContainer);
  } else {
    const noRefHint = mainDoc.createElement('div');
    noRefHint.className = 'at-text-muted';
    noRefHint.style.marginBottom = '12px';
    noRefHint.textContent = '参考条目: 无（请先在"参考条目池"中添加）';
    dataSection.appendChild(noRefHint);
  }

  // ═══ 引用任务输出（聊天世界书）═══
  // 收集可选的任务输出
  const taskOutputChoices = [];

  // 1. 添加任务的输出（包括自己的上一轮）
  for (const otherTask of preset.tasks || []) {
    const isSelf = otherTask.id === task.id;
    const hasOutput = !!otherTask.output?.entryKey;

    // 自己始终显示（即使未配置输出），其他任务需要有输出配置
    if (!isSelf && !hasOutput) continue;

    taskOutputChoices.push({
      id: otherTask.id,
      label: isSelf
        ? `${otherTask.name}（自己·上一轮）${hasOutput ? '' : ' ⚠️未配置输出'}`
        : otherTask.name,
      hint: otherTask.output?.entryKey || '待配置'
    });
  }

  // 2. 添加摘要输出（如果摘要功能已启用）
  const summaryEnabled = preset.summaryTask?.update?.enabled;
  if (summaryEnabled) {
    taskOutputChoices.push({
      id: 'summary:events',
      label: '剧情摘要 - EVENTS',
      hint: 'AUTO_剧情摘要_EVENTS'
    });
    taskOutputChoices.push({
      id: 'summary:relations',
      label: '剧情摘要 - RELATIONS',
      hint: 'AUTO_剧情摘要_RELATIONS'
    });
    taskOutputChoices.push({
      id: 'summary:active',
      label: '剧情摘要 - ACTIVE',
      hint: 'AUTO_剧情摘要_ACTIVE'
    });
  }

  // 渲染复选框组
  if (taskOutputChoices.length > 0) {
    const taskOutputLabel = mainDoc.createElement('label');
    taskOutputLabel.className = 'at-form-label';
    taskOutputLabel.textContent = '引用任务输出（聊天世界书）';
    dataSection.appendChild(taskOutputLabel);

    const taskOutputContainer = mainDoc.createElement('div');
    taskOutputContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px;';

    // 确保 useTaskOutputs 数组存在
    if (!task.dataSource) task.dataSource = { useReferences: [], useTaskOutputs: [] };
    if (!task.dataSource.useTaskOutputs) task.dataSource.useTaskOutputs = [];

    for (const choice of taskOutputChoices) {
      const checkWrapper = mainDoc.createElement('label');
      checkWrapper.className = 'at-form-checkbox';
      checkWrapper.title = `关键词: ${choice.hint}`;
      checkWrapper.style.cssText = 'flex: 0 0 auto; max-width: 100%;';

      const checkbox = mainDoc.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.dataSource.useTaskOutputs.includes(choice.id);
      checkbox.addEventListener('change', (e) => {
        if (e.target.checked) {
          if (!task.dataSource.useTaskOutputs.includes(choice.id)) {
            task.dataSource.useTaskOutputs.push(choice.id);
          }
        } else {
          task.dataSource.useTaskOutputs = task.dataSource.useTaskOutputs.filter(
            id => id !== choice.id
          );
        }
        markDirty();
      });

      const labelText = mainDoc.createElement('span');
      labelText.textContent = choice.label;

      checkWrapper.appendChild(checkbox);
      checkWrapper.appendChild(labelText);
      taskOutputContainer.appendChild(checkWrapper);
    }

    dataSection.appendChild(taskOutputContainer);
  } else {
    // 没有可选的任务输出时显示提示
    const noTaskOutputHint = mainDoc.createElement('div');
    noTaskOutputHint.className = 'at-text-muted';
    noTaskOutputHint.style.marginBottom = '12px';
    noTaskOutputHint.textContent = '引用任务输出: 无可用（需要其他任务配置输出条目，或启用摘要功能）';
    dataSection.appendChild(noTaskOutputHint);
  }

  form.appendChild(dataSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 提示词
  // ═══════════════════════════════════════
  const promptSection = mainDoc.createElement('div');
  promptSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">提示词</div>';

  // 提示词条目关键词（带世界书选取）
  const promptGroup = mainDoc.createElement('div');
  promptGroup.className = 'at-form-group';

  const promptLabel = mainDoc.createElement('label');
  promptLabel.className = 'at-form-label';
  promptLabel.textContent = '提示词条目关键词';
  promptGroup.appendChild(promptLabel);

  const promptRow = mainDoc.createElement('div');
  promptRow.className = 'at-flex at-gap-sm';

  const promptInput = mainDoc.createElement('input');
  promptInput.type = 'text';
  promptInput.className = 'at-form-input';
  promptInput.style.flex = '1';
  promptInput.value = task.prompt?.entryKey || '';
  promptInput.placeholder = '角色世界书中的条目关键词';
  promptInput.title = '角色世界书中存放该任务详细指令的条目。引擎会读取该条目内容发送给AI';
  promptInput.addEventListener('input', (e) => {
    if (!task.prompt) task.prompt = {};
    task.prompt.entryKey = e.target.value;
    markDirty();
  });
  promptRow.appendChild(promptInput);

  // 从世界书选取按钮
  const selectPromptBtn = buildButton({
    text: '选取',
    small: true,
    title: '从世界书选取条目',
    onClick: () => {
      // 切换选择器显示状态
      if (promptSelectorContainer.style.display === 'none') {
        promptSelectorContainer.style.display = 'block';
        loadPromptSelector();
      } else {
        promptSelectorContainer.style.display = 'none';
      }
    }
  });
  promptRow.appendChild(selectPromptBtn);

  promptGroup.appendChild(promptRow);

  // 选择器容器
  const promptSelectorContainer = mainDoc.createElement('div');
  promptSelectorContainer.style.cssText = `
    display: none;
    margin-top: 8px;
    background: var(--bg-secondary);
    border: 1px solid var(--border-light);
    border-radius: 6px;
    overflow: hidden;
  `;

  // 加载选择器
  async function loadPromptSelector() {
    promptSelectorContainer.innerHTML = '<div class="at-text-muted" style="text-align: center; padding: 20px;">加载中...</div>';

    const selector = await buildWorldbookEntrySelector((selectedEntries) => {
      // 修复：参数是数组，取第一个元素
      if (!selectedEntries || selectedEntries.length === 0) return;
      const selected = selectedEntries[0];

      // 填充选中的关键词
      promptInput.value = selected.primaryKey;
      if (!task.prompt) task.prompt = {};
      task.prompt.entryKey = selected.primaryKey;
      markDirty();

      // 关闭选择器
      promptSelectorContainer.style.display = 'none';
      toastr.info(`已选择: ${selected.name || selected.primaryKey}`);
    }, []);  // 不过滤已添加的

    promptSelectorContainer.innerHTML = '';
    promptSelectorContainer.appendChild(selector);
  }

  promptGroup.appendChild(promptSelectorContainer);
  promptSection.appendChild(promptGroup);

  form.appendChild(promptSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 输出设置（仅worldbook_update）
  // ═══════════════════════════════════════
  if (task.taskType === 'worldbook_update') {
    const outputSection = mainDoc.createElement('div');
    outputSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">输出设置</div>';

    // 输出条目关键词
    const outputKeyInput = buildInput({
      label: '输出条目关键词',
      value: task.output?.entryKey || '',
      placeholder: '输出写入聊天世界书的条目keys',
      onChange: (v) => {
        if (!task.output) task.output = {};
        task.output.entryKey = v;
        markDirty();
      }
    });
    outputKeyInput.title = 'AI的输出内容会写入聊天世界书，以此关键词作为条目的keys';
    outputSection.appendChild(outputKeyInput);

    // 额外触发词
    outputSection.appendChild(buildStringListEditor({
      label: '额外触发词',
      values: task.output?.triggerKeys || [],
      placeholder: '添加触发词',
      onChange: (values) => {
        if (!task.output) task.output = {};
        task.output.triggerKeys = values;
        markDirty();
      }
    }));

    // XML标签名
    const xmlTagInput = buildInput({
      label: 'XML标签名',
      value: task.output?.xmlTag || 'auto_output',
      placeholder: 'auto_output（不要带<>）',
      onChange: (v) => {
        if (!task.output) task.output = {};
        task.output.xmlTag = v || 'auto_output';
        markDirty();
      }
    });
    xmlTagInput.title = '引擎会让AI用<标签名>内容</标签名>格式输出，然后提取内容写入世界书';
    outputSection.appendChild(xmlTagInput);

    // 更新模式选择
    outputSection.appendChild(buildSelect({
      label: '更新模式',
      value: task.output?.updateMode || 'replace',
      choices: [
        { value: 'replace', label: '全量更新（覆盖原内容）' },
        { value: 'append', label: '增量更新（追加到末尾）' }
      ],
      onChange: (v) => {
        if (!task.output) task.output = {};
        task.output.updateMode = v;
        markDirty();
        renderPage('creator');
      }
    }));

    // 增量更新配置（仅在 append 模式下显示）
    if (task.output?.updateMode === 'append') {
      const appendConfigSection = mainDoc.createElement('div');
      appendConfigSection.style.cssText = `
        margin: 8px 0 12px 0;
        padding: 10px;
        background: var(--bg-tertiary);
        border-radius: 4px;
        border-left: 3px solid var(--accent-secondary);
      `;

      const appendTitle = mainDoc.createElement('div');
      appendTitle.style.cssText = 'font-size: 12px; color: var(--text-secondary); margin-bottom: 8px;';
      appendTitle.textContent = '增量更新配置';
      appendConfigSection.appendChild(appendTitle);

      // 确保 appendConfig 存在
      if (!task.output.appendConfig) {
        task.output.appendConfig = { addTimestamp: true, separator: '\n\n', maxLength: null };
      }

      // 添加时间戳
      appendConfigSection.appendChild(buildCheckbox({
        label: '添加时间戳注释',
        checked: task.output.appendConfig.addTimestamp ?? true,
        onChange: (v) => {
          task.output.appendConfig.addTimestamp = v;
          markDirty();
        }
      }));

      // 分隔符
      const sepGroup = mainDoc.createElement('div');
      sepGroup.className = 'at-form-group';
      sepGroup.style.marginTop = '8px';

      const sepLabel = mainDoc.createElement('label');
      sepLabel.className = 'at-form-label';
      sepLabel.textContent = '分隔符';
      sepGroup.appendChild(sepLabel);

      const sepInput = mainDoc.createElement('input');
      sepInput.type = 'text';
      sepInput.className = 'at-form-input';
      sepInput.value = task.output.appendConfig.separator ?? '\\n\\n';
      sepInput.placeholder = '\\n\\n';
      sepInput.title = '新旧内容之间的分隔符，\\n表示换行';
      sepInput.addEventListener('input', (e) => {
        // 将 \n 转换为实际换行符
        task.output.appendConfig.separator = e.target.value.replace(/\\n/g, '\n');
        markDirty();
      });
      sepGroup.appendChild(sepInput);

      const sepHint = mainDoc.createElement('div');
      sepHint.className = 'at-text-muted';
      sepHint.style.cssText = 'font-size: 11px; margin-top: 2px;';
      sepHint.textContent = '使用 \\n 表示换行';
      sepGroup.appendChild(sepHint);

      appendConfigSection.appendChild(sepGroup);

      // 最大长度
      const maxLenGroup = mainDoc.createElement('div');
      maxLenGroup.className = 'at-form-group';
      maxLenGroup.style.marginTop = '8px';

      const maxLenLabel = mainDoc.createElement('label');
      maxLenLabel.className = 'at-form-label';
      maxLenLabel.textContent = '长度警告阈值（字符）';
      maxLenGroup.appendChild(maxLenLabel);

      const maxLenRow = mainDoc.createElement('div');
      maxLenRow.className = 'at-flex at-gap-sm at-flex-center';

      const maxLenInput = mainDoc.createElement('input');
      maxLenInput.type = 'number';
      maxLenInput.className = 'at-form-input';
      maxLenInput.style.width = '120px';
      maxLenInput.value = task.output.appendConfig.maxLength || '';
      maxLenInput.placeholder = '留空不限制';
      maxLenInput.min = '1000';
      maxLenInput.addEventListener('input', (e) => {
        const val = e.target.value ? parseInt(e.target.value) : null;
        task.output.appendConfig.maxLength = val;
        markDirty();
      });
      maxLenRow.appendChild(maxLenInput);

      const maxLenHint = mainDoc.createElement('span');
      maxLenHint.className = 'at-text-muted';
      maxLenHint.style.fontSize = '12px';
      maxLenHint.textContent = '超过时弹出警告';
      maxLenRow.appendChild(maxLenHint);

      maxLenGroup.appendChild(maxLenRow);
      appendConfigSection.appendChild(maxLenGroup);

      outputSection.appendChild(appendConfigSection);
    }

    // 禁用源条目
    outputSection.appendChild(buildCheckbox({
      label: '禁用角色世界书同名条目',
      checked: task.output?.disableSourceEntry ?? true,
      onChange: (v) => {
        if (!task.output) task.output = {};
        task.output.disableSourceEntry = v;
        markDirty();
      }
    }));

    // 条目属性编辑器
    outputSection.appendChild(buildEntryAttributesEditor(task.output?.attributes, (attrs) => {
      if (!task.output) task.output = {};
      task.output.attributes = attrs;
      markDirty();
    }, `task_${task.id}`));  // ← 添加第三个参数

    form.appendChild(outputSection);
    form.appendChild(buildDivider());
  }

  // ═══════════════════════════════════════
  // API预设
  // ═══════════════════════════════════════
  const apiSection = mainDoc.createElement('div');
  apiSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">API预设</div>';

  const apiChoices = [
    { value: '', label: '使用默认预设' },
    ...(apiPresetsDraft?.presets || []).map(p => ({
      value: p.id,
      label: p.name + (p.id === apiPresetsDraft?.defaultPresetId ? ' (默认)' : '')
    }))
  ];

  apiSection.appendChild(buildSelect({
    label: 'API预设',
    value: task.apiPresetId || '',
    choices: apiChoices,
    onChange: (v) => {
      task.apiPresetId = v || null;
      markDirty();
    }
  }));

  form.appendChild(apiSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 执行选项
  // ═══════════════════════════════════════
  const execSection = mainDoc.createElement('div');
  execSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">执行选项</div>';

  // 最大重试次数
  const retryGroup = mainDoc.createElement('div');
  retryGroup.className = 'at-form-group';

  const retryLabel = mainDoc.createElement('label');
  retryLabel.className = 'at-form-label';
  retryLabel.textContent = '最大重试次数';
  retryGroup.appendChild(retryLabel);

  const retryRow = mainDoc.createElement('div');
  retryRow.className = 'at-flex at-gap-sm at-flex-center';

  const retryInput = mainDoc.createElement('input');
  retryInput.type = 'number';
  retryInput.className = 'at-form-input';
  retryInput.style.width = '80px';
  retryInput.min = '1';
  retryInput.max = '5';
  retryInput.value = task.maxRetries ?? 3;
  retryInput.title = '当AI输出格式无效时，最多重试几次';
  retryInput.addEventListener('input', (e) => {
    const val = parseInt(e.target.value);
    task.maxRetries = Math.max(1, Math.min(5, val || 3));
    markDirty();
  });
  retryRow.appendChild(retryInput);

  const retryHint = mainDoc.createElement('span');
  retryHint.className = 'at-text-muted';
  retryHint.style.marginLeft = '8px';
  retryHint.textContent = '次（AI输出格式无效时重试）';
  retryRow.appendChild(retryHint);

  retryGroup.appendChild(retryRow);
  execSection.appendChild(retryGroup);

  form.appendChild(execSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 删除任务按钮
  // ═══════════════════════════════════════
  const deleteSection = mainDoc.createElement('div');
  deleteSection.style.textAlign = 'right';

  deleteSection.appendChild(buildButton({
    text: '删除任务',
    onClick: async () => {
      const confirmed = await SillyTavern.callGenericPopup(
        `确定删除任务「${task.name}」吗？`,
        SillyTavern.POPUP_TYPE.CONFIRM
      );
      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) return;

      preset.tasks = preset.tasks.filter(t => t.id !== task.id);
      expandedTaskId = null;
      markDirty();
      renderPage('creator');
      toastr.info('任务已删除');
    }
  }));

  form.appendChild(deleteSection);

  return form;
}

