/**
 * 构建触发位置编辑器
 */
function buildPositionsEditor(task) {
  const container = mainDoc.createElement('div');
  container.className = 'at-form-group';

  const label = mainDoc.createElement('label');
  label.className = 'at-form-label';
  label.textContent = '触发位置';
  container.appendChild(label);

  const positions = task.trigger?.positions || [];

  // 当前位置显示
  const tagsContainer = mainDoc.createElement('div');
  tagsContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px;';

  for (const pos of positions) {
    const tag = mainDoc.createElement('span');
    tag.className = 'at-section-badge';
    tag.style.cssText = 'display: inline-flex; align-items: center; gap: 4px;';
    tag.innerHTML = `${pos} <span style="cursor: pointer; opacity: 0.7;" data-pos="${pos}">×</span>`;

    tag.querySelector('span').addEventListener('click', () => {
      task.trigger.positions = positions.filter(p => p !== pos);
      markDirty();
      renderPage('creator');
    });

    tagsContainer.appendChild(tag);
  }

  if (positions.length === 0) {
    tagsContainer.innerHTML = '<span class="at-text-muted">暂无触发位置</span>';
  }

  container.appendChild(tagsContainer);

  // 添加位置
  const addContainer = mainDoc.createElement('div');
  addContainer.className = 'at-flex at-gap-sm';

  const input = mainDoc.createElement('input');
  input.type = 'number';
  input.className = 'at-form-input';
  input.style.width = '100px';
  input.placeholder = '位置';
  input.min = '1';

  const addBtn = buildButton({
    text: '添加',
    small: true,
    onClick: () => {
      const val = parseInt(input.value);
      if (!val || val < 1) {
        toastr.warning('请输入有效的位置（正整数）');
        return;
      }
      if (positions.includes(val)) {
        toastr.warning('该位置已存在');
        return;
      }
      if (!task.trigger) task.trigger = { type: 'cycle', positions: [] };
      task.trigger.positions = [...positions, val].sort((a, b) => a - b);
      markDirty();
      renderPage('creator');
    }
  });

  addContainer.appendChild(input);
  addContainer.appendChild(addBtn);
  container.appendChild(addContainer);

  return container;
}

