// 变量条件编辑器
// ─────────────────────────────────────────────────────────────────

/**
 * 构建变量条件编辑器
 */
function buildConditionEditor(task) {
  const container = mainDoc.createElement('div');
  container.className = 'at-form-group';

  const label = mainDoc.createElement('label');
  label.className = 'at-form-label';
  label.textContent = '触发条件';
  container.appendChild(label);

  // 确保condition结构存在
  if (!task.trigger) task.trigger = { type: 'variable', condition: { groupRelation: 'AND', groups: [] } };
  if (!task.trigger.condition) task.trigger.condition = { groupRelation: 'AND', groups: [] };

  const condition = task.trigger.condition;

  // 组间关系
  const relationContainer = mainDoc.createElement('div');
  relationContainer.style.marginBottom = '12px';
  relationContainer.appendChild(buildSelect({
    label: '组间关系',
    value: condition.groupRelation || 'AND',
    choices: [
      { value: 'AND', label: 'AND (全部满足)' },
      { value: 'OR', label: 'OR (任一满足)' }
    ],
    onChange: (v) => {
      condition.groupRelation = v;
      markDirty();
    }
  }));
  container.appendChild(relationContainer);

  // 条件组列表
  const groups = condition.groups || [];

  for (let gi = 0; gi < groups.length; gi++) {
    container.appendChild(buildConditionGroup(groups[gi], gi, condition, task));
  }

  // 添加条件组按钮
  if (groups.length < 3) {
    const addGroupBtn = buildButton({
      text: '+ 添加条件组',
      small: true,
      onClick: () => {
        condition.groups.push({
          not: false,
          relation: 'AND',
          conditions: [{ variable: '', operator: '=', value: '' }]
        });
        markDirty();
        renderPage('creator');
      }
    });
    addGroupBtn.style.marginTop = '8px';
    container.appendChild(addGroupBtn);
  }

  // 变量列表折叠区
  container.appendChild(buildVariableListPanel());

  return container;
}

/**
 * 构建单个条件组
 */
function buildConditionGroup(group, groupIndex, condition, task) {
  const groupEl = mainDoc.createElement('div');
  groupEl.style.cssText = `
    border: 1px solid var(--border-light);
    border-radius: 4px;
    padding: 10px;
    margin-bottom: 8px;
    background: var(--bg-tertiary);
  `;

  // 组头部
  const header = mainDoc.createElement('div');
  header.className = 'at-flex at-flex-between at-flex-center';
  header.style.marginBottom = '8px';

  const headerLeft = mainDoc.createElement('div');
  headerLeft.className = 'at-flex at-gap-sm at-flex-center';

  // NOT复选框
  const notCheck = buildCheckbox({
    label: 'NOT',
    checked: group.not || false,
    onChange: (v) => { group.not = v; markDirty(); }
  });
  headerLeft.appendChild(notCheck);

  // 组内关系
  const relationSelect = mainDoc.createElement('select');
  relationSelect.className = 'at-form-select';
  relationSelect.style.width = '120px';
  relationSelect.innerHTML = `
    <option value="AND" ${group.relation === 'AND' ? 'selected' : ''}>AND</option>
    <option value="OR" ${group.relation === 'OR' ? 'selected' : ''}>OR</option>
  `;
  relationSelect.addEventListener('change', (e) => {
    group.relation = e.target.value;
    markDirty();
  });
  headerLeft.appendChild(relationSelect);

  header.appendChild(headerLeft);

  // 删除组按钮
  const deleteGroupBtn = buildButton({
    text: '删除组',
    small: true,
    onClick: () => {
      condition.groups.splice(groupIndex, 1);
      markDirty();
      renderPage('creator');
    }
  });
  header.appendChild(deleteGroupBtn);

  groupEl.appendChild(header);

  // 条件列表
  const conditions = group.conditions || [];
  for (let ci = 0; ci < conditions.length; ci++) {
    groupEl.appendChild(buildSingleCondition(conditions[ci], ci, group));
  }

  // 添加条件按钮
  if (conditions.length < 4) {
    const addCondBtn = buildButton({
      text: '+ 添加条件',
      small: true,
      onClick: () => {
        group.conditions.push({ variable: '', operator: '=', value: '' });
        markDirty();
        renderPage('creator');
      }
    });
    groupEl.appendChild(addCondBtn);
  }

  return groupEl;
}

/**
 * 构建单个条件行（两行布局）
 */
function buildSingleCondition(cond, condIndex, group) {
  const container = mainDoc.createElement('div');
  container.style.cssText = `
    background: var(--bg-secondary);
    border-radius: 4px;
    padding: 8px;
    margin-bottom: 6px;
  `;

  // 第一行：变量名 + 删除按钮
  const row1 = mainDoc.createElement('div');
  row1.className = 'at-flex at-gap-sm';
  row1.style.marginBottom = '6px';
  row1.style.alignItems = 'flex-start';

  // 变量名标签
  const varLabel = mainDoc.createElement('span');
  varLabel.style.cssText = 'font-size: 12px; color: var(--text-muted); min-width: 45px; padding-top: 6px;';
  varLabel.textContent = '变量名:';
  row1.appendChild(varLabel);

  // 变量名输入 - 使用自适应高度的textarea
  const varInput = mainDoc.createElement('textarea');
  varInput.className = 'at-form-input';
  varInput.style.cssText = `
    flex: 1;
    min-height: 28px;
    max-height: 68px;
    resize: none;
    overflow-y: hidden;
    line-height: 1.4;
    padding: 6px 10px;
  `;
  varInput.rows = 1;
  varInput.placeholder = '如: stat_data.hp';
  varInput.value = cond.variable || '';
  varInput.title = '支持点号路径，如 stat_data.character.hp';

  // 自动调整高度函数
  function autoResizeTextarea() {
    varInput.style.height = 'auto';
    const newHeight = Math.min(Math.max(varInput.scrollHeight, 28), 68);
    varInput.style.height = newHeight + 'px';
  }

  varInput.addEventListener('input', (e) => {
    cond.variable = e.target.value;
    markDirty();
    autoResizeTextarea();
  });

  // 初始调整高度
  setTimeout(autoResizeTextarea, 0);

  row1.appendChild(varInput);

  // 删除按钮
  const delBtn = mainDoc.createElement('button');
  delBtn.className = 'at-btn at-btn-icon at-btn-sm';
  delBtn.style.marginTop = '2px';
  delBtn.textContent = '×';
  delBtn.title = '删除此条件';
  delBtn.addEventListener('click', () => {
    group.conditions.splice(condIndex, 1);
    if (group.conditions.length === 0) {
      group.conditions.push({ variable: '', operator: '=', value: '' });
    }
    markDirty();
    renderPage('creator');
  });
  row1.appendChild(delBtn);

  container.appendChild(row1);

  // 第二行：操作符 + 目标值
  const row2 = mainDoc.createElement('div');
  row2.className = 'at-flex at-gap-sm at-flex-center';

  // 操作符标签
  const opLabel = mainDoc.createElement('span');
  opLabel.style.cssText = 'font-size: 12px; color: var(--text-muted); min-width: 45px;';
  opLabel.textContent = '条件:';
  row2.appendChild(opLabel);

  // 操作符
  const opSelect = mainDoc.createElement('select');
  opSelect.className = 'at-form-select';
  opSelect.style.width = '100px';
  for (const op of OPERATOR_OPTIONS) {
    const option = mainDoc.createElement('option');
    option.value = op.value;
    option.textContent = op.label;
    if (op.value === cond.operator) option.selected = true;
    opSelect.appendChild(option);
  }
  opSelect.addEventListener('change', (e) => {
    cond.operator = e.target.value;
    markDirty();
  });
  row2.appendChild(opSelect);

  // 目标值
  const valInput = mainDoc.createElement('input');
  valInput.type = 'text';
  valInput.className = 'at-form-input';
  valInput.style.flex = '1';
  valInput.placeholder = '目标值';
  valInput.value = cond.value || '';
  valInput.addEventListener('input', (e) => {
    cond.value = e.target.value;
    markDirty();
  });
  row2.appendChild(valInput);

  container.appendChild(row2);

  return container;
}

/**
 * 构建变量列表面板
 */
function buildVariableListPanel() {
  const panel = mainDoc.createElement('details');
  panel.style.marginTop = '12px';

  const summary = mainDoc.createElement('summary');
  summary.style.cssText = 'cursor: pointer; color: var(--text-secondary); font-size: 13px;';
  summary.textContent = '展开变量列表';
  panel.appendChild(summary);

  const content = mainDoc.createElement('div');
  content.style.cssText = `
    max-height: 200px;
    overflow-y: auto;
    margin-top: 8px;
    padding: 8px;
    background: var(--bg-tertiary);
    border-radius: 4px;
    font-size: 12px;
  `;

  // 获取聊天变量
  const variables = getChatVariables();
  const flattened = flattenVariables(variables);

  if (flattened.length === 0) {
    content.innerHTML = '<div class="at-text-muted">当前聊天无变量</div>';
  } else {
    for (const { path, value } of flattened) {
      const item = mainDoc.createElement('div');
      item.style.cssText = `
        padding: 4px 6px;
        cursor: pointer;
        border-radius: 3px;
        display: flex;
        justify-content: space-between;
      `;
      item.innerHTML = `
        <span style="color: var(--accent-primary);">${path}</span>
        <span class="at-text-muted">${JSON.stringify(value)}</span>
      `;
      item.addEventListener('click', () => {
        // 复制路径到剪贴板
        navigator.clipboard.writeText(path).then(() => {
          toastr.info(`已复制: ${path}`);
        });
      });
      item.addEventListener('mouseenter', () => {
        item.style.background = 'var(--bg-hover)';
      });
      item.addEventListener('mouseleave', () => {
        item.style.background = 'transparent';
      });
      content.appendChild(item);
    }
  }

  panel.appendChild(content);

  // 展开时更新summary文字
  panel.addEventListener('toggle', () => {
    summary.textContent = panel.open ? '收起变量列表' : '展开变量列表';
  });

  return panel;
}

// ─────────────────────────────────────────────────────────────────
// 条目属性编辑器
// ─────────────────────────────────────────────────────────────────

/**
 * 构建条目属性编辑器
 * @param attributes - 当前属性对象
 * @param onChange - 属性变更回调
 * @param editorId - 编辑器唯一ID（用于记忆展开状态）
 */
function buildEntryAttributesEditor(attributes, onChange, editorId = 'default') {
  const container = mainDoc.createElement('div');
  container.style.marginTop = '12px';

  // 确保attributes存在
  const attrs = attributes || {
    enabled: true,
    constant: true,
    position: 1,
    depth: 4,
    role: 'system',
    order: 100,
    probability: 100,
    preventRecursionIn: false,
    preventRecursionOut: false,
    sticky: null,
    cooldown: null,
    delay: null
  };

  // 检查记忆的展开状态
  const isExpanded = expandedAttrEditors[editorId] ?? false;

  // 使用details折叠
  const details = mainDoc.createElement('details');
  if (isExpanded) {
    details.open = true;
  }

  // 监听展开/折叠状态变化
  details.addEventListener('toggle', () => {
    expandedAttrEditors[editorId] = details.open;
  });

  const summary = mainDoc.createElement('summary');
  summary.style.cssText = 'cursor: pointer; color: var(--text-secondary); font-size: 13px; margin-bottom: 8px;';
  summary.textContent = `条目属性 (${getPositionDisplayName(attrs.position)}, 深度${attrs.depth})`;
  details.appendChild(summary);

  const content = mainDoc.createElement('div');
  content.style.cssText = 'padding: 8px; background: var(--bg-tertiary); border-radius: 4px;';

  // 基础属性行
  const basicRow = mainDoc.createElement('div');
  basicRow.className = 'at-flex at-gap-md at-flex-center';
  basicRow.style.marginBottom = '8px';
  basicRow.style.flexWrap = 'wrap';

  basicRow.appendChild(buildCheckbox({
    label: '启用',
    checked: attrs.enabled ?? true,
    onChange: (v) => { attrs.enabled = v; onChange(attrs); }
  }));

  // 激活类型：蓝灯/绿灯单选
  const radioName = 'entryType_' + editorId;
  const typeContainer = mainDoc.createElement('div');
  typeContainer.className = 'at-flex at-gap-sm at-flex-center';
  typeContainer.innerHTML = '<span style="font-size: 13px; color: var(--text-secondary);">激活:</span>';

  const blueRadio = mainDoc.createElement('label');
  blueRadio.className = 'at-form-checkbox';
  blueRadio.style.marginLeft = '4px';
  const blueInput = mainDoc.createElement('input');
  blueInput.type = 'radio';
  blueInput.name = radioName;
  blueInput.checked = attrs.constant ?? true;
  blueInput.addEventListener('change', () => {
    attrs.constant = true;
    onChange(attrs);
    // 不调用 renderPage，而是局部更新：隐藏高级设置
    const advDetails = content.querySelector('.at-adv-details');
    if (advDetails) {
      advDetails.style.display = 'none';
    }
  });
  blueRadio.appendChild(blueInput);
  const blueText = mainDoc.createElement('span');
  blueText.style.color = 'var(--info)';
  blueText.textContent = '蓝灯';
  blueRadio.appendChild(blueText);
  typeContainer.appendChild(blueRadio);

  const greenRadio = mainDoc.createElement('label');
  greenRadio.className = 'at-form-checkbox';
  const greenInput = mainDoc.createElement('input');
  greenInput.type = 'radio';
  greenInput.name = radioName;
  greenInput.checked = !(attrs.constant ?? true);
  greenInput.addEventListener('change', () => {
    attrs.constant = false;
    onChange(attrs);
    // 不调用 renderPage，而是局部更新：显示高级设置
    const advDetails = content.querySelector('.at-adv-details');
    if (advDetails) {
      advDetails.style.display = 'block';
    }
  });
  greenRadio.appendChild(greenInput);
  const greenText = mainDoc.createElement('span');
  greenText.style.color = 'var(--success)';
  greenText.textContent = '绿灯';
  greenRadio.appendChild(greenText);
  typeContainer.appendChild(greenRadio);

  basicRow.appendChild(typeContainer);

  // 概率
  const probContainer = mainDoc.createElement('div');
  probContainer.className = 'at-flex at-gap-sm at-flex-center';
  const probLabel = mainDoc.createElement('span');
  probLabel.style.fontSize = '13px';
  probLabel.textContent = '概率:';
  probContainer.appendChild(probLabel);

  const probInputEl = mainDoc.createElement('input');
  probInputEl.type = 'number';
  probInputEl.className = 'at-form-input';
  probInputEl.style.width = '60px';
  probInputEl.min = '0';
  probInputEl.max = '100';
  probInputEl.value = attrs.probability ?? 100;
  probInputEl.addEventListener('input', (e) => {
    attrs.probability = parseInt(e.target.value) || 100;
    onChange(attrs);
  });
  probContainer.appendChild(probInputEl);

  const probUnit = mainDoc.createElement('span');
  probUnit.style.fontSize = '13px';
  probUnit.textContent = '%';
  probContainer.appendChild(probUnit);

  basicRow.appendChild(probContainer);

  content.appendChild(basicRow);

  // 位置设置
  const posRow = mainDoc.createElement('div');
  posRow.className = 'at-flex at-gap-sm';
  posRow.style.marginBottom = '8px';

  // 位置下拉
  const posSelect = mainDoc.createElement('select');
  posSelect.className = 'at-form-select';
  posSelect.style.flex = '1';
  for (const opt of POSITION_OPTIONS) {
    const option = mainDoc.createElement('option');
    option.value = opt.value;
    option.textContent = opt.label;
    if (opt.value === attrs.position) option.selected = true;
    posSelect.appendChild(option);
  }
  posSelect.addEventListener('change', (e) => {
    attrs.position = parseInt(e.target.value);
    onChange(attrs);
    // 局部更新：显示/隐藏深度和角色选择
    updateDepthRoleVisibility();
    // 更新summary文字
    summary.textContent = `条目属性 (${getPositionDisplayName(attrs.position)}, 深度${attrs.depth})`;
  });
  posRow.appendChild(posSelect);

  // 深度输入
  const depthInput = mainDoc.createElement('input');
  depthInput.type = 'number';
  depthInput.className = 'at-form-input at-depth-input';
  depthInput.style.width = '60px';
  depthInput.placeholder = '深度';
  depthInput.value = attrs.depth ?? 4;
  depthInput.addEventListener('input', (e) => {
    attrs.depth = parseInt(e.target.value) || 4;
    onChange(attrs);
    summary.textContent = `条目属性 (${getPositionDisplayName(attrs.position)}, 深度${attrs.depth})`;
  });
  posRow.appendChild(depthInput);

  // 角色选择
  const roleSelect = mainDoc.createElement('select');
  roleSelect.className = 'at-form-select at-role-select';
  roleSelect.style.width = '90px';
  ['system', 'user', 'assistant'].forEach(role => {
    const option = mainDoc.createElement('option');
    option.value = role;
    option.textContent = role;
    if (role === attrs.role) option.selected = true;
    roleSelect.appendChild(option);
  });
  roleSelect.addEventListener('change', (e) => {
    attrs.role = e.target.value;
    onChange(attrs);
  });
  posRow.appendChild(roleSelect);

  // 根据position显示/隐藏深度和角色
  function updateDepthRoleVisibility() {
    const show = attrs.position === 4;
    depthInput.style.display = show ? 'block' : 'none';
    roleSelect.style.display = show ? 'block' : 'none';
  }
  updateDepthRoleVisibility();

  content.appendChild(posRow);

  // 顺序
  const orderRow = mainDoc.createElement('div');
  orderRow.className = 'at-flex at-gap-sm at-flex-center';
  orderRow.style.marginBottom = '8px';

  const orderLabel = mainDoc.createElement('span');
  orderLabel.style.cssText = 'font-size: 13px; min-width: 40px;';
  orderLabel.textContent = '顺序:';
  orderRow.appendChild(orderLabel);

  const orderInput = mainDoc.createElement('input');
  orderInput.type = 'number';
  orderInput.className = 'at-form-input';
  orderInput.style.width = '80px';
  orderInput.value = attrs.order ?? 100;
  orderInput.addEventListener('input', (e) => {
    attrs.order = parseInt(e.target.value) || 100;
    onChange(attrs);
  });
  orderRow.appendChild(orderInput);

  const orderHint = mainDoc.createElement('span');
  orderHint.className = 'at-text-muted';
  orderHint.style.marginLeft = '8px';
  orderHint.textContent = '数字小的在前';
  orderRow.appendChild(orderHint);

  content.appendChild(orderRow);

  // 高级设置（始终创建，通过display控制显示）
  const advDetails = mainDoc.createElement('details');
  advDetails.className = 'at-adv-details';
  advDetails.style.marginTop = '8px';
  // 根据当前状态决定是否显示
  advDetails.style.display = (attrs.constant ?? true) ? 'none' : 'block';

  const advSummary = mainDoc.createElement('summary');
  advSummary.style.cssText = 'cursor: pointer; color: var(--text-muted); font-size: 12px;';
  advSummary.textContent = '高级设置';
  advDetails.appendChild(advSummary);

  const advContent = mainDoc.createElement('div');
  advContent.style.cssText = 'padding-top: 8px;';

  // 递归控制
  advContent.appendChild(buildCheckbox({
    label: '禁止被递归激活',
    checked: attrs.preventRecursionIn || false,
    onChange: (v) => { attrs.preventRecursionIn = v; onChange(attrs); }
  }));

  advContent.appendChild(buildCheckbox({
    label: '禁止递归激活其他',
    checked: attrs.preventRecursionOut || false,
    onChange: (v) => { attrs.preventRecursionOut = v; onChange(attrs); }
  }));

  // 时效控制
  const timeRow = mainDoc.createElement('div');
  timeRow.className = 'at-flex at-gap-md';
  timeRow.style.marginTop = '8px';

  ['sticky', 'cooldown', 'delay'].forEach(field => {
    const fieldLabel = { sticky: '粘性', cooldown: '冷却', delay: '延迟' }[field];
    const fieldUnit = field === 'delay' ? '条' : '轮';

    const fieldContainer = mainDoc.createElement('div');
    const fieldLabelEl = mainDoc.createElement('span');
    fieldLabelEl.style.cssText = 'font-size: 12px; color: var(--text-secondary);';
    fieldLabelEl.textContent = fieldLabel + ':';
    fieldContainer.appendChild(fieldLabelEl);

    const input = mainDoc.createElement('input');
    input.type = 'number';
    input.className = 'at-form-input';
    input.style.cssText = 'width: 50px; margin-left: 4px;';
    input.placeholder = '-';
    input.value = attrs[field] ?? '';
    input.addEventListener('input', (e) => {
      const val = e.target.value ? parseInt(e.target.value) : null;
      attrs[field] = val;
      onChange(attrs);
    });
    fieldContainer.appendChild(input);

    const unitEl = mainDoc.createElement('span');
    unitEl.style.cssText = 'font-size: 12px; color: var(--text-muted);';
    unitEl.textContent = fieldUnit;
    fieldContainer.appendChild(unitEl);

    timeRow.appendChild(fieldContainer);
  });

  advContent.appendChild(timeRow);
  advDetails.appendChild(advContent);
  content.appendChild(advDetails);

  details.appendChild(content);
  container.appendChild(details);
  return container;
}

