// 字符串列表编辑器
// ─────────────────────────────────────────────────────────────────

/**
 * 构建字符串列表编辑器（用于entries、triggerKeys等）
 */
function buildStringListEditor(options) {
  const { label, values, placeholder, onChange } = options;

  const container = mainDoc.createElement('div');
  container.className = 'at-form-group';

  if (label) {
    const labelEl = mainDoc.createElement('label');
    labelEl.className = 'at-form-label';
    labelEl.textContent = label;
    container.appendChild(labelEl);
  }

  // 当前值标签显示
  const tagsContainer = mainDoc.createElement('div');
  tagsContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px;';

  for (const val of values) {
    const tag = mainDoc.createElement('span');
    tag.className = 'at-section-badge';
    tag.style.cssText = 'display: inline-flex; align-items: center; gap: 4px;';
    tag.innerHTML = `${val} <span style="cursor: pointer; opacity: 0.7;">×</span>`;

    tag.querySelector('span').addEventListener('click', () => {
      const newValues = values.filter(v => v !== val);
      onChange(newValues);
      renderPage('creator');
    });

    tagsContainer.appendChild(tag);
  }

  if (values.length === 0) {
    tagsContainer.innerHTML = '<span class="at-text-muted">无</span>';
  }

  container.appendChild(tagsContainer);

  // 添加输入
  const addContainer = mainDoc.createElement('div');
  addContainer.className = 'at-flex at-gap-sm';

  const input = mainDoc.createElement('input');
  input.type = 'text';
  input.className = 'at-form-input';
  input.style.flex = '1';
  input.placeholder = placeholder || '输入值';

  const addBtn = buildButton({
    text: '添加',
    small: true,
    onClick: () => {
      const val = input.value.trim();
      if (!val) return;
      if (values.includes(val)) {
        toastr.warning('该值已存在');
        return;
      }
      onChange([...values, val]);
      input.value = '';
      renderPage('creator');
    }
  });

  // 回车添加
  input.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addBtn.click();
    }
  });

  addContainer.appendChild(input);
  addContainer.appendChild(addBtn);
  container.appendChild(addContainer);

  return container;
}

// ─────────────────────────────────────────────────────────────────
// 创作者页 - 变量更新任务区块
// ─────────────────────────────────────────────────────────────────

/**
 * 创作者页 - 变量更新任务区块
 */
function buildCreatorVarUpdateSection(preset) {
  const content = mainDoc.createElement('div');

  if (!preset) {
    content.innerHTML = '<div class="at-text-muted">请先选择方案</div>';
    return buildSection({
      id: 'creator_var_update',
      title: '变量更新任务',
      content: content,
      defaultCollapsed: true
    });
  }

  // 确保 varUpdateTasks 存在
  if (!preset.varUpdateTasks) {
    preset.varUpdateTasks = [];
  }

  const tasks = preset.varUpdateTasks;
  const enabledCount = tasks.filter(t => t.enabled).length;

  // MVU 状态提示
  const mvuAvailable = isMvuAvailable();
  const mvuHint = mainDoc.createElement('div');
  mvuHint.style.cssText = `
    padding: 8px 12px;
    margin-bottom: 12px;
    border-radius: 4px;
    font-size: 13px;
    background: ${mvuAvailable ? 'rgba(92, 163, 146, 0.1)' : 'rgba(184, 106, 90, 0.1)'};
    border: 1px solid ${mvuAvailable ? 'var(--success)' : 'var(--warning)'};
    color: ${mvuAvailable ? 'var(--success)' : 'var(--warning)'};
  `;
  if (mvuAvailable) {
    mvuHint.innerHTML = '💡 MVU 状态：✓ 可用';
  } else {
    mvuHint.innerHTML = '⚠️ 未检测到 MVU，变量更新任务将无法执行。<br><span style="font-size: 12px; opacity: 0.8;">请确保已加载 MVU 脚本且角色卡包含 [InitVar]。</span>';
  }
  content.appendChild(mvuHint);

  // 任务列表
  if (tasks.length === 0) {
    const emptyHint = mainDoc.createElement('div');
    emptyHint.className = 'at-text-muted';
    emptyHint.style.cssText = 'text-align: center; padding: 20px;';
    emptyHint.textContent = '暂无变量更新任务，点击下方按钮创建';
    content.appendChild(emptyHint);
  } else {
    const list = mainDoc.createElement('div');
    list.className = 'at-var-update-list';

    tasks.forEach((task, index) => {
      list.appendChild(buildVarUpdateTaskItem(task, index, tasks.length, preset));
    });

    content.appendChild(list);
  }

  // 新建任务按钮
  const btnContainer = mainDoc.createElement('div');
  btnContainer.style.marginTop = '12px';
  btnContainer.appendChild(buildButton({
    text: '+ 新建变量更新任务',
    onClick: () => {
      const newTask = {
        ...JSON.parse(JSON.stringify(DEFAULT_VAR_UPDATE_TASK)),
        id: generateUUID()
      };
      preset.varUpdateTasks.push(newTask);
      expandedVarUpdateTaskId = newTask.id;
      markDirty();
      renderPage('creator');
      toastr.info('已创建新任务');
    }
  }));
  content.appendChild(btnContainer);

  return buildSection({
    id: 'creator_var_update',
    title: '变量更新任务',
    badge: tasks.length > 0 ? `${enabledCount}/${tasks.length}` : null,
    content: content,
    defaultCollapsed: true
  });
}

/**
 * 构建单个变量更新任务项
 */
function buildVarUpdateTaskItem(task, index, total, preset) {
  const isExpanded = expandedVarUpdateTaskId === task.id;

  const container = mainDoc.createElement('div');
  container.className = 'at-var-update-item';
  container.style.cssText = `
    margin-bottom: 8px;
    background: var(--bg-tertiary);
    border-radius: 6px;
    border-left: 3px solid ${task.enabled ? 'var(--accent-secondary)' : 'var(--border-color)'};
    overflow: hidden;
  `;

  // 任务头部
  const header = mainDoc.createElement('div');
  header.style.cssText = `
    display: flex;
    align-items: center;
    padding: 10px 12px;
    cursor: pointer;
    gap: 8px;
  `;

  // 启用复选框
  const enableCheck = mainDoc.createElement('input');
  enableCheck.type = 'checkbox';
  enableCheck.checked = task.enabled;
  enableCheck.style.cssText = 'width: 16px; height: 16px; accent-color: var(--accent-primary);';
  enableCheck.addEventListener('click', (e) => e.stopPropagation());
  enableCheck.addEventListener('change', (e) => {
    task.enabled = e.target.checked;
    markDirty();
    renderPage('creator');
  });
  header.appendChild(enableCheck);

  // 序号
  const indexSpan = mainDoc.createElement('span');
  indexSpan.style.cssText = 'color: var(--text-muted); min-width: 24px;';
  indexSpan.textContent = `${index + 1}.`;
  header.appendChild(indexSpan);

  // 任务名称
  const nameSpan = mainDoc.createElement('span');
  nameSpan.style.cssText = 'flex: 1; font-weight: 500;';
  nameSpan.textContent = task.name;
  nameSpan.dataset.varUpdateNameDisplay = task.id;
  header.appendChild(nameSpan);

  // 间隔标签
  const intervalBadge = mainDoc.createElement('span');
  intervalBadge.className = 'at-section-badge';
  intervalBadge.textContent = `@${task.trigger?.interval || 5}`;
  header.appendChild(intervalBadge);

  // 展开指示
  const toggleIcon = mainDoc.createElement('span');
  toggleIcon.style.cssText = `
    color: var(--text-muted);
    transition: transform 0.2s;
    transform: rotate(${isExpanded ? '0' : '-90'}deg);
  `;
  toggleIcon.textContent = '▼';
  header.appendChild(toggleIcon);

  header.addEventListener('click', () => {
    expandedVarUpdateTaskId = isExpanded ? null : task.id;
    renderPage('creator');
  });

  container.appendChild(header);

  // 展开的编辑表单
  if (isExpanded) {
    container.appendChild(buildVarUpdateTaskForm(task, index, preset));
  }

  return container;
}

/**
 * 构建变量更新任务编辑表单
 */
function buildVarUpdateTaskForm(task, index, preset) {
  const form = mainDoc.createElement('div');
  form.style.cssText = `
    padding: 12px;
    border-top: 1px solid var(--border-light);
    background: var(--bg-secondary);
  `;

  // 统一初始化 dataSource 结构
  if (!task.dataSource) {
    task.dataSource = { useReferences: [], useTaskOutputs: [] };
  }
  if (!task.dataSource.useReferences) {
    task.dataSource.useReferences = [];
  }
  if (!task.dataSource.useTaskOutputs) {
    task.dataSource.useTaskOutputs = [];
  }

  // ═══════════════════════════════════════
  // 基础信息
  // ═══════════════════════════════════════

  const basicSection = mainDoc.createElement('div');
  basicSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">基础信息</div>';

  // 任务名称
  basicSection.appendChild(buildInput({
    label: '任务名称',
    value: task.name,
    onChange: (v) => {
      task.name = v;
      markDirty();
      const nameDisplay = mainDoc.querySelector(`[data-var-update-name-display="${task.id}"]`);
      if (nameDisplay) nameDisplay.textContent = v;
    }
  }));

  // 触发间隔
  const intervalGroup = mainDoc.createElement('div');
  intervalGroup.className = 'at-form-group';

  const intervalLabel = mainDoc.createElement('label');
  intervalLabel.className = 'at-form-label';
  intervalLabel.textContent = '触发间隔';
  intervalGroup.appendChild(intervalLabel);

  const intervalRow = mainDoc.createElement('div');
  intervalRow.className = 'at-flex at-gap-sm at-flex-center';

  const intervalSpan1 = mainDoc.createElement('span');
  intervalSpan1.textContent = '每';
  intervalRow.appendChild(intervalSpan1);

  const intervalInput = mainDoc.createElement('input');
  intervalInput.type = 'number';
  intervalInput.className = 'at-form-input';
  intervalInput.style.width = '80px';
  intervalInput.min = '1';
  intervalInput.value = task.trigger?.interval || 5;
  intervalInput.addEventListener('input', (e) => {
    if (!task.trigger) task.trigger = { interval: 5 };
    task.trigger.interval = parseInt(e.target.value) || 5;
    markDirty();
  });
  intervalRow.appendChild(intervalInput);

  const intervalSpan2 = mainDoc.createElement('span');
  intervalSpan2.textContent = '次 AI 回复触发';
  intervalRow.appendChild(intervalSpan2);

  intervalGroup.appendChild(intervalRow);
  basicSection.appendChild(intervalGroup);

  // 任务简述
  basicSection.appendChild(buildTextarea({
    label: '任务简述（可选）',
    value: task.taskBrief || '',
    placeholder: '给AI的上下文说明，如：监控角色HP/MP变化',
    rows: 2,
    onChange: (v) => { task.taskBrief = v; markDirty(); }
  }));

  form.appendChild(basicSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 提示词配置
  // ═══════════════════════════════════════
  const promptSection = mainDoc.createElement('div');
  promptSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">提示词</div>';

  // 确保 promptConfig 存在
  if (!task.promptConfig) {
    task.promptConfig = { mode: 'default', customContent: '' };
  }

  promptSection.appendChild(buildPromptConfigEditor(
    task.promptConfig,
    () => markDirty(),
    getDefaultVarUpdatePrompt
  ));

  form.appendChild(promptSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 数据源
  // ═══════════════════════════════════════
  const dataSection = mainDoc.createElement('div');
  dataSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">数据源</div>';

  // 聊天记录范围
  const rangeGroup = mainDoc.createElement('div');
  rangeGroup.className = 'at-form-group';

  const rangeLabel = mainDoc.createElement('label');
  rangeLabel.className = 'at-form-label';
  rangeLabel.textContent = '聊天记录范围';
  rangeGroup.appendChild(rangeLabel);

  const rangeRow = mainDoc.createElement('div');
  rangeRow.className = 'at-flex at-gap-sm at-flex-center';

  const rangeSpan1 = mainDoc.createElement('span');
  rangeSpan1.textContent = '最近';
  rangeRow.appendChild(rangeSpan1);

  const rangeInput = mainDoc.createElement('input');
  rangeInput.type = 'number';
  rangeInput.className = 'at-form-input';
  rangeInput.style.width = '80px';
  rangeInput.min = '1';
  rangeInput.value = task.chatHistoryRange || 10;
  rangeInput.addEventListener('input', (e) => {
    task.chatHistoryRange = parseInt(e.target.value) || 10;
    markDirty();
  });
  rangeRow.appendChild(rangeInput);

  const rangeSpan2 = mainDoc.createElement('span');
  rangeSpan2.textContent = '条消息';
  rangeRow.appendChild(rangeSpan2);

  rangeGroup.appendChild(rangeRow);
  dataSection.appendChild(rangeGroup);

  // 参考条目（从参考池选择）
  const refPool = preset?.referencePool || [];

  if (refPool.length > 0) {
    const refLabel = mainDoc.createElement('label');
    refLabel.className = 'at-form-label';
    refLabel.textContent = '参考条目';
    dataSection.appendChild(refLabel);

    const refContainer = mainDoc.createElement('div');
    refContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px;';

    for (const ref of refPool) {
      const refCheck = buildCheckbox({
        label: ref.label || ref.varName,
        checked: (task.dataSource?.useReferences || []).includes(ref.varName),
        onChange: (checked) => {
          if (!task.dataSource) task.dataSource = { useReferences: [], useTaskOutputs: [] };
          if (!task.dataSource.useReferences) task.dataSource.useReferences = [];

          if (checked) {
            if (!task.dataSource.useReferences.includes(ref.varName)) {
              task.dataSource.useReferences.push(ref.varName);
            }
          } else {
            task.dataSource.useReferences =
              task.dataSource.useReferences.filter(v => v !== ref.varName);
          }
          markDirty();
        }
      });
      refContainer.appendChild(refCheck);
    }
    dataSection.appendChild(refContainer);
  } else {
    const noRefHint = mainDoc.createElement('div');
    noRefHint.className = 'at-text-muted';
    noRefHint.style.cssText = 'font-size: 12px; margin-bottom: 8px;';
    noRefHint.textContent = '参考条目：无可用条目（请先在「参考条目池」中添加）';
    dataSection.appendChild(noRefHint);
  }

    // ═══════ 新增：引用任务输出选择 ═══════

    const taskOutputChoices = [];

    // 添加其他任务的输出
    for (const otherTask of preset.tasks || []) {
      if (!otherTask.output?.entryKey) continue;
      taskOutputChoices.push({
        id: otherTask.id,
        label: otherTask.name,
        hint: otherTask.output.entryKey
      });
    }

    // 添加摘要输出（如果摘要功能已启用）
    const summaryEnabled = preset.summaryTask?.update?.enabled;
    if (summaryEnabled) {
      taskOutputChoices.push({
        id: 'summary:events',
        label: '剧情摘要 - EVENTS',
        hint: 'AUTO_剧情摘要_EVENTS'
      });
      taskOutputChoices.push({
        id: 'summary:relations',
        label: '剧情摘要 - RELATIONS',
        hint: 'AUTO_剧情摘要_RELATIONS'
      });
      taskOutputChoices.push({
        id: 'summary:active',
        label: '剧情摘要 - ACTIVE',
        hint: 'AUTO_剧情摘要_ACTIVE'
      });
    }

    if (taskOutputChoices.length > 0) {
      const taskOutputLabel = mainDoc.createElement('label');
      taskOutputLabel.className = 'at-form-label';
      taskOutputLabel.textContent = '引用任务输出（聊天世界书）';
      dataSection.appendChild(taskOutputLabel);

      const taskOutputContainer = mainDoc.createElement('div');
      taskOutputContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px;';

      if (!task.dataSource.useTaskOutputs) {
        task.dataSource.useTaskOutputs = [];
      }

      for (const choice of taskOutputChoices) {
        const checkWrapper = mainDoc.createElement('label');
        checkWrapper.className = 'at-form-checkbox';
        checkWrapper.title = `关键词: ${choice.hint}`;
        checkWrapper.style.cssText = 'flex: 0 0 auto; max-width: 100%;';

        const checkbox = mainDoc.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.dataSource.useTaskOutputs.includes(choice.id);
        checkbox.addEventListener('change', (e) => {
          if (e.target.checked) {
            if (!task.dataSource.useTaskOutputs.includes(choice.id)) {
              task.dataSource.useTaskOutputs.push(choice.id);
            }
          } else {
            task.dataSource.useTaskOutputs =
              task.dataSource.useTaskOutputs.filter(id => id !== choice.id);
          }
          markDirty();
        });

        const labelText = mainDoc.createElement('span');
        labelText.textContent = choice.label;

        checkWrapper.appendChild(checkbox);
        checkWrapper.appendChild(labelText);
        taskOutputContainer.appendChild(checkWrapper);
      }

      dataSection.appendChild(taskOutputContainer);
    } else {
      const noOutputHint = mainDoc.createElement('div');
      noOutputHint.className = 'at-text-muted';
      noOutputHint.style.cssText = 'font-size: 12px; margin-bottom: 8px;';
      noOutputHint.textContent = '引用任务输出：无可用（需要其他任务配置输出条目，或启用摘要功能）';
      dataSection.appendChild(noOutputHint);
    }

  form.appendChild(dataSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 执行选项（新增）
  // ═══════════════════════════════════════
  const execSection = mainDoc.createElement('div');
  execSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">执行选项</div>';

  // 重新生成时触发
  const regenCheck = buildCheckbox({
    label: '重新生成(重roll)时触发',
    checked: task.triggerOnRegenerate !== false,  // 默认开启
    onChange: (v) => {
      task.triggerOnRegenerate = v;
      markDirty();
    }
  });
  regenCheck.title = '当用户重新生成同一楼层的AI回复时，是否触发此任务更新变量';
  regenCheck.style.marginBottom = '8px';
  execSection.appendChild(regenCheck);

  // 最大重试次数
  const retryGroup = mainDoc.createElement('div');
  retryGroup.className = 'at-form-group';

  const retryLabel = mainDoc.createElement('label');
  retryLabel.className = 'at-form-label';
  retryLabel.textContent = '最大重试次数';
  retryGroup.appendChild(retryLabel);

  const retryRow = mainDoc.createElement('div');
  retryRow.className = 'at-flex at-gap-sm at-flex-center';

  const retryInput = mainDoc.createElement('input');
  retryInput.type = 'number';
  retryInput.className = 'at-form-input';
  retryInput.style.width = '80px';
  retryInput.min = '1';
  retryInput.max = '5';
  retryInput.value = task.maxRetries ?? 3;
  retryInput.title = '当AI输出格式无效时，最多重试几次';
  retryInput.addEventListener('input', (e) => {
    const val = parseInt(e.target.value);
    task.maxRetries = Math.max(1, Math.min(5, val || 3));
    markDirty();
  });
  retryRow.appendChild(retryInput);

  const retryHint = mainDoc.createElement('span');
  retryHint.className = 'at-text-muted';
  retryHint.style.marginLeft = '8px';
  retryHint.textContent = '次（AI输出无效时重试）';
  retryRow.appendChild(retryHint);

  retryGroup.appendChild(retryRow);
  execSection.appendChild(retryGroup);

  form.appendChild(execSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // API预设
  // ═══════════════════════════════════════
  const apiSection = mainDoc.createElement('div');
  apiSection.innerHTML = '<div style="font-weight: 500; margin-bottom: 8px; color: var(--text-secondary);">API预设</div>';

  const apiChoices = [
    { value: '', label: '使用默认预设' },
    ...(apiPresetsDraft?.presets || []).map(p => ({
      value: p.id,
      label: p.name + (p.id === apiPresetsDraft?.defaultPresetId ? ' (默认)' : '')
    }))
  ];

  apiSection.appendChild(buildSelect({
    label: 'API预设',
    value: task.apiPresetId || '',
    choices: apiChoices,
    onChange: (v) => {
      task.apiPresetId = v || null;
      markDirty();
    }
  }));

  form.appendChild(apiSection);
  form.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 删除任务按钮
  // ═══════════════════════════════════════
  const deleteSection = mainDoc.createElement('div');
  deleteSection.style.textAlign = 'right';

  deleteSection.appendChild(buildButton({
    text: '删除任务',
    onClick: async () => {
      const confirmed = await SillyTavern.callGenericPopup(
        `确定删除变量更新任务「${task.name}」吗？`,
        SillyTavern.POPUP_TYPE.CONFIRM
      );
      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) return;

      preset.varUpdateTasks = preset.varUpdateTasks.filter(t => t.id !== task.id);
      expandedVarUpdateTaskId = null;
      markDirty();
      renderPage('creator');
      toastr.info('任务已删除');
    }
  }));

  form.appendChild(deleteSection);

  return form;
}

/**
 * 构建提示词配置编辑器（三模式切换）
 * @param {Object} promptConfig - 提示词配置对象 {mode, customContent, worldbookKey}
 * @param {Function} onChange - 变更回调
 * @param {Function} getDefaultPromptFn - 获取默认提示词的函数
 * @param {Object} options - 可选配置 {rows: 文本框行数}
 */
function buildPromptConfigEditor(promptConfig, onChange, getDefaultPromptFn, options = {}) {
  const { rows = 6 } = options;

  // 确保有默认提示词获取函数
  const getDefaultPrompt = getDefaultPromptFn || (() => '[默认提示词未加载]');

  const container = mainDoc.createElement('div');

  // 模式选择行
  const modeRow = mainDoc.createElement('div');
  modeRow.className = 'at-flex at-gap-sm at-flex-center';
  modeRow.style.marginBottom = '8px';

  const modeLabel = mainDoc.createElement('span');
  modeLabel.style.cssText = 'font-size: 13px; color: var(--text-secondary);';
  modeLabel.textContent = '来源：';
  modeRow.appendChild(modeLabel);

  const modeSelect = mainDoc.createElement('select');
  modeSelect.innerHTML = `
    <option value="default" ${promptConfig.mode === 'default' ? 'selected' : ''}>使用默认</option>
    <option value="custom" ${promptConfig.mode === 'custom' ? 'selected' : ''}>自定义内容</option>
  `;

  modeRow.appendChild(modeSelect);

  // 恢复默认按钮（仅custom模式显示）
  const resetBtn = buildButton({
    text: '恢复默认',
    small: true,
    onClick: async () => {
      const confirmed = await SillyTavern.callGenericPopup(
        '确定恢复为默认提示词吗？当前内容将丢失。',
        SillyTavern.POPUP_TYPE.CONFIRM
      );
      if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) return;

      promptConfig.customContent = getDefaultPrompt();
      onChange();
      renderContent();
    }
  });
  resetBtn.style.marginLeft = '8px';
  resetBtn.style.display = promptConfig.mode === 'custom' ? 'inline-block' : 'none';
  modeRow.appendChild(resetBtn);

  container.appendChild(modeRow);

  // 内容区域
  const contentArea = mainDoc.createElement('div');

  function renderContent() {
    contentArea.innerHTML = '';

    if (promptConfig.mode === 'default') {
      // 只读显示默认提示词
      const textarea = mainDoc.createElement('textarea');
      textarea.className = 'at-form-textarea';
      textarea.rows = rows;
      textarea.value = getDefaultPrompt();
      textarea.disabled = true;
      textarea.style.cssText = 'background: var(--bg-tertiary); opacity: 0.7; font-size: 12px;';
      contentArea.appendChild(textarea);

    } else if (promptConfig.mode === 'custom') {
      // 可编辑文本框
      const textarea = mainDoc.createElement('textarea');
      textarea.className = 'at-form-textarea';
      textarea.rows = rows + 2;
      textarea.value = promptConfig.customContent || getDefaultPrompt();
      textarea.style.fontSize = '12px';
      textarea.placeholder = '输入自定义提示词...';
      textarea.addEventListener('input', (e) => {
        promptConfig.customContent = e.target.value;
        onChange();
      });
      contentArea.appendChild(textarea);

      // 如果customContent为空，初始化为默认值
      if (!promptConfig.customContent) {
        promptConfig.customContent = getDefaultPrompt();
        onChange();
      }
    }
  }

  modeSelect.addEventListener('change', (e) => {
    promptConfig.mode = e.target.value;
    resetBtn.style.display = promptConfig.mode === 'custom' ? 'inline-block' : 'none';
    onChange();
    renderContent();
  });

  renderContent();
  container.appendChild(contentArea);

  return container;
}

/**
 * 创作者页 - 摘要设置区块
 */
function buildCreatorSummarySection(preset) {
  const content = mainDoc.createElement('div');

  if (!preset) {
    content.innerHTML = '<div class="at-text-muted">请先选择方案</div>';
    return buildSection({
      id: 'creator_summary',
      title: '摘要设置',
      content: content,
      defaultCollapsed: true
    });
  }

  // 确保summaryTask结构存在
  if (!preset.summaryTask) {
    preset.summaryTask = {
      update: {
        enabled: false,
        interval: 20,
        promptConfig: { mode: 'default', customContent: '', worldbookKey: '' },
        apiPresetId: null,
        autoHideMessages: true
      },
      compress: {
        promptConfig: { mode: 'default', customContent: '', worldbookKey: '' },
        apiPresetId: null
      },
      outputAttributes: {
        events: null,
        relations: null,
        active: null
      }
    };
  }

  const summaryTask = preset.summaryTask;

  // 确保子结构存在
  if (!summaryTask.update) {
    summaryTask.update = {
      enabled: false,
      interval: 20,
      promptConfig: { mode: 'default', customContent: '', worldbookKey: '' },
      apiPresetId: null,
      autoHideMessages: true
    };
  }
  if (!summaryTask.compress) {
    summaryTask.compress = {
      promptConfig: { mode: 'default', customContent: '', worldbookKey: '' },
      apiPresetId: null
    };
  }
  if (!summaryTask.outputAttributes) {
    summaryTask.outputAttributes = { events: null, relations: null, active: null };
  }

  // 确保promptConfig结构正确
  const ensurePromptConfig = (config) => {
    if (!config || typeof config !== 'object' || !config.mode) {
      return { mode: 'default', customContent: '' };
    }
    return { mode: config.mode, customContent: config.customContent || '' };
  };

  summaryTask.update.promptConfig = ensurePromptConfig(summaryTask.update.promptConfig);
  summaryTask.compress.promptConfig = ensurePromptConfig(summaryTask.compress.promptConfig);

  // ═══════════════════════════════════════
  // 小总结（增量更新）
  // ═══════════════════════════════════════
  const updateSection = mainDoc.createElement('div');
  updateSection.style.marginBottom = '16px';

  const updateHeader = mainDoc.createElement('div');
  updateHeader.style.cssText = 'font-weight: 500; margin-bottom: 10px; color: var(--text-primary);';
  updateHeader.textContent = '小总结（增量更新）';
  updateSection.appendChild(updateHeader);

  // 启用开关
  updateSection.appendChild(buildCheckbox({
    label: '启用小总结',
    checked: summaryTask.update.enabled || false,
    onChange: (v) => {
      summaryTask.update.enabled = v;
      markDirty();
      // 刷新以更新徽章和相关UI
      renderPage('creator');
    }
  }));

  // 触发间隔
  const intervalGroup = mainDoc.createElement('div');
  intervalGroup.className = 'at-form-group';
  intervalGroup.style.marginTop = '10px';

  const intervalLabel = mainDoc.createElement('label');
  intervalLabel.className = 'at-form-label';
  intervalLabel.textContent = '触发间隔';
  intervalGroup.appendChild(intervalLabel);

  const intervalRow = mainDoc.createElement('div');
  intervalRow.className = 'at-flex at-gap-sm at-flex-center';

  const intervalInput = mainDoc.createElement('input');
  intervalInput.type = 'number';
  intervalInput.className = 'at-form-input';
  intervalInput.style.width = '80px';
  intervalInput.min = '1';
  intervalInput.value = summaryTask.update.interval || 20;
  intervalInput.addEventListener('input', (e) => {
    summaryTask.update.interval = parseInt(e.target.value) || 20;
    markDirty();
  });
  intervalRow.appendChild(intervalInput);

  const intervalUnit = mainDoc.createElement('span');
  intervalUnit.style.color = 'var(--text-secondary)';
  intervalUnit.textContent = '轮（每隔多少次AI回复触发）';
  intervalRow.appendChild(intervalUnit);

  intervalGroup.appendChild(intervalRow);
  updateSection.appendChild(intervalGroup);

  // 提示词配置
  const updatePromptSection = mainDoc.createElement('div');
  updatePromptSection.className = 'at-form-group';
  updatePromptSection.style.marginTop = '12px';

  const updatePromptLabel = mainDoc.createElement('label');
  updatePromptLabel.className = 'at-form-label';
  updatePromptLabel.textContent = '提示词';
  updatePromptSection.appendChild(updatePromptLabel);

  updatePromptSection.appendChild(buildPromptConfigEditor(
    summaryTask.update.promptConfig,
    () => markDirty(),
    getDefaultSummaryUpdatePrompt,
    { rows: 8 }
  ));

  updateSection.appendChild(updatePromptSection);

  // API预设
  const updateApiChoices = [
    { value: '', label: '使用默认预设' },
    ...(apiPresetsDraft?.presets || []).map(p => ({
      value: p.id,
      label: p.name + (p.id === apiPresetsDraft?.defaultPresetId ? ' (默认)' : '')
    }))
  ];

  updateSection.appendChild(buildSelect({
    label: 'API预设',
    value: summaryTask.update.apiPresetId || '',
    choices: updateApiChoices,
    onChange: (v) => {
      summaryTask.update.apiPresetId = v || null;
      markDirty();
    }
  }));

    // ═══════ 新增：数据源选择 ═══════
    const dataSourceSection = mainDoc.createElement('div');
    dataSourceSection.style.marginTop = '12px';

    const dataSourceLabel = mainDoc.createElement('label');
    dataSourceLabel.className = 'at-form-label';
    dataSourceLabel.textContent = '数据源（可选）';
    dataSourceSection.appendChild(dataSourceLabel);

    // 确保 dataSource 结构存在
    if (!summaryTask.update.dataSource) {
      summaryTask.update.dataSource = { useReferences: [], useTaskOutputs: [] };
    }

    // 参考条目选择
    const refPool = preset?.referencePool || [];
    if (refPool.length > 0) {
      const refSubLabel = mainDoc.createElement('div');
      refSubLabel.style.cssText = 'font-size: 12px; color: var(--text-secondary); margin: 6px 0 4px 0;';
      refSubLabel.textContent = '参考条目:';
      dataSourceSection.appendChild(refSubLabel);

      const refContainer = mainDoc.createElement('div');
      refContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px;';

      for (const ref of refPool) {
        const refCheck = buildCheckbox({
          label: ref.label || ref.varName,
          checked: (summaryTask.update.dataSource.useReferences || []).includes(ref.varName),
          onChange: (checked) => {
            if (!summaryTask.update.dataSource.useReferences) {
              summaryTask.update.dataSource.useReferences = [];
            }
            if (checked) {
              if (!summaryTask.update.dataSource.useReferences.includes(ref.varName)) {
                summaryTask.update.dataSource.useReferences.push(ref.varName);
              }
            } else {
              summaryTask.update.dataSource.useReferences =
                summaryTask.update.dataSource.useReferences.filter(v => v !== ref.varName);
            }
            markDirty();
          }
        });
        refContainer.appendChild(refCheck);
      }
      dataSourceSection.appendChild(refContainer);
    }

    // 引用任务输出选择
    const taskOutputChoices = [];
    for (const task of preset.tasks || []) {
      if (!task.output?.entryKey) continue;
      taskOutputChoices.push({
        id: task.id,
        label: task.name,
        hint: task.output.entryKey
      });
    }

    if (taskOutputChoices.length > 0) {
      const outputSubLabel = mainDoc.createElement('div');
      outputSubLabel.style.cssText = 'font-size: 12px; color: var(--text-secondary); margin: 6px 0 4px 0;';
      outputSubLabel.textContent = '引用任务输出:';
      dataSourceSection.appendChild(outputSubLabel);

      const outputContainer = mainDoc.createElement('div');
      outputContainer.style.cssText = 'display: flex; flex-wrap: wrap; gap: 8px;';

      if (!summaryTask.update.dataSource.useTaskOutputs) {
        summaryTask.update.dataSource.useTaskOutputs = [];
      }

      for (const choice of taskOutputChoices) {
        const checkWrapper = mainDoc.createElement('label');
        checkWrapper.className = 'at-form-checkbox';
        checkWrapper.title = `关键词: ${choice.hint}`;

        const checkbox = mainDoc.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = summaryTask.update.dataSource.useTaskOutputs.includes(choice.id);
        checkbox.addEventListener('change', (e) => {
          if (e.target.checked) {
            if (!summaryTask.update.dataSource.useTaskOutputs.includes(choice.id)) {
              summaryTask.update.dataSource.useTaskOutputs.push(choice.id);
            }
          } else {
            summaryTask.update.dataSource.useTaskOutputs =
              summaryTask.update.dataSource.useTaskOutputs.filter(id => id !== choice.id);
          }
          markDirty();
        });

        const labelText = mainDoc.createElement('span');
        labelText.textContent = choice.label;

        checkWrapper.appendChild(checkbox);
        checkWrapper.appendChild(labelText);
        outputContainer.appendChild(checkWrapper);
      }
      dataSourceSection.appendChild(outputContainer);
    }

    // 如果参考池和任务输出都为空
    if (refPool.length === 0 && taskOutputChoices.length === 0) {
      const emptyHint = mainDoc.createElement('div');
      emptyHint.className = 'at-text-muted';
      emptyHint.style.cssText = 'font-size: 12px;';
      emptyHint.textContent = '无可用数据源（请先在参考条目池添加条目，或创建带输出的任务）';
      dataSourceSection.appendChild(emptyHint);
    }

    updateSection.appendChild(dataSourceSection);

  // 自动隐藏开关
  const autoHideCheck = buildCheckbox({
    label: '自动隐藏已摘要楼层',
    checked: summaryTask.update.autoHideMessages ?? true,
    onChange: (v) => {
      summaryTask.update.autoHideMessages = v;
      markDirty();
    }
  });
  autoHideCheck.title = '开启后，每次小总结执行完毕会自动隐藏已摘要的历史消息';
  autoHideCheck.style.marginTop = '8px';
  updateSection.appendChild(autoHideCheck);

  content.appendChild(updateSection);
  content.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 大总结（压缩）
  // ═══════════════════════════════════════
  const compressSection = mainDoc.createElement('div');
  compressSection.style.marginBottom = '16px';

  const compressHeader = mainDoc.createElement('div');
  compressHeader.style.cssText = 'font-weight: 500; margin-bottom: 10px; color: var(--text-primary);';
  compressHeader.textContent = '大总结（压缩）';
  compressSection.appendChild(compressHeader);

  const compressHint = mainDoc.createElement('div');
  compressHint.className = 'at-text-muted';
  compressHint.style.cssText = 'font-size: 12px; margin-bottom: 10px;';
  compressHint.textContent = '手动触发，用于压缩过长的EVENTS条目';
  compressSection.appendChild(compressHint);

  // 提示词配置
  const compressPromptSection = mainDoc.createElement('div');
  compressPromptSection.className = 'at-form-group';

  const compressPromptLabel = mainDoc.createElement('label');
  compressPromptLabel.className = 'at-form-label';
  compressPromptLabel.textContent = '提示词';
  compressPromptSection.appendChild(compressPromptLabel);

  compressPromptSection.appendChild(buildPromptConfigEditor(
    summaryTask.compress.promptConfig,
    () => markDirty(),
    getDefaultSummaryCompressPrompt,
    { rows: 8 }
  ));

  compressSection.appendChild(compressPromptSection);

  // API预设
  const compressApiChoices = [
    { value: '', label: '使用默认预设' },
    ...(apiPresetsDraft?.presets || []).map(p => ({
      value: p.id,
      label: p.name + (p.id === apiPresetsDraft?.defaultPresetId ? ' (默认)' : '')
    }))
  ];

  compressSection.appendChild(buildSelect({
    label: 'API预设',
    value: summaryTask.compress.apiPresetId || '',
    choices: compressApiChoices,
    onChange: (v) => {
      summaryTask.compress.apiPresetId = v || null;
      markDirty();
    }
  }));

  content.appendChild(compressSection);
  content.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 摘要条目属性
  // ═══════════════════════════════════════
  const attrsSection = mainDoc.createElement('div');

  const attrsHeader = mainDoc.createElement('div');
  attrsHeader.style.cssText = 'font-weight: 500; margin-bottom: 10px; color: var(--text-primary);';
  attrsHeader.textContent = '摘要条目属性';
  attrsSection.appendChild(attrsHeader);

  const attrsHint = mainDoc.createElement('div');
  attrsHint.className = 'at-text-muted';
  attrsHint.style.cssText = 'font-size: 12px; margin-bottom: 12px;';
  attrsHint.textContent = '配置三个摘要条目写入聊天世界书时的属性（条目关键词固定不可修改）';
  attrsSection.appendChild(attrsHint);

  // 默认属性值
  const defaultAttrs = {
    enabled: true,
    constant: true,
    position: 4,
    depth: 4,
    role: 'system',
    order: 100,
    probability: 100,
    preventRecursionIn: false,
    preventRecursionOut: false,
    sticky: null,
    cooldown: null,
    delay: null
  };

  // 三个摘要条目
  const summaryEntries = [
    { key: 'events', name: 'EVENTS', desc: '事件列表 (AUTO_剧情摘要_EVENTS)' },
    { key: 'relations', name: 'RELATIONS', desc: '关系网 (AUTO_剧情摘要_RELATIONS)' },
    { key: 'active', name: 'ACTIVE', desc: '待办事项 (AUTO_剧情摘要_ACTIVE)' }
  ];

  for (const entry of summaryEntries) {
    const entryContainer = mainDoc.createElement('div');
    entryContainer.style.cssText = `
      background: var(--bg-tertiary);
      border-radius: 6px;
      padding: 10px 12px;
      margin-bottom: 8px;
      border-left: 3px solid var(--accent-secondary);
    `;

    // 条目标题行
    const titleRow = mainDoc.createElement('div');
    titleRow.className = 'at-flex at-flex-between at-flex-center';
    titleRow.style.marginBottom = '8px';

    const titleLeft = mainDoc.createElement('div');
    titleLeft.innerHTML = `<strong>${entry.name}</strong>`;
    titleRow.appendChild(titleLeft);

    // 使用默认/自定义切换
    const currentAttrs = summaryTask.outputAttributes[entry.key];
    const isUsingDefault = currentAttrs === null;

    const toggleBtn = buildButton({
      text: isUsingDefault ? '自定义属性' : '恢复默认',
      small: true,
      onClick: () => {
        if (isUsingDefault) {
          // 切换为自定义，初始化为默认值
          summaryTask.outputAttributes[entry.key] = { ...defaultAttrs };
        } else {
          // 切换为默认
          summaryTask.outputAttributes[entry.key] = null;
        }
        markDirty();
        renderPage('creator');
      }
    });
    titleRow.appendChild(toggleBtn);

    entryContainer.appendChild(titleRow);

    // 描述
    const descEl = mainDoc.createElement('div');
    descEl.className = 'at-text-muted';
    descEl.style.cssText = 'font-size: 12px; margin-bottom: 8px;';
    descEl.textContent = entry.desc;
    entryContainer.appendChild(descEl);

    if (isUsingDefault) {
      // 显示默认属性摘要
      const defaultSummary = mainDoc.createElement('div');
      defaultSummary.style.cssText = 'font-size: 12px; color: var(--text-secondary);';
      // 根据position类型显示不同内容
      if (defaultAttrs.position === 4) {
        defaultSummary.textContent = `使用默认: 指定深度${defaultAttrs.depth}, ${defaultAttrs.role}, 顺序${defaultAttrs.order}`;
      } else {
        defaultSummary.textContent = `使用默认: ${getPositionDisplayName(defaultAttrs.position)}, 顺序${defaultAttrs.order}`;
      }
      entryContainer.appendChild(defaultSummary);
    } else {
      // 显示属性编辑器
      const attrEditor = buildSummaryEntryAttributesEditor(
        currentAttrs,
        (attrs) => {
          summaryTask.outputAttributes[entry.key] = attrs;
          markDirty();
        },
        `summary_${entry.key}`
      );
      entryContainer.appendChild(attrEditor);
    }

    attrsSection.appendChild(entryContainer);
  }

  content.appendChild(attrsSection);

  // 计算徽章显示
  const enabled = summaryTask.update.enabled;

  return buildSection({
    id: 'creator_summary',
    title: '摘要设置',
    badge: enabled ? '已启用' : '未启用',
    content: content,
    defaultCollapsed: true
  });
}

/**
