  blueInput.type = 'radio';
  blueInput.name = radioName;
  blueInput.checked = attrs.constant ?? true;
  blueInput.addEventListener('change', () => {
    attrs.constant = true;
    onChange(attrs);
  });
  blueRadio.appendChild(blueInput);
  const blueText = mainDoc.createElement('span');
  blueText.style.color = 'var(--info)';
  blueText.textContent = '蓝灯';
  blueRadio.appendChild(blueText);
  typeContainer.appendChild(blueRadio);

  const greenRadio = mainDoc.createElement('label');
  greenRadio.className = 'at-form-checkbox';
  const greenInput = mainDoc.createElement('input');
  greenInput.type = 'radio';
  greenInput.name = radioName;
  greenInput.checked = !(attrs.constant ?? true);
  greenInput.addEventListener('change', () => {
    attrs.constant = false;
    onChange(attrs);
  });
  greenRadio.appendChild(greenInput);
  const greenText = mainDoc.createElement('span');
  greenText.style.color = 'var(--success)';
  greenText.textContent = '绿灯';
  greenRadio.appendChild(greenText);
