  probContainer.innerHTML = '<span style="font-size: 12px;">概率:</span>';
  const probInput = mainDoc.createElement('input');
  probInput.type = 'number';
  probInput.className = 'at-form-input';
  probInput.style.width = '55px';
  probInput.min = '0';
  probInput.max = '100';
  probInput.value = attrs.probability ?? 100;
  probInput.addEventListener('input', (e) => {
    attrs.probability = parseInt(e.target.value) || 100;
    onChange(attrs);
  });
  probContainer.appendChild(probInput);
  probContainer.innerHTML += '<span style="font-size: 12px;">%</span>';
  row1.appendChild(probContainer);

  container.appendChild(row1);

  // 第二行：位置 + 深度 + 角色 + 顺序
  const row2 = mainDoc.createElement('div');
  row2.className = 'at-flex at-gap-sm';
  row2.style.cssText = 'flex-wrap: wrap; align-items: center;';

  // 位置
  const posSelect = mainDoc.createElement('select');
  posSelect.className = 'at-form-select';
  posSelect.style.width = '110px';
  for (const opt of POSITION_OPTIONS) {
    const option = mainDoc.createElement('option');
    option.value = opt.value;
    option.textContent = opt.label;
    if (opt.value === attrs.position) option.selected = true;
    posSelect.appendChild(option);
  }
  posSelect.addEventListener('change', (e) => {
    attrs.position = parseInt(e.target.value);
    onChange(attrs);
    // 更新深度/角色显示
    depthInput.style.display = attrs.position === 4 ? 'block' : 'none';
    roleSelect.style.display = attrs.position === 4 ? 'block' : 'none';
  });
  row2.appendChild(posSelect);

  // 深度
  const depthInput = mainDoc.createElement('input');
  depthInput.type = 'number';
  depthInput.className = 'at-form-input';
  depthInput.style.width = '55px';
  depthInput.style.display = attrs.position === 4 ? 'block' : 'none';
  depthInput.placeholder = '深度';
  depthInput.value = attrs.depth ?? 4;
  depthInput.addEventListener('input', (e) => {
    attrs.depth = parseInt(e.target.value) || 4;
    onChange(attrs);
  });
  row2.appendChild(depthInput);

  // 角色
  const roleSelect = mainDoc.createElement('select');
  roleSelect.className = 'at-form-select';
  roleSelect.style.width = '80px';
  roleSelect.style.display = attrs.position === 4 ? 'block' : 'none';
  ['system', 'user', 'assistant'].forEach(role => {
    const option = mainDoc.createElement('option');
    option.value = role;
    option.textContent = role;
    if (role === attrs.role) option.selected = true;
    roleSelect.appendChild(option);
  });
  roleSelect.addEventListener('change', (e) => {
    attrs.role = e.target.value;
    onChange(attrs);
  });
  row2.appendChild(roleSelect);

  // 顺序
  const orderContainer = mainDoc.createElement('div');
  orderContainer.className = 'at-flex at-gap-sm at-flex-center';
  orderContainer.innerHTML = '<span style="font-size: 12px;">顺序:</span>';
  const orderInput = mainDoc.createElement('input');
  orderInput.type = 'number';
  orderInput.className = 'at-form-input';
  orderInput.style.width = '60px';
  orderInput.value = attrs.order ?? 100;
  orderInput.addEventListener('input', (e) => {
    attrs.order = parseInt(e.target.value) || 100;
    onChange(attrs);
  });
  orderContainer.appendChild(orderInput);
  row2.appendChild(orderContainer);

  container.appendChild(row2);

  return container;
}

// ─────────────────────────────────────────────────────────────────
// 创作者页 - 依赖检查区块
// ─────────────────────────────────────────────────────────────────

/**
 * 依赖检查结果类型
 * @typedef {Object} CheckResult
 * @property {'ok'|'warn'|'error'} status - 状态
 * @property {string} type - 检查类型（prompt/reference/api）
 * @property {string} name - 项目名称
 * @property {string} message - 显示消息
 */

/**
 * 执行依赖检查
 * @param {Object} preset - 当前方案
 * @returns {Promise<CheckResult[]>}
 */
async function performDependencyCheck(preset) {
  const results = [];

  if (!preset) return results;

  // 获取角色世界书
  const charWB = getCharWorldbookNames('current');
  let charEntries = [];

  if (charWB.primary) {
    try {
      charEntries = await getWorldbook(charWB.primary);
    } catch (err) {
      console.warn('[AutoTask] 读取角色世界书失败:', err);
    }
  }

  // 辅助函数：检查条目是否存在
  const findEntry = (key) => {
    if (!key) return null;
    return charEntries.find(e =>
      e.strategy.keys.some(k =>
        typeof k === 'string' ? k === key : k.test?.(key)
      )
    );
  };

  // ═══════════════════════════════════════
  // 1. 检查任务提示词条目
  // ═══════════════════════════════════════
  for (const task of preset.tasks || []) {
    if (!task.enabled) continue; // 仅检查启用的任务

    const promptKey = task.prompt?.entryKey;
    if (promptKey) {
      const entry = findEntry(promptKey);
      if (entry) {
        results.push({
          status: 'ok',
          type: 'prompt',
          name: promptKey,
          message: `任务「${task.name}」提示词条目存在`
        });
      } else {
        results.push({
          status: 'error',
          type: 'prompt',
          name: promptKey,
          message: `任务「${task.name}」提示词条目不存在`
        });
      }
    } else {
      // 启用的任务没有提示词条目
      results.push({
        status: 'warn',
        type: 'prompt',
        name: task.name,
        message: `任务「${task.name}」未配置提示词条目`
      });
    }
  }

  // ═══════════════════════════════════════
  // 3. 检查参考池条目
  // ═══════════════════════════════════════
  for (const ref of preset.referencePool || []) {
    const key = ref.entryKey;
    if (!key) {
      results.push({
        status: 'warn',
        type: 'reference',
        name: ref.label || ref.varName,
        message: `参考条目「${ref.label || ref.varName}」未配置关键词`
      });
      continue;
    }

    const entry = findEntry(key);
    if (!entry) {
      results.push({
        status: 'error',
        type: 'reference',
        name: key,
        message: `参考条目「${ref.label}」不存在`
      });
    } else if (ref.requireEnabled && !entry.enabled) {
      results.push({
        status: 'warn',
        type: 'reference',
        name: key,
        message: `参考条目「${ref.label}」存在但已禁用`
      });
    } else {
      results.push({
        status: 'ok',
        type: 'reference',
        name: key,
        message: `参考条目「${ref.label}」存在${ref.requireEnabled ? '且已启用' : ''}`
      });
    }
  }

  // ═══════════════════════════════════════
  // 3.5 检查任务的 useTaskOutputs 引用
  // ═══════════════════════════════════════
  for (const task of preset.tasks || []) {
    if (!task.enabled) continue;

    for (const outputId of task.dataSource?.useTaskOutputs || []) {
      if (outputId.startsWith('summary:')) {
        // 摘要输出：检查摘要是否启用
        if (!preset.summaryTask?.update?.enabled) {
          results.push({
            status: 'warn',
            type: 'reference',
            name: outputId,
            message: `任务「${task.name}」引用了摘要输出，但摘要功能未启用`
          });
        }
      } else {
        // 普通任务输出：检查任务是否存在且有输出配置
        const targetTask = (preset.tasks || []).find(t => t.id === outputId);
        const isSelf = outputId === task.id;

        if (!targetTask) {
          results.push({
            status: 'error',
            type: 'reference',
            name: outputId,
            message: `任务「${task.name}」引用的任务已被删除`
          });
        } else if (!targetTask.output?.entryKey) {
          // 自引用但未配置输出：警告
          // 引用其他任务但未配置输出：警告
          results.push({
            status: 'warn',
            type: 'reference',
            name: targetTask.name,
            message: isSelf
              ? `任务「${task.name}」自引用但未配置输出条目`
              : `任务「${task.name}」引用的任务「${targetTask.name}」未配置输出`
          });
        }
      }
    }
  }

  // ═══════════════════════════════════════
  // 4. 检查变量更新任务
  // ═══════════════════════════════════════
  for (const task of preset.varUpdateTasks || []) {
    if (!task.enabled) continue;

    // 检查参考条目引用
    for (const varName of task.dataSource?.useReferences || []) {
      const ref = (preset.referencePool || []).find(r => r.varName === varName);
      if (!ref) {
        results.push({
          status: 'warn',
          type: 'reference',
          name: varName,
          message: `变量更新「${task.name}」引用的参考条目「${varName}」不存在于参考池`
        });
      }
    }

    // 检查任务输出引用
    for (const outputId of task.dataSource?.useTaskOutputs || []) {
      if (outputId.startsWith('summary:')) {
        // 摘要输出：检查摘要是否启用
        if (!preset.summaryTask?.update?.enabled) {
          results.push({
            status: 'warn',
            type: 'reference',
            name: outputId,
            message: `变量更新「${task.name}」引用了摘要输出，但摘要功能未启用`
          });
        }
      } else {
        // 普通任务输出：检查任务是否存在且有输出配置
        const targetTask = (preset.tasks || []).find(t => t.id === outputId);
        if (!targetTask) {
          results.push({
            status: 'error',
            type: 'reference',
            name: outputId,
            message: `变量更新「${task.name}」引用的任务已被删除`
          });
        } else if (!targetTask.output?.entryKey) {
          results.push({
            status: 'warn',
            type: 'reference',
            name: targetTask.name,
            message: `变量更新「${task.name}」引用的任务「${targetTask.name}」未配置输出`
          });
        }
      }
    }
  }

  // ═══════════════════════════════════════
  // 5. 检查API预设引用
  // ═══════════════════════════════════════
  const checkedApiIds = new Set();

  // 检查任务的API预设
  for (const task of preset.tasks || []) {
    if (!task.enabled) continue;

    const apiId = task.apiPresetId;
    if (apiId && !checkedApiIds.has(apiId)) {
      checkedApiIds.add(apiId);
      const apiPreset = getApiPresetById(apiId);
      if (!apiPreset) {
        results.push({
          status: 'warn',
          type: 'api',
          name: apiId,
          message: `API预设「${apiId}」不存在，将回退到默认`
        });
      }
    }
  }

  // 检查摘要任务的API预设
  const summaryApiIds = [
    preset.summaryTask?.update?.apiPresetId,
    preset.summaryTask?.compress?.apiPresetId
  ].filter(id => id && !checkedApiIds.has(id));

  for (const apiId of summaryApiIds) {
    checkedApiIds.add(apiId);
    const apiPreset = getApiPresetById(apiId);
    if (!apiPreset) {
      results.push({
        status: 'warn',
        type: 'api',
        name: apiId,
        message: `摘要API预设「${apiId}」不存在，将回退到默认`
      });
    }
  }

  // 检查变量更新任务的API预设
  for (const varTask of preset.varUpdateTasks || []) {
    if (!varTask.enabled) continue;

    const apiId = varTask.apiPresetId;
    if (apiId && !checkedApiIds.has(apiId)) {
      checkedApiIds.add(apiId);
      const apiPreset = getApiPresetById(apiId);
      if (!apiPreset) {
        results.push({
          status: 'warn',
          type: 'api',
          name: apiId,
          message: `变量更新「${varTask.name}」的API预设不存在，将回退到默认`
        });
      }
    }
  }

  // ═══════════════════════════════════════
  // 6. 检查摘要任务的数据源引用
  // ═══════════════════════════════════════
  if (preset.summaryTask?.update?.enabled) {
    // 检查摘要任务引用的参考条目
    for (const varName of preset.summaryTask.update.dataSource?.useReferences || []) {
      const ref = (preset.referencePool || []).find(r => r.varName === varName);
      if (!ref) {
        results.push({
          status: 'warn',
          type: 'reference',
          name: varName,
          message: `摘要任务引用的参考条目「${varName}」不存在于参考池`
        });
      }
    }

    // 检查摘要任务引用的任务输出
    for (const outputId of preset.summaryTask.update.dataSource?.useTaskOutputs || []) {
      const targetTask = (preset.tasks || []).find(t => t.id === outputId);
      if (!targetTask) {
        results.push({
          status: 'error',
          type: 'reference',
          name: outputId,
          message: `摘要任务引用的任务已被删除`
        });
      } else if (!targetTask.output?.entryKey) {
        results.push({
          status: 'warn',
          type: 'reference',
          name: targetTask.name,
          message: `摘要任务引用的任务「${targetTask.name}」未配置输出`
        });
      }
    }
  }

  return results;
}

/**
 * 创作者页 - 依赖检查区块
 */
function buildCreatorCheckSection(preset) {
  const content = mainDoc.createElement('div');

  if (!preset) {
    content.innerHTML = '<div class="at-text-muted">请先选择方案</div>';
    return buildSection({
      id: 'creator_check',
      title: '依赖检查',
      content: content,
      defaultCollapsed: true
    });
  }

  // 初始状态：显示加载提示
  const statusContainer = mainDoc.createElement('div');
  statusContainer.className = 'at-check-status';
  statusContainer.innerHTML = '<div class="at-text-muted">点击「刷新检查」开始检查</div>';
  content.appendChild(statusContainer);

  // 检查结果列表容器
  const resultList = mainDoc.createElement('div');
  resultList.className = 'at-check-results';
  resultList.style.marginTop = '12px';
  content.appendChild(resultList);

  // 刷新按钮
  const btnContainer = mainDoc.createElement('div');
  btnContainer.style.marginTop = '12px';

  const refreshBtn = buildButton({
    text: '刷新检查',
    onClick: async () => {
      // 显示加载状态
      statusContainer.innerHTML = '<div class="at-text-muted">正在检查...</div>';
      resultList.innerHTML = '';

      try {
        const results = await performDependencyCheck(preset);
        renderCheckResults(statusContainer, resultList, results);
      } catch (err) {
        statusContainer.innerHTML = `<div class="at-status-error">检查失败: ${err.message}</div>`;
        console.error('[AutoTask] Dependency check error:', err);
      }
    }
  });
  btnContainer.appendChild(refreshBtn);
  content.appendChild(btnContainer);

  // 自动执行首次检查（延迟执行，避免阻塞渲染）
  setTimeout(async () => {
    statusContainer.innerHTML = '<div class="at-text-muted">正在检查...</div>';
    try {
      const results = await performDependencyCheck(preset);
      renderCheckResults(statusContainer, resultList, results);
    } catch (err) {
      statusContainer.innerHTML = `<div class="at-status-error">检查失败: ${err.message}</div>`;
    }
  }, 100);

  return buildSection({
    id: 'creator_check',
    title: '依赖检查',
    content: content,
    defaultCollapsed: true
  });
}

/**
 * 渲染检查结果
 */
function renderCheckResults(statusContainer, resultList, results) {
  // 统计
  const okCount = results.filter(r => r.status === 'ok').length;
  const warnCount = results.filter(r => r.status === 'warn').length;
  const errorCount = results.filter(r => r.status === 'error').length;

  // 更新状态摘要
  if (results.length === 0) {
    statusContainer.innerHTML = '<div class="at-text-muted">无需检查的项目</div>';
  } else {
    const parts = [];
    if (okCount > 0) parts.push(`<span class="at-status-ok">✓ ${okCount}项正常</span>`);
    if (warnCount > 0) parts.push(`<span class="at-status-warn">⚠ ${warnCount}项警告</span>`);
    if (errorCount > 0) parts.push(`<span class="at-status-error">✗ ${errorCount}项缺失</span>`);

    statusContainer.innerHTML = `<div style="display: flex; gap: 16px; flex-wrap: wrap;">${parts.join('')}</div>`;
  }

  // 清空并渲染结果列表
  resultList.innerHTML = '';

  // 按状态排序：error > warn > ok
  const sortedResults = [...results].sort((a, b) => {
    const order = { error: 0, warn: 1, ok: 2 };
    return order[a.status] - order[b.status];
  });

  for (const result of sortedResults) {
    const item = mainDoc.createElement('div');
    item.style.cssText = `
      display: flex;
      align-items: flex-start;
      gap: 8px;
      padding: 6px 0;
      border-bottom: 1px solid var(--border-light);
    `;

    // 状态图标
    const icon = mainDoc.createElement('span');
    if (result.status === 'ok') {
      icon.className = 'at-status-ok';
      icon.textContent = '✓';
    } else if (result.status === 'warn') {
      icon.className = 'at-status-warn';
      icon.textContent = '⚠';
    } else {
      icon.className = 'at-status-error';
      icon.textContent = '✗';
    }
    item.appendChild(icon);

    // 消息
    const msg = mainDoc.createElement('span');
    msg.style.flex = '1';
    msg.textContent = result.message;
    item.appendChild(msg);

    // 类型标签
    const typeLabel = mainDoc.createElement('span');
    typeLabel.className = 'at-section-badge';
    typeLabel.style.fontSize = '11px';
    const typeMap = { prompt: '提示词', reference: '参考', api: 'API' };
    typeLabel.textContent = typeMap[result.type] || result.type;
    item.appendChild(typeLabel);

    resultList.appendChild(item);
  }

  // 如果没有结果
  if (results.length === 0) {
    const emptyHint = mainDoc.createElement('div');
    emptyHint.className = 'at-text-muted';
    emptyHint.style.textAlign = 'center';
    emptyHint.style.padding = '12px';
    emptyHint.textContent = '当前方案没有需要检查的依赖项';
    resultList.appendChild(emptyHint);
  }
}

