/**
 * 验证导入的配置结构
 * @param {Object} config - 待验证的配置
 * @returns {{valid: boolean, errors: string[]}}
 */
function validateImportedConfig(config) {
  const errors = [];

  // 基础结构检查
  if (!config || typeof config !== 'object') {
    errors.push('配置必须是一个对象');
    return { valid: false, errors };
  }

  if (!config.version) {
    errors.push('缺少版本号 (version)');
  }

  if (!Array.isArray(config.presets)) {
    errors.push('缺少方案列表 (presets) 或格式错误');
    return { valid: false, errors };
  }

  if (config.presets.length === 0) {
    errors.push('方案列表不能为空');
  }

  // 检查每个方案
  for (let i = 0; i < config.presets.length; i++) {
    const preset = config.presets[i];
    const prefix = `方案[${i}]`;

    if (!preset.id) {
      errors.push(`${prefix}: 缺少ID`);
    }
    if (!preset.name) {
      errors.push(`${prefix}: 缺少名称`);
    }
    if (!Array.isArray(preset.tasks)) {
      errors.push(`${prefix}: 任务列表格式错误`);
    }

    // 检查任务
    if (Array.isArray(preset.tasks)) {
      for (let j = 0; j < preset.tasks.length; j++) {
        const task = preset.tasks[j];
        const taskPrefix = `${prefix}.任务[${j}]`;

        if (!task.id) {
          errors.push(`${taskPrefix}: 缺少ID`);
        }
        if (!task.name) {
          errors.push(`${taskPrefix}: 缺少名称`);
        }
        if (!['worldbook_update', 'direct_output'].includes(task.taskType)) {
          errors.push(`${taskPrefix}: 无效的任务类型`);
        }
      }
    }
  }

  // 检查activePresetId
  if (config.activePresetId) {
    const found = config.presets.some(p => p.id === config.activePresetId);
    if (!found) {
      errors.push('activePresetId 指向的方案不存在');
    }
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

/**
 * 处理导入的配置（重置API预设引用）
 * @param {Object} config - 原始配置
 * @returns {{config: Object, resetCount: number, affectedTasks: string[]}}
 */
function processImportedConfig(config) {
  const affectedTasks = [];
  let resetCount = 0;

  // 深拷贝避免修改原对象
  const processed = deepClone(config);

  // 遍历所有方案
  for (const preset of processed.presets || []) {
    // 重置任务的API预设
    for (const task of preset.tasks || []) {
      if (task.apiPresetId) {
        affectedTasks.push(task.name);
        task.apiPresetId = null;
        resetCount++;
      }
    }

    // 重置摘要任务的API预设
    if (preset.summaryTask?.update?.apiPresetId) {
      preset.summaryTask.update.apiPresetId = null;
      resetCount++;
    }
    if (preset.summaryTask?.compress?.apiPresetId) {
      preset.summaryTask.compress.apiPresetId = null;
      resetCount++;
    }

    // ═══ 重置变量更新任务的API预设 ═══
    for (const varTask of preset.varUpdateTasks || []) {
      if (varTask.apiPresetId) {
        affectedTasks.push(varTask.name);
        varTask.apiPresetId = null;
        resetCount++;
      }
    }
  }

  return {
    config: processed,
    resetCount,
    affectedTasks: [...new Set(affectedTasks)] // 去重
  };
}

/**
 * 导出配置为JSON字符串
 */
function exportConfigToJson() {
  if (!configDraft) {
    throw new Error('配置未加载');
  }
  return JSON.stringify(configDraft, null, 2);
}

/**
 * 下载JSON文件
 */
function downloadJsonFile(jsonString, filename) {
  const blob = new Blob([jsonString], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const a = mainDoc.createElement('a');
  a.href = url;
  a.download = filename;
  a.style.display = 'none';
  mainDoc.body.appendChild(a);
  a.click();
  mainDoc.body.removeChild(a);

  URL.revokeObjectURL(url);
}

/**
 * 复制文本到剪贴板（兼容跨框架环境）  ← 新增这个函数
 * @param {string} text - 要复制的文本
 */
function copyToClipboard(text) {
  const textarea = mainDoc.createElement('textarea');
  textarea.value = text;
  textarea.style.cssText = 'position: fixed; left: -9999px; top: -9999px;';
  mainDoc.body.appendChild(textarea);

  textarea.focus();
  textarea.select();

  try {
    const success = mainDoc.execCommand('copy');
    if (!success) {
      throw new Error('execCommand 返回 false');
    }
  } finally {
    mainDoc.body.removeChild(textarea);
  }
}

/**
 * 创作者页 - 导入导出区块
 */
function buildCreatorExportSection() {
  const content = mainDoc.createElement('div');

  // ═══════════════════════════════════════
  // 导出部分
  // ═══════════════════════════════════════
  const exportSection = mainDoc.createElement('div');
  exportSection.style.marginBottom = '16px';

  const exportHeader = mainDoc.createElement('div');
  exportHeader.style.cssText = 'font-weight: 500; margin-bottom: 10px; color: var(--text-primary);';
  exportHeader.textContent = '导出配置';
  exportSection.appendChild(exportHeader);

  const exportHint = mainDoc.createElement('div');
  exportHint.className = 'at-text-muted';
  exportHint.style.cssText = 'font-size: 12px; margin-bottom: 10px;';
  exportHint.textContent = '导出整个TaskConfig配置（不包含API密钥等本地数据）';
  exportSection.appendChild(exportHint);

  // 导出按钮组
  const exportBtnGroup = mainDoc.createElement('div');
  exportBtnGroup.className = 'at-flex at-gap-sm';

  // 下载JSON文件
  exportBtnGroup.appendChild(buildButton({
    text: '下载JSON文件',
    onClick: () => {
      try {
        const json = exportConfigToJson();
        const timestamp = new Date().toISOString().slice(0, 10);
        const presetName = getActivePreset()?.name || 'config';
        const filename = `autotask_${presetName}_${timestamp}.json`;
        downloadJsonFile(json, filename);
        toastr.success('配置已导出');
      } catch (err) {
        toastr.error('导出失败: ' + err.message);
      }
    }
  }));

  // 复制到剪贴板
  exportBtnGroup.appendChild(buildButton({
    text: '复制到剪贴板',
    onClick: () => {
      try {
        const json = exportConfigToJson();
        copyToClipboard(json);
        toastr.success('已复制到剪贴板');
      } catch (err) {
        toastr.error('复制失败: ' + err.message);
      }
    }
  }));

  exportSection.appendChild(exportBtnGroup);
  content.appendChild(exportSection);

  content.appendChild(buildDivider());

  // ═══════════════════════════════════════
  // 导入部分
  // ═══════════════════════════════════════
  const importSection = mainDoc.createElement('div');

  const importHeader = mainDoc.createElement('div');
  importHeader.style.cssText = 'font-weight: 500; margin-bottom: 10px; color: var(--text-primary);';
  importHeader.textContent = '导入配置';
  importSection.appendChild(importHeader);

  const importHint = mainDoc.createElement('div');
  importHint.className = 'at-text-muted';
  importHint.style.cssText = 'font-size: 12px; margin-bottom: 10px;';
  importHint.textContent = '导入后所有API预设引用将被重置，需要重新配置';
  importSection.appendChild(importHint);

  // 文本输入区
  const textareaContainer = mainDoc.createElement('div');
  textareaContainer.className = 'at-form-group';

  const textarea = mainDoc.createElement('textarea');
  textarea.className = 'at-form-textarea';
  textarea.rows = 6;
  textarea.placeholder = '粘贴JSON配置内容...';
  textarea.style.fontFamily = 'monospace';
  textarea.style.fontSize = '12px';
  textareaContainer.appendChild(textarea);

  importSection.appendChild(textareaContainer);

  // 文件上传
  const fileInputContainer = mainDoc.createElement('div');
  fileInputContainer.style.marginBottom = '12px';

  const fileLabel = mainDoc.createElement('label');
  fileLabel.className = 'at-btn';
  fileLabel.style.cssText = 'display: inline-flex; align-items: center; gap: 6px; cursor: pointer;';
  fileLabel.innerHTML = '📁 选择JSON文件';

  const fileInput = mainDoc.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = '.json,application/json';
  fileInput.style.display = 'none';

  fileInput.addEventListener('change', (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      textarea.value = evt.target.result;
      toastr.info(`已加载文件: ${file.name}`);
    };
    reader.onerror = () => {
      toastr.error('文件读取失败');
    };
    reader.readAsText(file);

    // 清空input以便重复选择同一文件
    fileInput.value = '';
  });

  fileLabel.appendChild(fileInput);
  fileInputContainer.appendChild(fileLabel);

  // 当前文件名显示
  const fileNameDisplay = mainDoc.createElement('span');
  fileNameDisplay.className = 'at-text-muted';
  fileNameDisplay.style.marginLeft = '12px';
  fileInputContainer.appendChild(fileNameDisplay);

  importSection.appendChild(fileInputContainer);

  // 验证结果显示区
  const validationResult = mainDoc.createElement('div');
  validationResult.className = 'at-validation-result';
  validationResult.style.cssText = `
    margin-bottom: 12px;
    padding: 10px;
    border-radius: 4px;
    display: none;
    font-size: 13px;
  `;
  importSection.appendChild(validationResult);

  // 导入按钮组
  const importBtnGroup = mainDoc.createElement('div');
  importBtnGroup.className = 'at-flex at-gap-sm';

  // 验证按钮
  importBtnGroup.appendChild(buildButton({
    text: '验证配置',
    onClick: () => {
      const jsonText = textarea.value.trim();
      if (!jsonText) {
        toastr.warning('请先粘贴或上传配置');
        return;
      }

      try {
        const config = JSON.parse(jsonText);
        const { valid, errors } = validateImportedConfig(config);

        validationResult.style.display = 'block';

        if (valid) {
          // 预览处理结果
          const { resetCount, affectedTasks } = processImportedConfig(config);

          validationResult.style.background = 'rgba(92, 163, 146, 0.1)';
          validationResult.style.border = '1px solid var(--success)';

          let html = '<div class="at-status-ok" style="margin-bottom: 8px;">✓ 配置格式正确</div>';
          html += `<div>版本: ${config.version}</div>`;
          html += `<div>方案数: ${config.presets.length}</div>`;

          const totalTasks = config.presets.reduce((sum, p) => sum + (p.tasks?.length || 0), 0);
          html += `<div>任务数: ${totalTasks}</div>`;

          if (resetCount > 0) {
            html += `<div style="margin-top: 8px; color: var(--warning);">`;
            html += `⚠ 导入后将重置 ${resetCount} 个API预设引用`;
            if (affectedTasks.length > 0) {
              html += `<br>涉及任务: ${affectedTasks.slice(0, 5).join('、')}`;
              if (affectedTasks.length > 5) {
                html += ` 等${affectedTasks.length}个`;
              }
            }
            html += `</div>`;
          }

          validationResult.innerHTML = html;
        } else {
          validationResult.style.background = 'rgba(184, 106, 90, 0.1)';
          validationResult.style.border = '1px solid var(--error)';

          let html = '<div class="at-status-error" style="margin-bottom: 8px;">✗ 配置格式有误</div>';
          html += '<ul style="margin: 0; padding-left: 20px;">';
          for (const err of errors.slice(0, 10)) {
            html += `<li>${err}</li>`;
          }
          if (errors.length > 10) {
            html += `<li>...还有 ${errors.length - 10} 个错误</li>`;
          }
          html += '</ul>';

          validationResult.innerHTML = html;
        }
      } catch (err) {
        validationResult.style.display = 'block';
        validationResult.style.background = 'rgba(184, 106, 90, 0.1)';
        validationResult.style.border = '1px solid var(--error)';
        validationResult.innerHTML = `<div class="at-status-error">JSON解析失败: ${err.message}</div>`;
      }
    }
  }));

  // 导入按钮
  importBtnGroup.appendChild(buildButton({
    text: '确认导入',
    primary: true,
    onClick: async () => {
      const jsonText = textarea.value.trim();
      if (!jsonText) {
        toastr.warning('请先粘贴或上传配置');
        return;
      }

      try {
        const config = JSON.parse(jsonText);
        const { valid, errors } = validateImportedConfig(config);

        if (!valid) {
          toastr.error('配置格式有误，请先验证');
          return;
        }

        // 处理配置
        const { config: processed, resetCount, affectedTasks } = processImportedConfig(config);

        // 确认对话框
        let confirmMsg = '确定导入此配置吗？\n\n这将覆盖当前所有配置。';
        if (resetCount > 0) {
          confirmMsg += `\n\n⚠ ${resetCount} 个API预设引用将被重置。`;
        }

        const confirmed = await SillyTavern.callGenericPopup(
          confirmMsg,
          SillyTavern.POPUP_TYPE.CONFIRM
        );

        if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
          return;
        }

        // 执行导入
        configDraft = processed;

        // 设置当前编辑方案
        currentEditingPresetId = processed.activePresetId || processed.presets[0]?.id;

        // 标记需要保存
        markDirty();

        // 清空输入
        textarea.value = '';
        validationResult.style.display = 'none';

        // 提示信息
        let successMsg = '配置已导入！';
        if (affectedTasks.length > 0) {
          successMsg = `配置已导入！\n\n以下 ${affectedTasks.length} 个任务的API预设需要重新配置：\n${affectedTasks.slice(0, 5).join('、')}${affectedTasks.length > 5 ? '...' : ''}`;
        }

        await SillyTavern.callGenericPopup(
          successMsg,
          SillyTavern.POPUP_TYPE.TEXT
        );

        // 刷新页面
        renderPage('creator');

        toastr.success('请保存并应用配置');

      } catch (err) {
        toastr.error('导入失败: ' + err.message);
        console.error('[AutoTask] Import error:', err);
      }
    }
  }));

  importSection.appendChild(importBtnGroup);
  content.appendChild(importSection);

  return buildSection({
    id: 'creator_export',
    title: '导入导出',
    content: content,
    defaultCollapsed: true
  });
}

// ─────────────────────────────────────────────────────────────────
// 创作者页 - 保存按钮
// ─────────────────────────────────────────────────────────────────

/**
 * 创作者页 - 底部保存按钮
 */
function buildCreatorSaveButtons() {
  const container = mainDoc.createElement('div');
  container.className = 'at-save-buttons';  // 添加类名用于定位
  container.style.cssText = `
    position: sticky;
    bottom: -16px;
    background: var(--bg-primary);
    padding: 12px 0 16px 0;
    margin: 16px -16px -16px -16px;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding-left: 16px;
    padding-right: 16px;
  `;

  // 未保存提示（初始状态）
  if (isDirty) {
    const dirtyHint = mainDoc.createElement('span');
    dirtyHint.className = 'at-dirty-hint';  // 添加类名用于动态更新
    dirtyHint.style.cssText = `
      color: var(--warning);
      font-size: 12px;
      display: flex;
      align-items: center;
      margin-right: auto;
    `;
    dirtyHint.textContent = '● 有未保存的更改';
    container.appendChild(dirtyHint);
  }

  // 保存按钮
  container.appendChild(buildButton({
    text: '保存',
    onClick: async () => {
      await handleSave(false);
    }
  }));

  // 保存并应用按钮
  container.appendChild(buildButton({
    text: '保存并应用',
    primary: true,
    onClick: async () => {
      await handleSave(true);
    }
  }));

  return container;
}

/**
 * 处理保存操作
 */
async function handleSave(applyAfterSave) {
  try {
    // TODO: 执行依赖检查，显示问题（后续实现）

    // 保存配置
    await saveConfig(configDraft);
    isDirty = false;
    toastr.success('配置已保存');

    // 应用配置
    if (applyAfterSave) {
      await eventEmit('autotask_config_updated');
      toastr.success('配置已应用');
    }

    // 刷新页面更新状态
    renderPage('creator');

  } catch (err) {
    toastr.error('保存失败: ' + err.message);
    console.error('[AutoTask] Save error:', err);
  }
}

// ═══════════════════════════════════════════════════════════════
// Part 9: 面板生命周期
// ═══════════════════════════════════════════════════════════════

/**
 * 打开面板
 */
async function openPanel() {
  // 0. 检查是否已有面板（在主文档中查找）
  const existingOverlay = mainDoc.getElementById('at-overlay');
  if (existingOverlay) {
    console.log('[AutoTask] 面板已存在，移除旧面板');
    existingOverlay.remove();
  }

  // 1. 注入样式到主文档
  injectStyles();

  // 2. 加载数据
  try {
    let config = await loadConfig();

    // 配置不存在，询问是否创建
    if (!config) {
      const create = await SillyTavern.callGenericPopup(
        '未找到AutoTask配置，是否创建默认配置？',
        SillyTavern.POPUP_TYPE.CONFIRM
      );
      if (create === SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
        config = await createDefaultConfig();
        toastr.success('已创建默认配置');
      } else {
        return; // 用户取消，不打开面板
      }
    }

    configDraft = deepClone(config);
    apiPresetsDraft = loadApiPresets();

    // 设置当前编辑的方案
    currentEditingPresetId = config.activePresetId;

  } catch (err) {
    toastr.error('加载配置失败: ' + err.message);
    console.error('[AutoTask] Config load error:', err);
    return;
  }

  // 3. 重置状态
  isDirty = false;
  currentTab = 'home';
  expandedTaskId = null;

  // 4. 构建DOM并挂载到主文档body
  const overlay = buildOverlay();
  mainBody.appendChild(overlay);
  console.log('[AutoTask] DOM已挂载到主文档');

  // 5. 绑定事件
  attachEventHandlers();
  // ESC键监听绑定到主文档
  mainDoc.addEventListener('keydown', handleEscKey);

  // 6. 渲染首页
  renderPage('home');

  console.log('[AutoTask] 面板已打开');
}

/**
 * 关闭面板
 */
async function closePanel(force = false) {
  // 1. 检查未保存修改
  if (!force && isDirty) {
    const confirmed = await SillyTavern.callGenericPopup(
      '有未保存的更改，确定离开吗？',
      SillyTavern.POPUP_TYPE.CONFIRM
    );
    if (confirmed !== SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
      return; // 用户取消，保持面板打开
    }
  }

  // 2. 移除主文档上的ESC键监听
  mainDoc.removeEventListener('keydown', handleEscKey);

  // 3. 从主文档移除DOM
  mainDoc.getElementById('at-overlay')?.remove();

  // 4. 重置状态
  isDirty = false;
  configDraft = null;
  apiPresetsDraft = null;

  console.log('[AutoTask] 面板已关闭');
}

// ═══════════════════════════════════════════════════════════════
// Part 10: 主入口
// ═══════════════════════════════════════════════════════════════

// 注册按钮
replaceScriptButtons([{ name: 'AutoTask配置', visible: true }]);

// 监听按钮点击
eventOn(getButtonEvent('AutoTask配置'), async () => {
  // 防止重复打开（检查主文档）
  if (mainDoc.getElementById('at-overlay')) {
    console.log('[AutoTask] 面板已打开');
    return;
  }
  await openPanel();
});

console.log('[AutoTask] 配置面板脚本已加载');

